insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('rs02-mat1-quiz','v28:4b3aec3654b9c0eda0e42c1ba3fddcc22f419b62cbe8676ac7f827735b210b37','Matemática — 1º ano','quiz','1',ARRAY[]::text[],'4b3aec3654b9c0eda0e42c1ba3fddcc22f419b62cbe8676ac7f827735b210b37','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Faça uma marca para cada unidade dos dois números. Junte os grupos e conte cada marca uma vez."},{"itemId":"q2","text":"Conte em voz alta até o número da pergunta. Continue por mais um número, sem voltar ao anterior."},{"itemId":"q3","text":"Represente a quantidade inicial. Risque uma marca para cada unidade que será retirada e conte as que ficaram."}]},"id":"rs02-mat1-quiz","title":"Matemática — 1º ano","grade":"1º ano","subject":"Matemática","collection":{"id":"mat1","title":"Matemática — 1º ano"},"description":"Leia ou escute cada pergunta. Você pode usar dedos ou marcas para pensar nas contas.\n\nColeção demonstrativa do Studio 02. Aguarda homologação pedagógica e vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quanto é 3 + 2?","options":[{"label":"4","id":"o1"},{"label":"5","id":"o2"},{"label":"6","id":"o3"},{"label":"7","id":"o4"}],"correctOptionId":"o2","explanation":"Junte 3 marcas e mais 2. Contando todas, temos 5: 3 + 2 = 5."},{"id":"q2","prompt":"Qual número vem depois do 9?","options":[{"label":"8","id":"o1"},{"label":"11","id":"o2"},{"label":"10","id":"o3"},{"label":"7","id":"o4"}],"correctOptionId":"o3","explanation":"Na contagem, depois de 9 vem 10. Avance apenas um número."},{"id":"q3","prompt":"Quanto é 8 - 3?","options":[{"label":"4","id":"o1"},{"label":"5","id":"o2"},{"label":"6","id":"o3"},{"label":"7","id":"o4"}],"correctOptionId":"o2","explanation":"Comece com 8 marcas e retire 3. Restam 5: 8 − 3 = 5."}]}','4b3aec3654b9c0eda0e42c1ba3fddcc22f419b62cbe8676ac7f827735b210b37',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('rs02-mat1-memory','v28:0fdcb80bde454b8208429c5ba79bd74a5e898ada3afb79eaa5a7e248d084ac19','Matemática — 1º ano','memory','1',ARRAY[]::text[],'0fdcb80bde454b8208429c5ba79bd74a5e898ada3afb79eaa5a7e248d084ac19','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Resolva a conta com dedos ou marcas. Para somar, junte as quantidades; para subtrair, retire uma parte. Guarde na memória onde apareceram as cartas."},"id":"rs02-mat1-memory","title":"Matemática — 1º ano","grade":"1º ano","subject":"Matemática","collection":{"id":"mat1","title":"Matemática — 1º ano"},"description":"Vire duas cartas por vez e procure a conta e seu resultado.\n\nColeção demonstrativa do Studio 02. Aguarda homologação pedagógica e vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"memory","memoryMode":"relational","pairs":[{"id":"p1","left":{"label":"2 + 2"},"right":{"label":"4"}},{"id":"p2","left":{"label":"3 + 2"},"right":{"label":"5"}},{"id":"p3","left":{"label":"6 - 3"},"right":{"label":"3"}},{"id":"p4","left":{"label":"1 + 1"},"right":{"label":"2"}}]}','0fdcb80bde454b8208429c5ba79bd74a5e898ada3afb79eaa5a7e248d084ac19',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('rs02-mat1-association','v28:9546a6b0dc04b9fd8f3f60d58fc5cb97a7cd9279068751e2c26c616ab4eeae3c','Matemática — 1º ano','association','1',ARRAY[]::text[],'9546a6b0dc04b9fd8f3f60d58fc5cb97a7cd9279068751e2c26c616ab4eeae3c','{"schemaVersion":1,"id":"rs02-mat1-association","title":"Matemática — 1º ano","grade":"1º ano","subject":"Matemática","collection":{"id":"mat1","title":"Matemática — 1º ano"},"description":"Ligue cada conta ao seu resultado. Você pode usar dedos ou marcas para calcular.\n\nColeção demonstrativa do Studio 02. Aguarda homologação pedagógica e vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"2 + 2"},"right":{"label":"4"}},{"id":"p2","left":{"label":"3 + 2"},"right":{"label":"5"}},{"id":"p3","left":{"label":"6 - 3"},"right":{"label":"3"}},{"id":"p4","left":{"label":"1 + 1"},"right":{"label":"2"}}]}','9546a6b0dc04b9fd8f3f60d58fc5cb97a7cd9279068751e2c26c616ab4eeae3c',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('rs02-lp2-quiz','v28:c30de9589645be77146b64af5c144f329395bb75119180e05529ae224376a0e9','Língua Portuguesa — 2º ano','quiz','2',ARRAY[]::text[],'c30de9589645be77146b64af5c144f329395bb75119180e05529ae224376a0e9','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Diga BOLA devagar. Escute o primeiro som, sem precisar repetir a sílaba toda. Depois diga cada opção e compare esse começo."},{"itemId":"q2","text":"Leia cada opção pensando no que ela nomeia. Qual delas indica mais de um ser ou objeto?"},{"itemId":"q3","text":"Fale PÃO e cada opção em voz alta. Escute o final das palavras, mesmo que comecem com sons diferentes."}]},"id":"rs02-lp2-quiz","title":"Língua Portuguesa — 2º ano","grade":"2º ano","subject":"Língua Portuguesa","collection":{"id":"lp2","title":"Língua Portuguesa — 2º ano"},"description":"Leia ou escute as palavras antes de escolher. Cada pergunta pede observar uma coisa: o som inicial, o plural ou a rima.\n\nDemonstração derivada do Studio 02, com o primeiro enunciado esclarecido na versão 0.4.1. Aguarda homologação pedagógica e vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual palavra começa com o som da letra B, como BOLA?","options":[{"label":"Sapo","id":"o1"},{"label":"Boneca","id":"o2"},{"label":"Casa","id":"o3"},{"label":"Tatu","id":"o4"}],"correctOptionId":"o2","explanation":"BOLA e BONECA começam com o som /b/. Compare apenas o som inicial da letra B, não a sílaba inteira."},{"id":"q2","prompt":"Qual palavra está no plural?","options":[{"label":"Livro","id":"o1"},{"label":"Gato","id":"o2"},{"label":"Flores","id":"o3"},{"label":"Pato","id":"o4"}],"correctOptionId":"o3","explanation":"Flores é o plural de flor: indica mais de uma flor. As outras palavras apresentadas estão no singular."},{"id":"q3","prompt":"Qual palavra rima com PÃO?","options":[{"label":"Chão","id":"o1"},{"label":"Casa","id":"o2"},{"label":"Faca","id":"o3"},{"label":"Bolo","id":"o4"}],"correctOptionId":"o1","explanation":"PÃO e CHÃO rimam porque terminam com o mesmo som. Compare o final falado das palavras, não o começo."}]}','c30de9589645be77146b64af5c144f329395bb75119180e05529ae224376a0e9',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('rs02-lp2-memory','v28:572185dad75b34f74e6a93295c5c99103854574349f3cf08d34651384981590f','Língua Portuguesa — 2º ano','memory','2',ARRAY[]::text[],'572185dad75b34f74e6a93295c5c99103854574349f3cf08d34651384981590f','{"schemaVersion":1,"catalog":{"band":"EF2","area":"portugues","batch":"memoria-v25","objective":"Relacionar sílabas a palavras curtas, com apoio de imagens já existentes no acervo.","readingRequired":true,"visualSupport":[{"term":"BOLA","image":{"src":"rsplay-asset:8d0f9cf86938562ac7769208efec9fb0636f076a7ebcffbd72914849f3f7b233","alt":"Bola redonda com faixas claras."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026; substituir crédito Pillow antigo só nas ocorrências aceitas."},{"term":"GATO","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito geométrico/Pillow antigo apenas nas ocorrências aceitas."},{"term":"PATO","image":{"src":"rsplay-asset:beebfbea5d977c91de26c7168ce61378328c6c3cacfb7f609d821241e7e22aa0","alt":"Pato com bico largo e duas patas."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito geométrico/Pillow antigo apenas nas ocorrências aceitas."}]},"id":"rs02-lp2-memory","title":"Língua Portuguesa — 2º ano","grade":"2º ano","subject":"Língua Portuguesa","collection":{"id":"lp2","title":"Língua Portuguesa — 2º ano"},"description":"Junte as sílabas e procure a palavra inteira. As figuras ajudam nos pares de BOLA, GATO e PATO.","difficulty":"facil","bncc":[],"status":"draft","template":"memory","memoryMode":"relational","pairs":[{"id":"p1","left":{"label":"CA + SA"},"right":{"label":"CASA"}},{"id":"p2","left":{"label":"BO + LA"},"right":{"label":"BOLA","image":{"src":"rsplay-asset:8d0f9cf86938562ac7769208efec9fb0636f076a7ebcffbd72914849f3f7b233","alt":"Bola redonda com faixas claras."}}},{"id":"p3","left":{"label":"GA + TO"},"right":{"label":"GATO","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."}}},{"id":"p4","left":{"label":"PA + TO"},"right":{"label":"PATO","image":{"src":"rsplay-asset:beebfbea5d977c91de26c7168ce61378328c6c3cacfb7f609d821241e7e22aa0","alt":"Pato com bico largo e duas patas."}}}]}','572185dad75b34f74e6a93295c5c99103854574349f3cf08d34651384981590f',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('rs02-lp2-association','v28:a0de2fe6134254478810e10236f366f048a9f5bcb23e077782af218f4f95bca6','Língua Portuguesa — 2º ano','association','2',ARRAY[]::text[],'a0de2fe6134254478810e10236f366f048a9f5bcb23e077782af218f4f95bca6','{"schemaVersion":1,"id":"rs02-lp2-association","title":"Língua Portuguesa — 2º ano","grade":"2º ano","subject":"Língua Portuguesa","collection":{"id":"lp2","title":"Língua Portuguesa — 2º ano"},"description":"Diga as sílabas em voz alta, junte seus sons e ligue à palavra inteira. Um adulto pode ler com você.\n\nColeção demonstrativa do Studio 02. Aguarda homologação pedagógica e vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"CA + SA"},"right":{"label":"CASA"}},{"id":"p2","left":{"label":"BO + LA"},"right":{"label":"BOLA"}},{"id":"p3","left":{"label":"GA + TO"},"right":{"label":"GATO"}},{"id":"p4","left":{"label":"PA + TO"},"right":{"label":"PATO"}}]}','a0de2fe6134254478810e10236f366f048a9f5bcb23e077782af218f4f95bca6',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('demo-sequence','v28:064883b681aa4bea1e0a22bfd0479eac6078bf1f7fb65a60809ee0535928042a','Da semente à planta','sequence',null,ARRAY[]::text[],'064883b681aa4bea1e0a22bfd0479eac6078bf1f7fb65a60809ee0535928042a','{"schemaVersion":1,"id":"demo-sequence","title":"Da semente à planta","grade":"Demonstração","subject":"Laboratório de jogos","collection":{"id":"laboratorio","title":"Laboratório — novos modelos"},"description":"Ordene as ações desta história: plantamos uma semente na terra, depois regamos a terra e, alguns dias depois, observamos o broto. Esta ordem representa a história, não todas as formas de cultivar uma planta.","difficulty":"facil","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Plantar a semente","id":"s1"},{"label":"Regar a terra","id":"s2"},{"label":"Observar o broto","id":"s3"}]}','064883b681aa4bea1e0a22bfd0479eac6078bf1f7fb65a60809ee0535928042a',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('demo-classification','v28:eeb90cc184c52b7834ccb1eb616bb05dab66a1b0bc5f5465e15ab6110379dc9e','Frutas e animais','classification',null,ARRAY[]::text[],'eeb90cc184c52b7834ccb1eb616bb05dab66a1b0bc5f5465e15ab6110379dc9e','{"schemaVersion":1,"id":"demo-classification","title":"Frutas e animais","grade":"Demonstração","subject":"Laboratório de jogos","collection":{"id":"laboratorio","title":"Laboratório — novos modelos"},"description":"Classifique cada item como fruta ou animal.\n\nExemplo técnico demonstrativo, sem homologação pedagógica ou vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"classification","categories":[{"id":"fruta","label":"Frutas"},{"id":"animal","label":"Animais"}],"items":[{"label":"Maçã","id":"c1","categoryId":"fruta"},{"label":"Gato","id":"c2","categoryId":"animal"},{"label":"Banana","id":"c3","categoryId":"fruta"}]}','eeb90cc184c52b7834ccb1eb616bb05dab66a1b0bc5f5465e15ab6110379dc9e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('demo-puzzle','v28:8ead6ea8ecdc7ab444575575fc66b70ceefd2914baf7bc55e90491e1d21d2b5f','Reconstruindo a imagem','puzzle',null,ARRAY[]::text[],'8ead6ea8ecdc7ab444575575fc66b70ceefd2914baf7bc55e90491e1d21d2b5f','{"schemaVersion":1,"id":"demo-puzzle","title":"Reconstruindo a imagem","grade":"Demonstração","subject":"Laboratório de jogos","collection":{"id":"laboratorio","title":"Laboratório — novos modelos"},"description":"Monte as quatro peças para reconstruir a imagem.\n\nExemplo técnico demonstrativo, sem homologação pedagógica ou vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"puzzle","rows":2,"columns":2,"image":{"src":"rsplay-asset:15f9366396e9cc4462f0f1b9035569a0964e63a45ed7f9c78380809a1dc3a94c","alt":"Marca Raízes e Saberes: árvore com copa, tronco e raízes à esquerda; nome e lema à direita."},"pieces":[{"id":"p1","label":"Copa da árvore, parte superior esquerda","slot":0},{"id":"p2","label":"Nome da marca, parte superior direita","slot":1},{"id":"p3","label":"Raízes da árvore, parte inferior esquerda","slot":2},{"id":"p4","label":"Lema educacional, parte inferior direita","slot":3}]}','8ead6ea8ecdc7ab444575575fc66b70ceefd2914baf7bc55e90491e1d21d2b5f',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('demo-word-search','v28:4bcdf706d6e4c6ce8b779470934fa4d09b713def66a56a33d12fee7ba35bf55d','Palavras da natureza','word-search',null,ARRAY[]::text[],'4bcdf706d6e4c6ce8b779470934fa4d09b713def66a56a33d12fee7ba35bf55d','{"schemaVersion":1,"id":"demo-word-search","title":"Palavras da natureza","grade":"Demonstração","subject":"Laboratório de jogos","collection":{"id":"laboratorio","title":"Laboratório — novos modelos"},"description":"Encontre SOL, LUA, MAR e RIO na grade. Procure na horizontal para a direita ou na vertical para baixo.\n\nExemplo técnico demonstrativo, sem homologação pedagógica ou vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"word-search","grid":["ZWCVPVXL","KTLCUVRR","AXCOINIF","HSCGJKOT","ZOFEOKLA","MLJFLUAF","HUXAAZPP","DKVMARHS"],"words":[{"id":"w1","word":"SOL","row":3,"col":1,"direction":"vertical"},{"id":"w2","word":"LUA","row":5,"col":4,"direction":"horizontal"},{"id":"w3","word":"MAR","row":7,"col":3,"direction":"horizontal"},{"id":"w4","word":"RIO","row":1,"col":6,"direction":"vertical"}]}','4bcdf706d6e4c6ce8b779470934fa4d09b713def66a56a33d12fee7ba35bf55d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('demo-crossword','v28:b78db2655c9c50d39e410ec5e5f597fb385d568b7468463d6c061090836d9244','Pistas que se cruzam','crossword',null,ARRAY[]::text[],'b78db2655c9c50d39e410ec5e5f597fb385d568b7468463d6c061090836d9244','{"schemaVersion":1,"id":"demo-crossword","title":"Pistas que se cruzam","grade":"Demonstração","subject":"Laboratório de jogos","collection":{"id":"laboratorio","title":"Laboratório — novos modelos"},"description":"Resolva as duas pistas e preencha as palavras na grade. As letras dos cruzamentos devem servir às duas palavras.\n\nExemplo técnico demonstrativo, sem homologação pedagógica ou vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"crossword","rows":4,"columns":4,"entries":[{"id":"e1","clue":"Lugar onde podemos morar","answer":"CASA","row":1,"col":0,"direction":"across"},{"id":"e2","clue":"Parte rígida do esqueleto","answer":"OSSO","row":0,"col":2,"direction":"down"}]}','b78db2655c9c50d39e410ec5e5f597fb385d568b7468463d6c061090836d9244',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('demo-completion','v28:800c97391b62851f10f9496666a36ad542093e45222512d6804ce6325ca23465','Complete a descoberta','completion',null,ARRAY[]::text[],'800c97391b62851f10f9496666a36ad542093e45222512d6804ce6325ca23465','{"schemaVersion":1,"id":"demo-completion","title":"Complete a descoberta","grade":"Demonstração","subject":"Laboratório de jogos","collection":{"id":"laboratorio","title":"Laboratório — novos modelos"},"description":"Escolha uma opção para completar cada lacuna.\n\nExemplo técnico demonstrativo, sem homologação pedagógica ou vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"Escolha ÁGUA ou PEDRA: colocamos ","after":" no regador para molhar a terra.","answers":["água"],"options":[{"label":"água","id":"agua"},{"label":"pedra","id":"pedra"}]},{"id":"b2","before":"O contrário de noite é ","after":".","answers":["dia"],"options":[{"label":"dia","id":"dia"},{"label":"noite","id":"noite"}]}]}','800c97391b62851f10f9496666a36ad542093e45222512d6804ce6325ca23465',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('demo-trail','v28:adfbd0786d6e20da5639774fb335a3f3bbe184c00815a9f6008311bcb5c33ebc','Trilha das descobertas','trail',null,ARRAY[]::text[],'adfbd0786d6e20da5639774fb335a3f3bbe184c00815a9f6008311bcb5c33ebc','{"schemaVersion":1,"id":"demo-trail","title":"Trilha das descobertas","grade":"Demonstração","subject":"Laboratório de jogos","collection":{"id":"laboratorio","title":"Laboratório — novos modelos"},"description":"Escolha uma resposta em cada etapa da trilha.\n\nExemplo técnico demonstrativo, sem homologação pedagógica ou vínculo BNCC.","difficulty":"facil","bncc":[],"status":"draft","template":"trail","nodes":[{"id":"n1","prompt":"Quanto é 1 + 1?","options":[{"label":"2","id":"a"},{"label":"3","id":"b"}],"correctOptionId":"a","explanation":"Um mais um corresponde a dois. Conte dois objetos para conferir."},{"id":"n2","prompt":"Qual destes é um animal?","options":[{"label":"Pedra","id":"a"},{"label":"Gato","id":"b"}],"correctOptionId":"b","explanation":"O gato é um animal: ele se alimenta, respira e cresce. A pedra não é um ser vivo."}]}','adfbd0786d6e20da5639774fb335a3f3bbe184c00815a9f6008311bcb5c33ebc',true);
