insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EF1-ciencias-variedades-puzzle-01','v28:ed083e052975a9d86283d11ca2e0a62691053be960aa4747ce99c4808d04c157','Peixe inteiro em quatro partes','puzzle','1',ARRAY[]::text[],'ed083e052975a9d86283d11ca2e0a62691053be960aa4747ce99c4808d04c157','{"schemaVersion":1,"catalog":{"band":"EF1","area":"ciencias-variedades","batch":"editorial-EF1-ciencias-variedades","objective":"Reconstruir a forma de um peixe e localizar estruturas externas numa representação inteira.","readingRequired":true,"visualSupport":[{"term":"peixe","image":{"src":"rsplay-asset:5d957a2333a91f3dc21e0ea17e7e161adb3cbe8ae48170cd482ee60a2b47b3a5","alt":"Peixe com olho, cauda e nadadeiras desenhadas."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito geométrico/Pillow antigo apenas nas ocorrências aceitas."},{"term":"olho","image":{"src":"rsplay-asset:8a5a7bde0dc3242cf00ab17b7113711a71edb895a0c4ef6dc5b7851b063cab14","alt":"Peixe com seta apontando especificamente para o olho."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"cauda","image":{"src":"rsplay-asset:56b70021c271c564b561288767ec0d05710a83bb285d54d9f3d6e0b83c09b4e6","alt":"Peixe com seta apontando especificamente para a cauda, na extremidade oposta à cabeça."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"nadadeiras","image":{"src":"rsplay-asset:877f43dd477d0d38f4c80943769f4b60362fd12e3c491a1ca6998059aefae591","alt":"Detalhe esquemático de uma nadadeira, em forma de leque."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."}]},"id":"ed05-EF1-ciencias-variedades-puzzle-01","title":"Peixe inteiro em