insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EF1-ciencias-variedades-word-search-01','v28:a9bac593bef864ed330448f5e8eb70213c3e681acfbbf2ec134f34a057abc055','Perguntas sobre luz e céu','word-search','1',ARRAY[]::text[],'a9bac593bef864ed330448f5e8eb70213c3e681acfbbf2ec134f34a057abc055','{"schemaVersion":1,"catalog":{"band":"EF1","area":"ciencias-variedades","batch":"editorial-EF1-ciencias-variedades","objective":"Identificar palavras de observação do céu e da luz a partir de pistas curtas.","readingRequired":true,"visualSupport":[{"term":"LUZ","image":{"src":"rsplay-asset:b6fd813563d20aaeb5f1e1dacf3be5623b98d91de03a8025806fc73a847ee14f","alt":"Modelo simplificado de fonte pontual na lanterna, com feixe abrindo em linha reta até uma tela sem obstáculo."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"SOMBRA","image":{"src":"rsplay-asset:291d29d0f72e3f9a81d59dfcb43ecdd12e314b8d2f4dcbf4d895945eeef8c8d2","alt":"Modelo de fonte pontual: bloco dentro do feixe interrompe parte da luz; os limites da sombra seguem raios retos por suas bordas."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"DIA","image":{"src":"rsplay-asset:9795995327bd141a2adbebd288d806395e04d51e33a4320a3cc31eba29406fb9","alt":"Paisagem clara com Sol acima do horizonte."},"rights":"Ilustração original imagegen revisada para RS Play, 2026. Exemplo ilustrativo de observação do céu, não registro de data/local reais."},{"term":"LUA","image":{"src":"rsplay-asset:b3066f1cefcf3a27446ecb1b8d30b7a5357523cc614d8ffb411e216d6f3d608a","alt":"Lua ilustrada como disco cinza com marcas da superfície, sem rosto."},"rights":"Ilustração imagegen revisada para RS Play, 2026; Sol é representação simbólica, Lua não é mapa astronômico exato. Substituir crédito antigo só nas ocorrências aceitas."},{"term":"TELA","image":{"src":"rsplay-asset:fbf81307b4fe829205315ed1e1dbf5dfdde87083ef2bbe2657593256768b31b5","alt":"Tela plana branca em suporte, usada para observar a sombra no esquema."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"lanterna","image":{"src":"rsplay-asset:b6fd813563d20aaeb5f1e1dacf3be5623b98d91de03a8025806fc73a847ee14f","alt":"Modelo simplificado de fonte pontual na lanterna, com feixe abrindo em linha reta até uma tela sem obstáculo."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"tela","image":{"src":"rsplay-asset:b6fd813563d20aaeb5f1e1dacf3be5623b98d91de03a8025806fc73a847ee14f","alt":"Modelo simplificado de fonte pontual na lanterna, com feixe abrindo em linha reta até uma tela sem obstáculo."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"bloco","image":{"src":"rsplay-asset:291d29d0f72e3f9a81d59dfcb43ecdd12e314b8d2f4dcbf4d895945eeef8c8d2","alt":"Modelo de fonte pontual: bloco dentro do feixe interrompe parte da luz; os limites da sombra seguem raios retos por suas bordas."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"Sol","image":{"src":"rsplay-asset:4c513d9a1c12696e6b6725492d0cbee63273dc5cf85c9493a3ea547e1a40c093","alt":"Sol representado com círculo e raios."},"rights":"Ilustração original por código Pillow para RS Play, 2026. Sem imagens de terceiros. Fonte: ciencias/fontes/common.py."},{"term":"noite","image":{"src":"rsplay-asset:b664306918d8eb0f16ff046c0edbb156ac594f1f900091cc0449224e20e16c7e","alt":"Paisagem noturna com estrelas e Lua representadas."},"rights":"Ilustração original imagegen revisada para RS Play, 2026. Exemplo ilustrativo de observação do céu, não registro de data/local reais."}]},"id":"ed05-EF1-ciencias-variedades-word-search-01","title":"Perguntas sobre luz e céu","grade":"EF1","subject":"Ciências/Variedades","description":"Responda às cinco pistas e encontre as palavras na grade.\n\nProcure na horizontal para a direita ou na vertical para baixo. Escrevemos sem acentos na grade. Peça ajuda para ler, se precisar.","difficulty":"medio","bncc":[],"status":"draft","template":"word-search","grid":["ZRWOEILX","SSOMBRAP","NGPKDPFE","MZHXIHCK","QIDLAELT","EWXSNYUE","UMXQTWZL","LFYBJLUA"],"words":[{"id":"w1","word":"LUZ","clue":"O que sai da lanterna acesa e ilumina a tela?","image":{"src":"rsplay-asset:b6fd813563d20aaeb5f1e1dacf3be5623b98d91de03a8025806fc73a847ee14f","alt":"Modelo simplificado de fonte pontual na lanterna, com feixe abrindo em linha reta até uma tela sem obstáculo."},"row":4,"col":6,"direction":"vertical"},{"id":"w2","word":"SOMBRA","clue":"Que região mais escura surge quando o bloco impede parte da luz?","image":{"src":"rsplay-asset:291d29d0f72e3f9a81d59dfcb43ecdd12e314b8d2f4dcbf4d895945eeef8c8d2","alt":"Modelo de fonte pontual: bloco dentro do feixe interrompe parte da luz; os limites da sombra seguem raios retos por suas bordas."},"row":1,"col":1,"direction":"horizontal"},{"id":"w3","word":"DIA","clue":"Qual período está representado na cena clara com o Sol visível?","image":{"src":"rsplay-asset:9795995327bd141a2adbebd288d806395e04d51e33a4320a3cc31eba29406fb9","alt":"Paisagem clara com Sol acima do horizonte."},"row":2,"col":4,"direction":"vertical"},{"id":"w4","word":"LUA","clue":"Qual nome completa: a ___ pode ser vista à noite e também durante o dia?","image":{"src":"rsplay-asset:b3066f1cefcf3a27446ecb1b8d30b7a5357523cc614d8ffb411e216d6f3d608a","alt":"Lua ilustrada como disco cinza com marcas da superfície, sem rosto."},"row":7,"col":5,"direction":"horizontal"},{"id":"w5","word":"TELA","clue":"Em que parte plana do desenho aparece a sombra do bloco?","image":{"src":"rsplay-asset:fbf81307b4fe829205315ed1e1dbf5dfdde87083ef2bbe2657593256768b31b5","alt":"Tela plana branca em suporte, usada para observar a sombra no esquema."},"row":4,"col":7,"direction":"vertical"}]}','a9bac593bef864ed330448f5e8eb70213c3e681acfbbf2ec134f34a057abc055',true);
