insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EF1-portugues-sequence-01','v28:052df2b1dc5ee1d6584cd5d56e2de90815acb27f597cf744ea01f9247a046ab8','Palavras formam uma frase','sequence','1',ARRAY[]::text[],'052df2b1dc5ee1d6584cd5d56e2de90815acb27f597cf744ea01f9247a046ab8','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Compare os cartões com a cena. Experimente uma ordem e escute a frase inteira. Confira se as palavras dizem quem age, o que faz e o que usa.","afterCompletion":"A frase é: A menina abre o livro. “A menina” indica quem faz a ação; “abre” indica a ação; “o livro” indica o que ela abre. Os espaços separam as palavras."},"catalog":{"band":"EF1","area":"portugues","batch":"editorial-EF1-portugues","objective":"Organizar cinco palavras para expressar quem realiza uma ação e sobre qual objeto.","readingRequired":true,"visualSupport":[{"term":"cena de leitura","image":{"src":"rsplay-asset:dd6ba39ff290c711aa2a496d7880801f41aaf7c05a622486889dea849e0d2e54","alt":"Uma menina abre um livro perto de uma estante."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."}]},"id":"ed05-EF1-portugues-sequence-01","title":"Palavras formam uma frase","grade":"EF1","subject":"Português","description":"Monte uma frase sobre a cena de leitura.\n\nPense em quem faz a ação, no que essa pessoa faz e no objeto usado. Leia a frase montada para conferir se faz sentido. Um adulto pode ler os cartões com você.\n\nObserve os espaços entre as palavras.","difficulty":"facil","bncc":[],"status":"draft","template":"sequence","items":[{"label":"A","id":"s0"},{"label":"menina","id":"s1"},{"label":"abre","id":"s2"},{"label":"o","id":"s3"},{"label":"livro.","id":"s4"}]}','052df2b1dc5ee1d6584cd5d56e2de90815acb27f597cf744ea01f9247a046ab8',true);
