insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-ciencias-variedades-association-01','v28:08ed1512d3f41b6b2fc582967572fec47af5022572ed6ab3dab4b6adaacfcd13','O que usamos em cada parte?','association','infantil',ARRAY[]::text[],'08ed1512d3f41b6b2fc582967572fec47af5022572ed6ab3dab4b6adaacfcd13','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Observe uma roupa de cada vez. Imagine ou faça o gesto de vesti-la e compare com as partes do corpo mostradas.","afterCompletion":"Neste jogo, o chapéu é usado na cabeça, a luva na mão e a meia no pé. Os pares relacionam cada roupa à parte do corpo que ela cobre."},"catalog":{"band":"EI4","area":"ciencias-variedades","batch":"editorial-EI4-ciencias-variedades","objective":"Relacionar partes externas do corpo a peças de vestuário por seu uso habitual.","readingRequired":false,"visualSupport":[{"term":"Cabeça","image":{"src":"rsplay-asset:984114fc7ffe263e143ec2acca2ccd8676e4c9868524078904b1405ea74243b7","alt":"Cabeça de pessoa ilustrada, com cabelo e olhos."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Chapéu","image":{"src":"rsplay-asset:f7df127c6a45529eb698ad562be1b2e4ee37927e0d45c14cf388d469fd8529f3","alt":"Chapéu de aba larga."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Mão","image":{"src":"rsplay-asset:52605e1178be3c42a49286fac2b124a6fcaa0703b3a8b6d43408a94e45710754","alt":"Mão aberta com cinco dedos."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Luva","image":{"src":"rsplay-asset:de0222918d26ff91aee355a96a0e3843869bc8726814d53dbd46e3667ecb5e7a","alt":"Luva com cinco espaços para os dedos."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Pé","image":{"src":"rsplay-asset:2164717d7e9865874654d72a8736ed579af00c4d7f7fcf452ec1f2b02b3a2c5a","alt":"Pé visto de lado, com tornozelo, calcanhar e parte da frente dos dedos; a planta do pé aparece na borda inferior."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Meia","image":{"src":"rsplay-asset:deb64f9ea9d210e6b89f1d043a45efd362e3489522109c7b4806d8b0a7e20b2c","alt":"Meia com parte para o pé e abertura para a perna."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."}]},"id":"ed05-EI4-ciencias-variedades-association-01","title":"O que usamos em cada parte?","grade":"EI4","subject":"Ciências/Variedades","description":"Ligue cada peça de roupa à parte do corpo em que ela é usada.\n\nPara o adulto: nomeie cabeça, mão, pé, chapéu, luva e meia. Pergunte como cada roupa é usada, sem indicar os pares. A criança pode apontar enquanto você ajuda a ligar.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Cabeça","image":{"src":"rsplay-asset:984114fc7ffe263e143ec2acca2ccd8676e4c9868524078904b1405ea74243b7","alt":"Cabeça de pessoa ilustrada, com cabelo e olhos."}},"right":{"label":"Chapéu","image":{"src":"rsplay-asset:f7df127c6a45529eb698ad562be1b2e4ee37927e0d45c14cf388d469fd8529f3","alt":"Chapéu de aba larga."}}},{"id":"p2","left":{"label":"Mão","image":{"src":"rsplay-asset:52605e1178be3c42a49286fac2b124a6fcaa0703b3a8b6d43408a94e45710754","alt":"Mão aberta com cinco dedos."}},"right":{"label":"Luva","image":{"src":"rsplay-asset:de0222918d26ff91aee355a96a0e3843869bc8726814d53dbd46e3667ecb5e7a","alt":"Luva com cinco espaços para os dedos."}}},{"id":"p3","left":{"label":"Pé","image":{"src":"rsplay-asset:2164717d7e9865874654d72a8736ed579af00c4d7f7fcf452ec1f2b02b3a2c5a","alt":"Pé visto de lado, com tornozelo, calcanhar e parte da frente dos dedos; a planta do pé aparece na borda inferior."}},"right":{"label":"Meia","image":{"src":"rsplay-asset:deb64f9ea9d210e6b89f1d043a45efd362e3489522109c7b4806d8b0a7e20b2c","alt":"Meia com parte para o pé e abertura para a perna."}}}]}','08ed1512d3f41b6b2fc582967572fec47af5022572ed6ab3dab4b6adaacfcd13',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-ciencias-variedades-sequence-01','v28:1d55df58131f70459fe66d65db3c46285d289b612ffe66868c126aa0926dd54b','Uma flor se abre','sequence','infantil',ARRAY[]::text[],'1d55df58131f70459fe66d65db3c46285d289b612ffe66868c126aa0926dd54b','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Olhe as pétalas em cada figura. Compare quanto elas já se abriram e veja qual imagem pode vir depois de outra.","afterCompletion":"A sequência começa com o botão fechado, passa pela flor se abrindo e termina com a flor aberta. As figuras representam a mudança da mesma flor ao longo do tempo."},"catalog":{"band":"EI4","area":"ciencias-variedades","batch":"editorial-EI4-ciencias-variedades","objective":"Ordenar três observações visuais da abertura de uma flor, sem confundir com o ciclo completo da planta.","readingRequired":false,"visualSupport":[{"term":"Botão fechado","image":{"src":"rsplay-asset:2669d0f1a30cbb3124c0b80d9d479dd16bbf305d11b656d255af93bb335f6966","alt":"Botão de flor ainda fechado na ponta de uma planta."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Flor começando a abrir","image":{"src":"rsplay-asset:efcc064f8d9abf435f13f1edde673ab2a4167b2f29ec2684c93b3260711dc0ed","alt":"A mesma planta, com pétalas começando a se abrir."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Flor aberta","image":{"src":"rsplay-asset:5ef88806c9289bb459ba617e393a5708d463633ea68f1ccb9542fe8447803aac","alt":"A mesma planta, com flor aberta, folhas e caule."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"flor","image":{"src":"rsplay-asset:5ef88806c9289bb459ba617e393a5708d463633ea68f1ccb9542fe8447803aac","alt":"A mesma planta, com flor aberta, folhas e caule."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"botão","image":{"src":"rsplay-asset:2669d0f1a30cbb3124c0b80d9d479dd16bbf305d11b656d255af93bb335f6966","alt":"Botão de flor ainda fechado na ponta de uma planta."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"planta","image":{"src":"rsplay-asset:5ef88806c9289bb459ba617e393a5708d463633ea68f1ccb9542fe8447803aac","alt":"A mesma planta, com flor aberta, folhas e caule."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."}]},"id":"ed05-EI4-ciencias-variedades-sequence-01","title":"Uma flor se abre","grade":"EI4","subject":"Ciências/Variedades","description":"As figuras mostram a mesma flor em momentos diferentes.\n\nColoque as figuras na ordem em que a flor se abre. Observe o que muda entre uma figura e outra.\n\nPara o adulto: apresente as figuras e ajude a criança a compará-las, sem indicar a ordem.","difficulty":"facil","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Botão fechado","image":{"src":"rsplay-asset:2669d0f1a30cbb3124c0b80d9d479dd16bbf305d11b656d255af93bb335f6966","alt":"Botão de flor ainda fechado na ponta de uma planta."},"id":"s1"},{"label":"Flor começando a abrir","image":{"src":"rsplay-asset:efcc064f8d9abf435f13f1edde673ab2a4167b2f29ec2684c93b3260711dc0ed","alt":"A mesma planta, com pétalas começando a se abrir."},"id":"s2"},{"label":"Flor aberta","image":{"src":"rsplay-asset:5ef88806c9289bb459ba617e393a5708d463633ea68f1ccb9542fe8447803aac","alt":"A mesma planta, com flor aberta, folhas e caule."},"id":"s3"}]}','1d55df58131f70459fe66d65db3c46285d