insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-matematica-sequence-01','v28:2efa15077f4d79872dca4d99cf453d8a62dff8d5f3ed27c45df0bac1423c4c86','Do menor ao maior','sequence','infantil',ARRAY[]::text[],'2efa15077f4d79872dca4d99cf453d8a62dff8d5f3ed27c45df0bac1423c4c86','{"schemaVersion":1,"catalog":{"band":"EI4","area":"matematica","batch":"editorial-EI4-matematica","objective":"Ordenar três objetos da mesma forma por tamanho.","readingRequired":false,"visualSupport":[{"term":"Pequeno","image":{"src":"rsplay-asset:03ee6cec5469f43aa6825189ef297d28c9197e67abbc3622932bca933364aeed","alt":"Círculo de tamanho pequeno nesta comparação."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"Médio","image":{"src":"rsplay-asset:69c4ebad939026a75fa96c57168946cb5ead3481491e2dcf0d4b7e943d04be74","alt":"Círculo de tamanho médio nesta comparação."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"Grande","image":{"src":"rsplay-asset:b3c365cd4ff300da57aeb86d5e467a4d2aac1047907137d14a18e6d11d2a2d96","alt":"Círculo de tamanho grande nesta comparação."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."}]},"id":"ed05-EI4-matematica-sequence-01","title":"Do menor ao maior","grade":"EI4","subject":"Matemática","description":"Coloque primeiro o menor círculo, depois o do meio e, por último, o maior.\n\nPara o adulto: leia o pedido. Todos os cartões têm o mesmo tamanho; a criança compara o tamanho dos círculos, sem precisar ler.","difficulty":"facil","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Pequeno","image":{"src":"rsplay-asset:03ee6cec5469f43aa6825189ef297d28c9197e67abbc3622932bca933364aeed","alt":"Círculo de tamanho pequeno nesta comparação."},"id":"s1"},{"label":"Médio","image":{"src":"rsplay-asset:69c4ebad939026a75fa96c57168946cb5ead3481491e2dcf0d4b7e943d04be74","alt":"Círculo de tamanho médio nesta comparação."},"id":"s2"},{"label":"Grande","image":{"src":"rsplay-asset:b3c365cd4ff300da57aeb86d5e467a4d2aac1047907137d14a18e6d11d2a2d96","alt":"Círculo de tamanho grande nesta comparação."},"id":"s3"}]}','2efa15077f4d79872dca4d99cf453d8a62dff8d5f3ed27c45df0bac1423c4c86',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-matematica-classification-01','v28:a5dca598872b25d3c0c1f6325a8a7b8ad1119d6ae8c46dd6f85d0bbe29019d6d','Com pontas ou sem pontas','classification','infantil',ARRAY[]::text[],'a5dca598872b25d3c0c1f6325a8a7b8ad1119d6ae8c46dd6f85d0bbe29019d6d','{"schemaVersion":1,"catalog":{"band":"EI4","area":"matematica","batch":"editorial-EI4-matematica","objective":"Separar contornos pela presença de cantos visíveis.","readingRequired":false,"visualSupport":[{"term":"Com pontas","image":{"src":"rsplay-asset:11101fbdac65ec98ad272a0f55d087cfa5cf5e0d49f1e8a8ea7484550ee67457","alt":"Contorno triangular com três cantos."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"Sem pontas","image":{"src":"rsplay-asset:0d784274860ebd0ce904c3896b4e8c9a887b9163127f09eb9d2b67bba736b7f6","alt":"Contorno circular, sem pontas."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."}]},"id":"ed05-EI4-matematica-classification-01","title":"Com pontas ou sem pontas","grade":"EI4","subject":"Matemática","description":"Separe as figuras: de um lado, as que têm pontas; do outro, as que não têm pontas.\n\nPara o adulto: mostre os exemplos de cada grupo. Ao apontar os destinos, diga “tem pontas” ou “não tem pontas”. A criança move as figuras, sem precisar ler os rótulos.","difficulty":"facil","bncc":[],"status":"draft","template":"classification","categories":[{"id":"com","label":"Com pontas"},{"id":"sem","label":"Sem pontas"}],"items":[{"label":"Triângulo","image":{"src":"rsplay-asset:11101fbdac65ec98ad272a0f55d087cfa5cf5e0d49f1e8a8ea7484550ee67457","alt":"Contorno triangular com três cantos."},"id":"c1","categoryId":"com"},{"label":"Quadrado","image":{"src":"rsplay-asset:65253ba9218568536bc657790345bdcfcf230dc04a6db2fb2e620a982c6383b9","alt":"Contorno quadrado com quatro cantos."},"id":"c2","categoryId":"com"},{"label":"Círculo","image":{"src":"rsplay-asset:0d784274860ebd0ce904c3896b4e8c9a887b9163127f09eb9d2b67bba736b7f6","alt":"Contorno circular, sem pontas."},"id":"c3","categoryId":"sem"},{"label":"Oval","image":{"src":"rsplay-asset:45cbfd9b0ae6f3ceab94b3f3dddaa4a14bba41eaa42a1762904ca1c5b8a696f4","alt":"Contorno oval, mais largo do que alto, sem pontas."},"id":"c4","categoryId":"sem"}]}','a5dca598872b25d3c0c1f6325a8a7b8ad1119d6ae8c46dd6f85d0bbe29019d6d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-matematica-puzzle-01','v28:88da6818a881de213afd72d91d7578bfc01234d5d024e175a403860ca8f296c2','Montar uma casa de formas','puzzle','infantil',ARRAY[]::text[],'88da6818a881de213afd72d91d7578bfc01234d5d024e175a403860ca8f296c2','{"schemaVersion":1,"catalog":{"band":"EI4","area":"matematica","batch":"editorial-EI4-matematica","objective":"Reconhecer partes e formas em uma composição montada.","readingRequired":false,"visualSupport":[{"term":"Casa de formas","image":{"src":"rsplay-asset:f62018aee1d3f135bcc7b15fd94fc6a8209191a0c861ebe5facf028c4d09e843","alt":"Casa esquemática: telhado triangular, corpo retangular e janela circular."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."}]},"id":"ed05-EI4-matematica-puzzle-01","title":"Montar uma casa de formas","grade":"EI4","subject":"Matemática","description":"Monte as quatro peças.\n\nPara o adulto: depois da montagem, peça que a criança aponte a janela redonda e o telhado com pontas. Aceite que mostre ou descreva, sem exigir nomes técnicos ou leitura.","difficulty":"facil","bncc":[],"status":"draft","template":"puzzle","rows":2,"columns":2,"image":{"src":"rsplay-asset:f62018aee1d3f135bcc7b15fd94fc6a8209191a0c861ebe5facf028c4d09e843","alt":"Casa esquemática: telhado triangular, corpo retangular e janela circular."},"pieces":[{"id":"p0","label":"Peça 1","slot":0},{"id":"p1","label":"Peça 2","slot":1},{"id":"p2","label":"Peça 3","slot":2},{"id":"p3","label":"Peça 4","slot":3}]}','88da6818a881de213afd72d91d7578bfc01234d5d024e175a403860ca8f296c2',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-matematica-word-search-01','v28:ca860dfe290099667a5b6a3fb21c09f578aa1b6d461de51695a19ae900359f14','Quatro posições com modelo','word-search','infantil',ARRAY[]::text[],'ca860dfe290099667a5b6a3fb21c09f578aa1b6d461de51695a19ae900359f14','{"schemaVersion":1,"catalog":{"band":"EI4","area":"matematica","batch":"editorial-EI4-matematica","objective":"Explorar modelos escritos de relações espaciais já nomeadas oralmente.","readingRequired":false,"visualSupport":[{"term":"CIMA","image":{"src":"rsplay-asset:234c98d9367d6d7e9248d6c74c1605cb12100c31421b6f7c7aacbdf9b83231d1","alt":"Cena de posição cima, acompanhada do modelo completo CIMA."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"BAIXO","image":{"src":"rsplay-asset:b1d93b492f76af30eb66d2ad5ec289c9fd1506978b516b5fd5578de88203f69c","alt":"Cena de posição baixo, acompanhada do modelo completo BAIXO."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"PERTO","image":{"src":"rsplay-asset:7f63006f0f2f689d755aa39e16c5d0e3e4180fb09224cee4c78d46d6fe592471","alt":"Cena de posição perto, acompanhada do modelo completo PERTO."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"LONGE","image":{"src":"rsplay-asset:2e9c8e653f219a2144c075cafaf5a5f4be2d11b2346920af5916164714c36f9b","alt":"Cena de posição longe, acompanhada do modelo completo LONGE."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."}]},"id":"ed05-EI4-matematica-word-search-01","title":"Quatro posições com modelo","grade":"EI4","subject":"Matemática","description":"Procure as palavras na grade com a ajuda de um adulto. Compare as letras com os modelos: CIMA, BAIXO, PERTO e LONGE.\n\nPara o adulto: mostre as cenas e leia cada palavra-modelo. Procurem na horizontal para a direita ou na vertical para baixo, comparando letra por letra. Não avalie leitura, escrita ou rapidez.","difficulty":"facil","bncc":[],"status":"draft","template":"word-search","grid":["OBAIXO","OPFJDB","VEPPWC","KRJZJI","ZTUQHM","LONGEA"],"words":[{"id":"w0","word":"CIMA","clue":"Adulto: nomeie a cena e mostre o modelo CIMA.","image":{"src":"rsplay-asset:234c98d9367d6d7e9248d6c74c1605cb12100c31421b6f7c7aacbdf9b83231d1","alt":"Cena de posição cima, acompanhada do modelo completo CIMA."},"row":2,"col":5,"direction":"vertical"},{"id":"w1","word":"BAIXO","clue":"Adulto: nomeie a cena e mostre o modelo BAIXO.","image":{"src":"rsplay-asset:b1d93b492f76af30eb66d2ad5ec289c9fd1506978b516b5fd5578de88203f69c","alt":"Cena de posição baixo, acompanhada do modelo completo BAIXO."},"row":0,"col":1,"direction":"horizontal"},{"id":"w2","word":"PERTO","clue":"Adulto: nomeie a cena e mostre o modelo PERTO.","image":{"src":"rsplay-asset:7f63006f0f2f689d755aa39e16c5d0e3e4180fb09224cee4c78d46d6fe592471","alt":"Cena de posição perto, acompanhada do modelo completo PERTO."},"row":1,"col":1,"direction":"vertical"},{"id":"w3","word":"LONGE","clue":"Adulto: nomeie a cena e mostre o modelo LONGE.","image":{"src":"rsplay-asset:2e9c8e653f219a2144c075cafaf5a5f4be2d11b2346920af5916164714c36f9b","alt":"Cena de posição longe, acompanhada do modelo completo LONGE."},"row":5,"col":0,"direction":"horizontal"}]}','ca860dfe290099667a5b6a3fb21c09f578aa1b6d461de51695a19ae900359f14',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-matematica-crossword-01','v28:d7f63518ff77416b265be088ea03bbc7fcee0b5e4a315c8bd6e92b05f4132da8','Objetos com modelos completos','crossword','infantil',ARRAY[]::text[],'d7f63518ff77416b265be088ea03bbc7fcee0b5e4a315c8bd6e92b05f4132da8','{"schemaVersion":1,"catalog":{"band":"EI4","area":"matematica","batch":"editorial-EI4-matematica","objective":"Relacionar objetos familiares e modelos escritos numa exploração visual mediada.","readingRequired":false,"visualSupport":[{"term":"BOLA","image":{"src":"rsplay-asset:276402307d8b195aaae9b57a564624ae452958fa96cbb50a5c4478fb356560d7","alt":"Bola com a palavra-modelo completa BOLA."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"CUBO","image":{"src":"rsplay-asset:288ccab24391b711ae4e916ecfeead4f01707090a2da75bdd4299c96ea8b9d0f","alt":"Cubo com a palavra-modelo completa CUBO."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"CONE","image":{"src":"rsplay-asset:e995c02c80291be013cf2461400f8ff7c602d52c376c334175ec199eaf274426","alt":"Cone com a palavra-modelo completa CONE."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."}]},"id":"ed05-EI4-matematica-crossword-01","title":"Objetos com modelos completos","grade":"EI4","subject":"Matemática","description":"Aponte o objeto e compare as letras com o modelo.\n\nPara o adulto: mostre BOLA, CUBO e CONE com suas imagens. Demonstre a direção das casas. Preencha ou ajude a selecionar as letras, sem cobrar escrita ou leitura autônoma.","difficulty":"facil","bncc":[],"status":"draft","template":"crossword","rows":5,"columns":5,"entries":[{"id":"e1","clue":"A figura redonda é a BOLA. Compare com o modelo BOLA.","answer":"BOLA","row":3,"col":1,"direction":"across"},{"id":"e2","clue":"Este bloco é o CUBO. Compare com o modelo CUBO.","answer":"CUBO","row":1,"col":1,"direction":"down"},{"id":"e3","clue":"A figura com ponta é o CONE. Compare com o modelo CONE.","answer":"CONE","row":1,"col":1,"direction":"across"}]}','d7f63518ff77416b265be088ea03bbc7fcee0b5e4a315c8bd6e92b05f4132da8',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-matematica-completion-01','v28:6f9489bc9531d8c11848a467ecae89218919ba4c5b71efd4924832311752f9f8','Qual figura vem agora?','completion','infantil',ARRAY[]::text[],'6f9489bc9531d8c11848a467ecae89218919ba4c5b71efd4924832311752f9f8','{"schemaVersion":1,"catalog":{"band":"EI4","area":"matematica","batch":"editorial-EI4-matematica","objective":"Continuar uma alternância visual AB com apoio oral.","readingRequired":false,"visualSupport":[{"term":"Padrão 1","image":{"src":"rsplay-asset:c26bdb789ccd43d95330623bba08e1ed7966d504f1294883d9601bdf8894891b","alt":"Três figuras alternadas e uma lacuna: círculo, quadrado, círculo."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"Padrão 2","image":{"src":"rsplay-asset:e7ae5d5f2d1827353e7cb669da2987365c0b8ab78d52b167204181cefaa224a9","alt":"Três figuras alternadas e uma lacuna: triângulo, círculo, triângulo."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"Padrão 3","image":{"src":"rsplay-asset:ea4565e257466945a66f4bbbb1681a2c7db21916f246ef5cbfb9df21e8dd1493","alt":"Três figuras alternadas e uma lacuna: quadrado, triângulo, quadrado."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."}]},"id":"ed05-EI4-matematica-completion-01","title":"Qual figura vem agora?","grade":"EI4","subject":"Matemática","description":"Olhe as três figuras. Escolha a figura que continua a repetição.\n\nPara o adulto: aponte as três figuras de cada padrão e diga seus nomes em ritmo. Mantenha os modelos ilustrados visíveis. Não peça digitação.","difficulty":"facil","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"Padrão 1: depois das três figuras vem ","after":".","answers":["Quadrado"],"options":[{"label":"Círculo","image":{"src":"rsplay-asset:0d784274860ebd0ce904c3896b4e8c9a887b9163127f09eb9d2b67bba736b7f6","alt":"Contorno circular, sem pontas."},"id":"b1-o1"},{"label":"Quadrado","image":{"src":"rsplay-asset:65253ba9218568536bc657790345bdcfcf230dc04a6db2fb2e620a982c6383b9","alt":"Contorno quadrado com quatro cantos."},"id":"b1-o2"}]},{"id":"b2","before":"Padrão 2: depois das três figuras vem ","after":".","answers":["Círculo"],"options":[{"label":"Círculo","image":{"src":"rsplay-asset:0d784274860ebd0ce904c3896b4e8c9a887b9163127f09eb9d2b67bba736b7f6","alt":"Contorno circular, sem pontas."},"id":"b2-o1"},{"label":"Triângulo","image":{"src":"rsplay-asset:11101fbdac65ec98ad272a0f55d087cfa5cf5e0d49f1e8a8ea7484550ee67457","alt":"Contorno triangular com três cantos."},"id":"b2-o2"}]},{"id":"b3","before":"Padrão 3: depois das três figuras vem ","after":".","answers":["Triângulo"],"options":[{"label":"Quadrado","image":{"src":"rsplay-asset:65253ba9218568536bc657790345bdcfcf230dc04a6db2fb2e620a982c6383b9","alt":"Contorno quadrado com quatro cantos."},"id":"b3-o1"},{"label":"Triângulo","image":{"src":"rsplay-asset:11101fbdac65ec98ad272a0f55d087cfa5cf5e0d49f1e8a8ea7484550ee67457","alt":"Contorno triangular com três cantos."},"id":"b3-o2"}]}]}','6f9489bc9531d8c11848a467ecae89218919ba4c5b71efd4924832311752f9f8',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-matematica-trail-01','v28:28b8c44c4c7fb3d8e2fe174cba33f2484d62f9e0db51f4c24be8f95e01ef9b84','Passeio das posições','trail','infantil',ARRAY[]::text[],'28b8c44c4c7fb3d8e2fe174cba33f2484d62f9e0db51f4c24be8f95e01ef9b84','{"schemaVersion":1,"catalog":{"band":"EI4","area":"matematica","batch":"editorial-EI4-matematica","objective":"Distinguir acima, abaixo e perto em comparações visuais de posição.","readingRequired":false,"visualSupport":[{"term":"CIMA","image":{"src":"rsplay-asset:234c98d9367d6d7e9248d6c74c1605cb12100c31421b6f7c7aacbdf9b83231d1","alt":"Cena de posição cima, acompanhada do modelo completo CIMA."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"BAIXO","image":{"src":"rsplay-asset:b1d93b492f76af30eb66d2ad5ec289c9fd1506978b516b5fd5578de88203f69c","alt":"Cena de posição baixo, acompanhada do modelo completo BAIXO."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"PERTO","image":{"src":"rsplay-asset:7f63006f0f2f689d755aa39e16c5d0e3e4180fb09224cee4c78d46d6fe592471","alt":"Cena de posição perto, acompanhada do modelo completo PERTO."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."},{"term":"LONGE","image":{"src":"rsplay-asset:2e9c8e653f219a2144c075cafaf5a5f4be2d11b2346920af5916164714c36f9b","alt":"Cena de posição longe, acompanhada do modelo completo LONGE."},"rights":"Diagrama matemático original criado para RS Play por código Pillow; fonte incluída em bloco2/fontes. Sem imagens de terceiros."}]},"id":"ed05-EI4-matematica-trail-01","title":"Passeio das posições","grade":"EI4","subject":"Matemática","description":"Ouça o pedido e escolha a imagem.\n\nPara o adulto: leia cada pedido e nomeie o objeto de referência. Refaça o gesto no espaço, se necessário. Não exija leitura de palavras nem números.","difficulty":"facil","bncc":[],"status":"draft","template":"trail","nodes":[{"id":"t1","prompt":"Em qual cena a bola está acima da linha?","options":[{"label":"Cena A","image":{"src":"rsplay-asset:b1d93b492f76af30eb66d2ad5ec289c9fd1506978b516b5fd5578de88203f69c","alt":"Cena de posição baixo, acompanhada do modelo completo BAIXO."},"id":"t1-o1"},{"label":"Cena B","image":{"src":"rsplay-asset:234c98d9367d6d7e9248d6c74c1605cb12100c31421b6f7c7aacbdf9b83231d1","alt":"Cena de posição cima, acompanhada do modelo completo CIMA."},"id":"t1-o2"}],"correctOptionId":"t1-o2","explanation":"Na cena B, a bola está acima da linha."},{"id":"t2","prompt":"Em qual cena a bola está abaixo da linha?","options":[{"label":"Cena A","image":{"src":"rsplay-asset:b1d93b492f76af30eb66d2ad5ec289c9fd1506978b516b5fd5578de88203f69c","alt":"Cena de posição baixo, acompanhada do modelo completo BAIXO."},"id":"t2-o1"},{"label":"Cena B","image":{"src":"rsplay-asset:234c98d9367d6d7e9248d6c74c1605cb12100c31421b6f7c7aacbdf9b83231d1","alt":"Cena de posição cima, acompanhada do modelo completo CIMA."},"id":"t2-o2"}],"correctOptionId":"t2-o1","explanation":"Na cena A, a bola está abaixo da linha."},{"id":"t3","prompt":"Em qual cena a bola está mais perto da caixa?","options":[{"label":"Cena A","image":{"src":"rsplay-asset:2e9c8e653f219a2144c075cafaf5a5f4be2d11b2346920af5916164714c36f9b","alt":"Cena de posição longe, acompanhada do modelo completo LONGE."},"id":"t3-o1"},{"label":"Cena B","image":{"src":"rsplay-asset:7f63006f0f2f689d755aa39e16c5d0e3e4180fb09224cee4c78d46d6fe592471","alt":"Cena de posição perto, acompanhada do modelo completo PERTO."},"id":"t3-o2"}],"correctOptionId":"t3-o2","explanation":"Na cena B, a distância entre a bola e a caixa é menor."}]}','28b8c44c4c7fb3d8e2fe174cba33f2484d62f9e0db51f4c24be8f95e01ef9b84',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI4-portugues-quiz-01','v28:be01fe49f3d26e13453663152a181eb35a8f49f5969affd5c2786563c5f27acb','O livro de Beto','quiz','infantil',ARRAY[]::text[],'be01fe49f3d26e13453663152a181eb35a8f49f5969affd5c2786563c5f27acb','{"schemaVersion":1,"catalog":{"band":"EI4","area":"portugues","batch":"editorial-EI4-portugues","objective":"Reconhecer personagem, objeto e imagem mencionados em uma história ouvida.","readingRequired":false,"visualSupport":[{"term":"Beto","image":{"src":"rsplay-asset:33555565b74f48237067eeb7946b9f9f8ea59a06cc1eafaae584bb941facad74","alt":"Beto com roupa roxa, braços e pernas visíveis."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"O gato","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Um copo","image":{"src":"rsplay-asset:85fb1d67b8e89db296bb8df85ca6c5666fe86b3b8463e792621a21030e495fb5","alt":"Copo azul sem alça, com uma faixa clara próxima da borda."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Um livro","image":{"src":"rsplay-asset:129f2d98f0e2e5a228aaaceb350dc3cbff69c23aebc378fb8fae4e428fdcf901","alt":"Livro aberto com páginas e linhas ilustradas."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Um peixe","image":{"src":"rsplay-asset:476072052f07bcfa9b8f62942b1ba85eeeba4b87a48d9a7992ab0ca92798ecad","alt":"Peixe laranja com cauda e olho."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"Um gato","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."}]},"id":"ed05-EI4-portugues-quiz-01","title":"O livro de Beto","grade":"EI4","subject":"Português","description":"Ouça a história e aponte a figura para responder.\n\nBeto abriu um livro. Na página, viu um peixe. Depois fechou o livro.\n\nAdulto: conte a história e repita quando necessário. Leia as perguntas e nomeie as figuras. Não é preciso que a criança leia.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quem abriu o livro?","options":[{"label":"Beto","image":{"src":"rsplay-asset:33555565b74f48237067eeb7946b9f9f8ea59a06cc1eafaae584bb941facad74","alt":"Beto com roupa roxa, braços e pernas visíveis."},"id":"q1-o0"},{"label":"O gato","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."},"id":"q1-o1"}],"correctOptionId":"q1-o0","explanation":"Beto abriu o livro."},{"id":"q2","prompt":"O que Beto abriu?","options":[{"label":"Um copo","image":{"src":"rsplay-asset:85fb1d67b8e89db296bb8df85ca6c5666fe86b3b8463e792621a21030e495fb5","alt":"Copo azul sem alça, com uma faixa clara próxima da borda."},"id":"q2-o0"},{"label":"Um livro","image":{"src":"rsplay-asset:129f2d98f0e2e5a228aaaceb350dc3cbff69c23aebc378fb8fae4e428fdcf901","alt":"Livro aberto com páginas e linhas ilustradas."},"id":"q2-o1"}],"correctOptionId":"q2-o1","explanation":"Ele abriu um livro para olhar a página."},{"id":"q3","prompt":"Que animal apareceu na página?","options":[{"label":"Um peixe","image":{"src":"rsplay-asset:476072052f07bcfa9b8f62942b1ba85eeeba4b87a48d9a7992ab0ca92798ecad","alt":"Peixe laranja com cauda e olho."},"id":"q3-o0"},{"label":"Um gato","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."},"id":"q3-o1"}],"correctOptionId":"q3-o0","explanation":"Na página havia um peixe."}]}','be01fe49f3d26e13453663152a181eb35a8f49f5969affd5c2786563c5f27acb',true);
