insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI5-portugues-association-01','v28:48758c199172aa58ddb889dac57dcf96eecb883d63ca5a0167bcc5d87db49039','Quem está falando','association','infantil',ARRAY[]::text[],'48758c199172aa58ddb889dac57dcf96eecb883d63ca5a0167bcc5d87db49039','{"schemaVersion":1,"catalog":{"band":"EI5","area":"portugues","batch":"editorial-EI5-portugues-piloto","objective":"Relacionar uma fala ou som ouvido ao personagem que o produz.","readingRequired":false,"visualSupport":[{"term":"gato","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito geométrico/Pillow antigo apenas nas ocorrências aceitas."},{"term":"cão","image":{"src":"rsplay-asset:66b9e132128fee92bd8d29b638abb35f3eca26965e467f13ba14b317af42e6ee","alt":"Cão de orelhas caídas e focinho largo."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026; substituir crédito Pillow antigo só nas ocorrências aceitas."},{"term":"lia","image":{"src":"rsplay-asset:c91514efc5d3af71847b86a7ccc4c9993892e80bf0328787752643a4b2fa6baa","alt":"Lia com roupa roxa, braços abertos e pernas visíveis."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."}]},"id":"ed05-EI5-portugues-association-01","title":"Quem está falando","grade":"EI5","subject":"Português","description":"Ouça cada fala e ligue à imagem de quem fala.\n\nAdulto: leia as falas com naturalidade e nomeie as figuras. Releia sempre que a criança pedir. As imagens repetidas ajudam a relacionar fala e personagem, sem exigir leitura.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"a1","left":{"label":"Miau!","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."}},"right":{"label":"O gato","image":{"src":"rsplay-asset:79e9bdf1a93b288aa7518dccf0d6e686aeecad8e75065adf6f3939976f5c7577","alt":"Gato com orelhas pontudas e bigodes."}}},{"id":"a2","left":{"label":"Au, au!","image":{"src":"rsplay-asset:66b9e132128fee92bd8d29b638abb35f3eca26965e467f13ba14b317af42e6ee","alt":"Cão de orelhas caídas e focinho largo."}},"right":{"label":"O cão","image":{"src":"rsplay-asset:66b9e132128fee92bd8d29b638abb35f3eca26965e467f13ba14b317af42e6ee","alt":"Cão de orelhas caídas e focinho largo."}}},{"id":"a3","left":{"label":"Olá! Eu sou Lia.","image":{"src":"rsplay-asset:c91514efc5d3af71847b86a7ccc4c9993892e80bf0328787752643a4b2fa6baa","alt":"Lia com roupa roxa, braços abertos e pernas visíveis."}},"right":{"label":"Lia","image":{"src":"rsplay-asset:c91514efc5d3af71847b86a7ccc4c9993892e80bf0328787752643a4b2fa6baa","alt":"Lia com roupa roxa, braços abertos e pernas visíveis."}}}]}','48758c199172aa58ddb889dac57dcf96eecb883d63ca5a0167bcc5d87db49039',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('ed05-EI5-portugues-sequence-01','v28:5d19719bc4aa977dcc4d5838c0b3ecc970dcc571d3a32a411ad5d907e02cba72','A pipa na praça','sequence','infantil',ARRAY[]::text[],'5d19719bc4aa977dcc4d5838c0b3ecc970dcc571d3a32a411ad5d907e02cba72','{"schemaVersion":1,"catalog":{"band":"EI5","area":"portugues","batch":"editorial-EI5-portugues-piloto","objective":"Ordenar três cenas de uma narrativa oral com começo, continuação e final.","readingRequired":false,"visualSupport":[{"term":"escolhe","image":{"src":"rsplay-asset:02adbe4e1e75da30dd55da766f9dcbc831feff9f22a14497ef81318c5ea9505e","alt":"Lia na praça, olhando para uma pipa perto do chão."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"leva","image":{"src":"rsplay-asset:f0a8ca40e6795ad7e86ae091c0bd30d34447903efd726c90caf894ed71902642","alt":"Lia levando a pipa em posição baixa pela praça."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."},{"term":"empina","image":{"src":"rsplay-asset:fcebdb815f100c2eddcf817657434a74d480524a04d6b9215fdd28f94f8e0af5","alt":"Lia segurando a linha de uma pipa mais alta."},"rights":"Ilustração gerada por IA com imagegen e revisada para RS Play, 2026. Substituir crédito Pillow antigo apenas nas ocorrências aceitas."}]},"id":"ed05-EI5-portugues-sequence-01","title":"A pipa na praça","grade":"EI5","subject":"Português","description":"Coloque as imagens na ordem da história. Depois, conte com suas palavras.\n\nPrimeiro, Lia escolheu uma pipa. Depois, levou a pipa pela praça. Por fim, empinou a pipa.\n\nAdulto: conte mostrando as cenas e leia os rótulos quando necessário.","difficulty":"facil","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Lia escolheu a pipa.","image":{"src":"rsplay-asset:02adbe4e1e75da30dd55da766f9dcbc831feff9f22a14497ef81318c5ea9505e","alt":"Lia na praça, olhando para uma pipa perto do chão."},"id":"s1"},{"label":"Lia levou a pipa pela praça.","image":{"src":"rsplay-asset:f0a8ca40e6795ad7e86ae091c0bd30d34447903efd726c90caf894ed71902642","alt":"Lia levando a pipa em posição baixa pela praça."},"id":"s2"},{"label":"Lia empinou a pipa.","image":{"src":"rsplay-asset:fcebdb815f100c2eddcf817657434a74d480524a04d6b9215fdd28f94f8e0af5","alt":"Lia segurando a linha de uma pipa mais alta."},"id":"s3"}]}','5d19719bc4aa977dcc4d5838c0b3ecc970dcc571d3a32a411ad5d907e02cba72',true);
