insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef1-quiz-05','v28:72c576cac0be8c1de8db1e3976ae715e9628ea62757323dd571c431d202beef6','Água não é prêmio','quiz','1',ARRAY[]::text[],'72c576cac0be8c1de8db1e3976ae715e9628ea62757323dd571c431d202beef6','{"schemaVersion":1,"catalog":{"band":"EF1","area":"historia","batch":"livros-historia-v18","objective":"Analisar a diferença entre orientar Ravi e negar um direito","readingRequired":true,"visualSupport":[]},"bookReference":{"year":1,"bookId":"historia-ef1","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Direitos, deveres e natureza","topic":"Analisar a diferença entre orientar Ravi e negar um direito","sourceUrl":"https://drive.google.com/file/d/1vCyiOgXkGzCghM9NfPBeriQjyVHoHK0h/view","pages":[{"pdfPage":87,"printedPage":"86"}],"itemSources":[{"itemId":"q1","pdfPages":[87]},{"itemId":"q2","pdfPages":[87]},{"itemId":"q3","pdfPages":[87]}]},"id":"livros-ef1-quiz-05","title":"Água não é prêmio","grade":"1º ano","subject":"História","collection":{"id":"historia-ef1","title":"História Indígena e Afro-Brasileira · 1º ano"},"description":"Com leitura mediada pelo professor, escolha uma resposta por pergunta. Consulte a página 86. Caso fictício apresentado pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual combinado Ravi esqueceu?","options":[{"label":"Guardar o jogo.","id":"q1-o1"},{"label":"Devolver um livro à biblioteca.","id":"q1-o2"},{"label":"Esperar a vez de desenhar.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O relato começa com Ravi esquecendo o combinado de guardar o jogo."},{"id":"q2","prompt":"Do que Ravi precisou depois?","options":[{"label":"Uma peça para a ponte.","id":"q2-o1"},{"label":"Uma folha para a colagem.","id":"q2-o2"},{"label":"Água.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"Depois de esquecer o combinado, Ravi pede água à professora."},{"id":"q3","prompt":"Qual decisão respeita Ravi e também ensina o combinado?","options":[{"label":"Dizer que ele nunca mais pode brincar.","id":"q3-o1"},{"label":"Garantir água e orientá-lo a guardar o jogo.","id":"q3-o2"},{"label":"Negar água até guardar tudo.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"O livro afirma que os direitos continuam valendo quando uma criança erra."}]}','72c576cac0be8c1de8db1e3976ae715e9628ea62757323dd571c431d202beef6',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef1-quiz-06','v28:a500f4dc0b9fedf01f39189cc18d37a5e09ef16879e848e6ecc0c78f662355ef','A colagem de Luana','quiz','1',ARRAY[]::text[],'a500f4dc0b9fedf01f39189cc18d37a5e09ef16879e848e6ecc0c78f662355ef','{"schemaVersion":1,"catalog":{"band":"EF1","area":"historia","batch":"livros-historia-v18","objective":"Examinar reaproveitamento e teste de materiais em uma criação","readingRequired":true,"visualSupport":[]},"bookReference":{"year":1,"bookId":"historia-ef1","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Direitos, deveres e natureza","topic":"Examinar reaproveitamento e teste de materiais em uma criação","sourceUrl":"https://drive.google.com/file/d/1vCyiOgXkGzCghM9NfPBeriQjyVHoHK0h/view","pages":[{"pdfPage":92,"printedPage":"91"}],"itemSources":[{"itemId":"q1","pdfPages":[92]},{"itemId":"q2","pdfPages":[92]},{"itemId":"q3","pdfPages":[92]}]},"id":"livros-ef1-quiz-06","title":"A colagem de Luana","grade":"1º ano","subject":"História","collection":{"id":"historia-ef1","title":"História Indígena e Afro-Brasileira · 1º ano"},"description":"Com leitura mediada pelo professor, escolha uma resposta por pergunta. Consulte a página 91. Caso fictício apresentado pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que material a turma já tinha para examinar?","options":[{"label":"Folhas arrancadas do jardim.","id":"q1-o3"},{"label":"Sobras limpas de papel.","id":"q1-o1"},{"label":"Cacos de vidro.","id":"q1-o2"}],"correctOptionId":"q1-o1","explanation":"A mesa tinha sobras limpas da atividade anterior que poderiam ser examinadas."},{"id":"q2","prompt":"O que é preciso conferir antes de reaproveitar uma sobra?","options":[{"label":"Se ela serve para a colagem.","id":"q2-o3"},{"label":"Se ninguém já usou papel antes.","id":"q2-o2"},{"label":"Se ela é a maior de todas.","id":"q2-o1"}],"correctOptionId":"q2-o3","explanation":"Reaproveitar exige verificar se o material atende à nova criação, como explica o texto."},{"id":"q3","prompt":"O que Luana pode fazer antes de colar?","options":[{"label":"Colar todas as sobras sem olhar.","id":"q3-o3"},{"label":"Jogar fora tudo que está na mesa.","id":"q3-o1"},{"label":"Testar posições e mudar a composição.","id":"q3-o2"}],"correctOptionId":"q3-o2","explanation":"O livro propõe experimentar posições e mudar a ideia antes de fixar as peças."}]}','a500f4dc0b9fedf01f39189cc18d37a5e09ef16879e848e6ecc0c78f662355ef',true);
