insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-association-01','v28:6a51052c60da9ede56050a8d5a6cc4f9627b37c57943ae3d1029a1455487831b','Três exemplos de conhecimentos','association','2',ARRAY[]::text[],'6a51052c60da9ede56050a8d5a6cc4f9627b37c57943ae3d1029a1455487831b','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Consulte um trecho por vez nas páginas indicadas. Localize o povo ou a pessoa mencionada e releia o que o texto informa sobre sua atuação. Compare os nomes com atenção; um adulto pode ajudar a lê-los sem fazer a ligação."},"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer exemplos Baré, Ikpeng e Wajãpi, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos indígenas","topic":"Exemplos Baré, Ikpeng e Wajãpi","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":41,"printedPage":"40"},{"pdfPage":43,"printedPage":"42"},{"pdfPage":51,"printedPage":"50"}],"itemSources":[{"itemId":"p1","pdfPages":[43]},{"itemId":"p2","pdfPages":[41]},{"itemId":"p3","pdfPages":[51]}]},"id":"livros-ef2-association-01","title":"Três exemplos de conhecimentos","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com apoio do professor, releia as páginas 40, 42 e 50. Ligue cada povo ao exemplo citado. Os exemplos não resumem todos os conhecimentos de cada povo.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Baré"},"right":{"label":"Belmira conta falar nheengatu e português."}},{"id":"p2","left":{"label":"Ikpeng"},"right":{"label":"Natuyu Yuwipo Txicão ajudou outras mulheres indígenas a fazer filmes."}},{"id":"p3","left":{"label":"Wajãpi"},"right":{"label":"Kusiwa reúne expressões gráficas e oralidade."}}]}','6a51052c60da9ede56050a8d5a6cc4f9627b37c57943ae3d1029a1455487831b',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-association-61','v28:cb0c41b3488f7cc416c5182ea9684e16ce6dae5b3e5126fa607d1a6172f68ad0','Pequi: território e alimentação','association','2',ARRAY[]::text[],'cb0c41b3488f7cc416c5182ea9684e16ce6dae5b3e5126fa607d1a6172f68ad0','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Relacionar o projeto de pequi Kisêdjê à recuperação de uma área desmatada e à produção de frutos e óleo.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos indígenas","topic":"Relacionar o projeto de pequi Kisêdjê à recuperação de uma área desmatada e à produção de frutos e óleo.","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":45,"printedPage":"44"}],"itemSources":[{"itemId":"p1","pdfPages":[45]},{"itemId":"p2","pdfPages":[45]}]},"id":"livros-ef2-association-61","title":"Pequi: território e alimentação","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, leia a página 44 e ligue cada aspecto do projeto Kisêdjê à informação correspondente.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Cuidado com o território"},"right":{"label":"Recuperação de uma área desmatada."}},{"id":"p2","left":{"label":"Produtos para a alimentação"},"right":{"label":"Frutos e óleo de pequi."}}]}','cb0c41b3488f7cc416c5182ea9684e16ce6dae5b3e5126fa607d1a6172f68ad0',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-01','v28:9b73d967b7cd227b1e5d009455d61ef8c2fa21addca2fa9e4c78e52e4223207e','As crianças Yudja contam','quiz','2',ARRAY[]::text[],'9b73d967b7cd227b1e5d009455d61ef8c2fa21addca2fa9e4c78e52e4223207e','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer autoria do relato sobre brincadeiras de Tuba Tuba, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos indígenas","topic":"Autoria do relato sobre brincadeiras de Tuba Tuba","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":47,"printedPage":"46"}],"itemSources":[{"itemId":"q1","pdfPages":[47]},{"itemId":"q2","pdfPages":[47]},{"itemId":"q3","pdfPages":[47]}]},"id":"livros-ef2-quiz-01","title":"As crianças Yudja contam","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Leia com o professor a página 46. Responda considerando as crianças e a comunidade citadas, sem estender o relato a todos os povos indígenas.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quem escreveu o relato apresentado?","options":[{"label":"As próprias crianças Yudja.","id":"q1-o1"},{"label":"Uma turista que não visitou a aldeia.","id":"q1-o2"},{"label":"Um grupo de adultos de outra cidade.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O texto informa que o relato foi escrito pelas próprias crianças."},{"id":"q2","prompt":"De qual aldeia são as crianças citadas?","options":[{"label":"Canauanim.","id":"q2-o1"},{"label":"Tuba Tuba.","id":"q2-o2"},{"label":"Uma aldeia sem nome no texto.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O livro identifica as crianças Yudja da aldeia Tuba Tuba."},{"id":"q3","prompt":"Quais experiências aparecem no relato?","options":[{"label":"Xadrez e dominó.","id":"q3-o1"},{"label":"Corrida de sacos e futebol.","id":"q3-o2"},{"label":"Pião de tucum e figuras de barbante.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O relato cita o pião de semente de tucum e figuras feitas com barbante."}]}','9b73d967b7cd227b1e5d009455d61ef8c2fa21addca2fa9e4c78e52e4223207e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-sequence-01','v28:08fc0fc3fff5a574719a244a6294c3d95283e5d87bcbea84f622da025b84cd74','Plantar, colher e preparar','sequence','2',ARRAY[]::text[],'08fc0fc3fff5a574719a244a6294c3d95283e5d87bcbea84f622da025b84cd74','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer percurso do alimento apresentado junto ao relato Kisêdjê, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos indígenas","topic":"Percurso do alimento apresentado junto ao relato Kisêdjê","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":49,"printedPage":"48"}],"itemSources":[{"itemId":"s1","pdfPages":[49]},{"itemId":"s2","pdfPages":[49]},{"itemId":"s3","pdfPages":[49]}]},"id":"livros-ef2-sequence-01","title":"Plantar, colher e preparar","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com o professor, releia a página 48 e ordene o percurso resumido: do cultivo ao preparo do alimento. O relato Kisêdjê citado fala da colheita do pequi; não representa todos os povos indígenas.","difficulty":"facil","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Plantar e cuidar do cultivo.","id":"s1"},{"label":"Colher os frutos.","id":"s2"},{"label":"Preparar os alimentos com conhecimentos compartilhados.","id":"s3"}]}','08fc0fc3fff5a574719a244a6294c3d95283e5d87bcbea84f622da025b84cd74',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-completion-01','v28:8cbc33653a54684df90496b67c1f2c71d69bc2cbfdab77e6862d9b285cf1a526','Conheça Enedina Alves Marques','completion','2',ARRAY[]::text[],'8cbc33653a54684df90496b67c1f2c71d69bc2cbfdab77e6862d9b285cf1a526','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Antes de escolher, observe se a frase pede profissão, curso ou ano. Procure essa informação no trecho sobre Enedina e confira a frase inteira. Não é preciso decorar todos os dados de uma vez."},"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer formação e trabalho de Enedina Alves Marques, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Presença africana na formação do Brasil","topic":"Formação e trabalho de Enedina Alves Marques","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":83,"printedPage":"82"}],"itemSources":[{"itemId":"b1","pdfPages":[83]},{"itemId":"b2","pdfPages":[83]},{"itemId":"b3","pdfPages":[83]}]},"id":"livros-ef2-completion-01","title":"Conheça Enedina Alves Marques","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com o professor, leia a página 82. Complete as frases sobre a trajetória de Enedina, escolhendo uma opção por lacuna.","difficulty":"facil","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"Enedina Alves Marques foi ","after":" e também se formou em engenharia.","answers":["professora"],"options":[{"label":"professora","id":"b1-o1"},{"label":"cineasta","id":"b1-o2"},{"label":"cantora","id":"b1-o3"}]},{"id":"b2","before":"Enedina concluiu o curso de Engenharia ","after":".","answers":["Civil"],"options":[{"label":"Florestal","id":"b2-o1"},{"label":"Civil","id":"b2-o2"},{"label":"Naval","id":"b2-o3"}]},{"id":"b3","before":"Ela concluiu sua formação em engenharia em ","after":".","answers":["1945"],"options":[{"label":"1960","id":"b3-o1"},{"label":"1945","id":"b3-o2"},{"label":"1961","id":"b3-o3"}]}]}','8cbc33653a54684df90496b67c1f2c71d69bc2cbfdab77e6862d9b285cf1a526',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-20','v28:ace564134119df74fd401db3f7d9720229d50bc878f483837213e1a65e500390','Grande Zimbábue e Nairobi','quiz','2',ARRAY[]::text[],'ace564134119df74fd401db3f7d9720229d50bc878f483837213e1a65e500390','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Localize o trecho sobre o museu e procure as ações que ele realiza. Não misture essas informações com as construções antigas tratadas nas outras perguntas."}]},"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Comparar um patrimônio arqueológico e uma instituição científica africana","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Presença africana na formação do Brasil","topic":"Comparar um patrimônio arqueológico e uma instituição científica africana","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":69,"printedPage":"68"},{"pdfPage":70,"printedPage":"69"}],"itemSources":[{"itemId":"q1","pdfPages":[69]},{"itemId":"q2","pdfPages":[69]},{"itemId":"q3","pdfPages":[70]}]},"id":"livros-ef2-quiz-20","title":"Grande Zimbábue e Nairobi","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, consulte as páginas 68, 69. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que material das construções ajuda a estudar Grande Zimbábue?","options":[{"label":"Plástico.","id":"q1-o1"},{"label":"Papel.","id":"q1-o2"},{"label":"Pedra.","id":"q1-o3"}],"correctOptionId":"q1-o3","explanation":"As construções de pedra permaneceram como vestígios da cidade antiga."},{"id":"q2","prompt":"A história dessas construções se liga a quais povos?","options":[{"label":"Kalapalo.","id":"q2-o1"},{"label":"Shona.","id":"q2-o2"},{"label":"Baniwa.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O texto relaciona os vestígios aos povos Shona, situando os sujeitos dessa história africana."},{"id":"q3","prompt":"Além de apresentar exposições, o que faz o Museu Nacional em Nairobi?","options":[{"label":"Pesquisar e conservar coleções científicas.","id":"q3-o1"},{"label":"Construir as muralhas de Grande Zimbábue.","id":"q3-o2"},{"label":"Produzir apenas lembranças para turistas.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"A pesquisa e a conservação mostram que o museu também produz conhecimento no presente."}]}','ace564134119df74fd401db3f7d9720229d50bc878f483837213e1a65e500390',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-21','v28:685bd8db782479d9cd9359cf6a870ae4a522acaaf909154b0dd45199e8b5c2e5','Acarajé: ingredientes e ofício','quiz','2',ARRAY[]::text[],'685bd8db782479d9cd9359cf6a870ae4a522acaaf909154b0dd45199e8b5c2e5','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Relacionar alimento, trabalho e conexões históricas entre Bahia e África Ocidental","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Presença africana na formação do Brasil","topic":"Relacionar alimento, trabalho e conexões históricas entre Bahia e África Ocidental","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":79,"printedPage":"78"}],"itemSources":[{"itemId":"q1","pdfPages":[79]},{"itemId":"q2","pdfPages":[79]},{"itemId":"q3","pdfPages":[79]}]},"id":"livros-ef2-quiz-21","title":"Acarajé: ingredientes e ofício","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, consulte a página 78. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que ingredientes o livro destaca no acarajé?","options":[{"label":"Trigo e manteiga.","id":"q1-o1"},{"label":"Feijão-fradinho e azeite de dendê.","id":"q1-o2"},{"label":"Mandioca e mel.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"Esses ingredientes são citados para apresentar o alimento ligado ao ofício das baianas."},{"id":"q2","prompt":"A história do acarajé liga a Bahia a qual região africana?","options":[{"label":"Golfo do Benim.","id":"q2-o1"},{"label":"Vale do Nilo.","id":"q2-o2"},{"label":"Região de Meroé.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"O livro identifica uma conexão com o Golfo do Benim, na África Ocidental."},{"id":"q3","prompt":"Por que preparar e vender acarajé é chamado de ofício?","options":[{"label":"Porque dispensa qualquer aprendizagem.","id":"q3-o1"},{"label":"Porque é somente o nome de um ingrediente.","id":"q3-o2"},{"label":"Porque reúne habilidades aprendidas no trabalho.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"Ofício nomeia o trabalho e os saberes envolvidos, não apenas a comida pronta."}]}','685bd8db782479d9cd9359cf6a870ae4a522acaaf909154b0dd45199e8b5c2e5',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-40','v28:d8628ed798eb3eaa54588506dbf24cb902599d02329a036092d10c08235213d9','Leonila: poesia e comunidade','quiz','2',ARRAY[]::text[],'d8628ed798eb3eaa54588506dbf24cb902599d02329a036092d10c08235213d9','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer as atuações de Leonila Rodrigues e seu vínculo com o Quilombo Abobral Margem Esquerda","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Presença africana na formação do Brasil","topic":"Reconhecer as atuações de Leonila Rodrigues e seu vínculo com o Quilombo Abobral Margem Esquerda","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":73,"printedPage":"72"}],"itemSources":[{"itemId":"q1","pdfPages":[73]},{"itemId":"q2","pdfPages":[73]}]},"id":"livros-ef2-quiz-40","title":"Leonila: poesia e comunidade","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, consulte a página 72. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que duas atuações de Leonila Rodrigues são citadas no texto?","options":[{"label":"Professora e engenheira.","id":"q1-o1"},{"label":"Poeta e liderança comunitária.","id":"q1-o2"},{"label":"Cineasta e pesquisadora.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O texto apresenta Leonila como poeta e liderança comunitária. Essas duas atuações mostram formas de criar e participar da vida da comunidade."},{"id":"q2","prompt":"A qual comunidade quilombola o texto liga Leonila Rodrigues?","options":[{"label":"Quilombo Abobral Margem Esquerda.","id":"q2-o1"},{"label":"Quilombo São José da Serra.","id":"q2-o2"},{"label":"Comunidade do Tamandaré.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"Leonila é apresentada como integrante do Quilombo Abobral Margem Esquerda, no Vale do Ribeira. O nome permite reconhecer a comunidade específica de sua trajetória."}]}','d8628ed798eb3eaa54588506dbf24cb902599d02329a036092d10c08235213d9',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-41','v28:56bca16a6ef3a733669e71e7352d79ae66ec633c90a0c2346ea3a407df39ca83','Dois grupos de jongo','quiz','2',ARRAY[]::text[],'56bca16a6ef3a733669e71e7352d79ae66ec633c90a0c2346ea3a407df39ca83','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Procure no texto o trecho sobre o Quilombo São José da Serra. Leia os nomes dos instrumentos desse exemplo, sem usar apenas a fotografia como referência."},{"itemId":"q2","text":"Leia a legenda da fotografia e confira o nome do grupo que ela apresenta. Texto e fotografia de uma mesma página podem tratar de grupos diferentes."}]},"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Distinguir os tambores do registro de São José da Serra e o grupo identificado na legenda da Serrinha","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Presença africana na formação do Brasil","topic":"Distinguir os tambores do registro de São José da Serra e o grupo identificado na legenda da Serrinha","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":75,"printedPage":"74"}],"itemSources":[{"itemId":"q1","pdfPages":[75]},{"itemId":"q2","pdfPages":[75]}]},"id":"livros-ef2-quiz-41","title":"Dois grupos de jongo","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, consulte a página 74. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quais tambores o registro citado apresenta no grupo do Quilombo São José da Serra?","options":[{"label":"Tambu e candongueiro.","id":"q1-o1"},{"label":"Tambu e berimbau.","id":"q1-o2"},{"label":"Berimbau e candongueiro.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O registro do IPHAN cita tambu e candongueiro nesse grupo de jongo. Essa informação vale para o exemplo de São José da Serra apresentado no texto."},{"id":"q2","prompt":"A legenda da página 74 identifica Tia Maria e participantes de qual grupo?","options":[{"label":"Jongo de São José da Serra.","id":"q2-o1"},{"label":"Jongo do Tamandaré.","id":"q2-o2"},{"label":"Jongo da Serrinha.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"A legenda identifica o Jongo da Serrinha. O livro avisa que a fotografia não mostra o grupo de São José da Serra citado no texto."}]}','56bca16a6ef3a733669e71e7352d79ae66ec633c90a0c2346ea3a407df39ca83',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-42','v28:0d3c5b058c4e9e2ff5a74315e2bc69eea9595b9823da8fa0f7acd36686fd84bb','Bembé: celebração e memória','quiz','2',ARRAY[]::text[],'0d3c5b058c4e9e2ff5a74315e2bc69eea9595b9823da8fa0f7acd36686fd84bb','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Relacionar o Bembé do Mercado a Santo Amaro e às memórias de liberdade e práticas do candomblé","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Presença africana na formação do Brasil","topic":"Relacionar o Bembé do Mercado a Santo Amaro e às memórias de liberdade e práticas do candomblé","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":77,"printedPage":"76"}],"itemSources":[{"itemId":"q1","pdfPages":[77]},{"itemId":"q2","pdfPages":[77]}]},"id":"livros-ef2-quiz-42","title":"Bembé: celebração e memória","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, consulte a página 76. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que memórias e práticas se encontram no Bembé do Mercado?","options":[{"label":"Memórias de viagens comerciais e práticas da capoeira.","id":"q1-o1"},{"label":"Memórias de luta pela liberdade e práticas do candomblé.","id":"q1-o2"},{"label":"Memórias de pesquisas científicas e práticas do jongo.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O texto relaciona a celebração às lutas pela liberdade e ao candomblé, religião de matriz africana. A pergunta trata dessa história, sem pedir a prática da religião."},{"id":"q2","prompt":"Em qual cidade e estado o livro situa o Bembé do Mercado?","options":[{"label":"Eldorado, em São Paulo.","id":"q2-o1"},{"label":"Rio de Janeiro, no Rio de Janeiro.","id":"q2-o2"},{"label":"Santo Amaro, na Bahia.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"O livro situa o Bembé em Santo Amaro, na Bahia, e o relaciona à história de pessoas negras do Recôncavo Baiano."}]}','0d3c5b058c4e9e2ff5a74315e2bc69eea9595b9823da8fa0f7acd36686fd84bb',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-62','v28:4de28d8c8b4ff43a7f58b547f5095d2c1c12f4da02a5b72cf897d539ed9e78e5','Antonieta: ensino e vida pública','quiz','2',ARRAY[]::text[],'4de28d8c8b4ff43a7f58b547f5095d2c1c12f4da02a5b72cf897d539ed9e78e5','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer as atuações de Antonieta de Barros e a finalidade do curso que criou em 1922.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Presença africana na formação do Brasil","topic":"Reconhecer as atuações de Antonieta de Barros e a finalidade do curso que criou em 1922.","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":84,"printedPage":"83"}],"itemSources":[{"itemId":"q1","pdfPages":[84]},{"itemId":"q2","pdfPages":[84]}]},"id":"livros-ef2-quiz-62","title":"Antonieta: ensino e vida pública","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, leia a página 83 e escolha uma resposta por pergunta sobre Antonieta de Barros.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quais trabalhos Antonieta de Barros exerceu em Santa Catarina?","options":[{"label":"Professora, jornalista e deputada.","id":"q1-o1"},{"label":"Professora, engenheira e pesquisadora.","id":"q1-o2"},{"label":"Jornalista, médica e deputada.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O texto reúne ensino, jornalismo e atuação como deputada na trajetória de Antonieta."},{"id":"q2","prompt":"Para que servia o curso criado por Antonieta em 1922?","options":[{"label":"Para ensinar a construir casas.","id":"q2-o1"},{"label":"Para ensinar a ler e escrever.","id":"q2-o2"},{"label":"Para ensinar a cuidar de plantações.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"Antonieta criou o curso para ensinar pessoas a ler e escrever."}]}','4de28d8c8b4ff43a7f58b547f5095d2c1c12f4da02a5b72cf897d539ed9e78e5',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-association-03','v28:6f330dd0443f98bcdae23dca22ed7a224a82eb9cb891db94769df0122c1e2520','Organizar o canto de leitura','association','2',ARRAY[]::text[],'6f330dd0443f98bcdae23dca22ed7a224a82eb9cb891db94769df0122c1e2520','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Relacionar ações de cooperação a suas funções no planejamento coletivo","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Respeito, empatia e cooperação","topic":"Relacionar ações de cooperação a suas funções no planejamento coletivo","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":101,"printedPage":"100"}],"itemSources":[{"itemId":"p1","pdfPages":[101]},{"itemId":"p2","pdfPages":[101]},{"itemId":"p3","pdfPages":[101]}]},"id":"livros-ef2-association-03","title":"Organizar o canto de leitura","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, ligue cada entrada à informação correspondente. Consulte a página 100. Exemplo de organização do canto de leitura apresentado no livro; as ações não exigem ordem rígida.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Ouvir"},"right":{"label":"Conhecer propostas para o canto de leitura."}},{"id":"p2","left":{"label":"Combinar"},"right":{"label":"Distribuir responsabilidades entre os participantes."}},{"id":"p3","left":{"label":"Observar"},"right":{"label":"Verificar se todos conseguem participar."}}]}','6f330dd0443f98bcdae23dca22ed7a224a82eb9cb891db94769df0122c1e2520',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-03','v28:d35829ea10ab78eda550e5c989c38d0d433b99ad3c07f67f41d51423595a544a','O desenho de Joana','quiz','2',ARRAY[]::text[],'d35829ea10ab78eda550e5c989c38d0d433b99ad3c07f67f41d51423595a544a','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Procure o momento anterior à conversa. Separe o que Davi pensou do que Joana explicou depois."},{"itemId":"q3","text":"Localize a fala de Joana sobre como prefere apresentar. Compare essa informação com as ideias que outra pessoa tinha sobre ela."}]},"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Diferenciar hipótese de Davi, pergunta e preferência expressa por Joana","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Respeito, empatia e cooperação","topic":"Diferenciar hipótese de Davi, pergunta e preferência expressa por Joana","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":99,"printedPage":"98"}],"itemSources":[{"itemId":"q1","pdfPages":[99]},{"itemId":"q2","pdfPages":[99]},{"itemId":"q3","pdfPages":[99]}]},"id":"livros-ef2-quiz-03","title":"O desenho de Joana","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, escolha uma resposta por pergunta. Consulte a página 98. Caso fictício apresentado pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"O que Davi imaginou antes de perguntar?","options":[{"label":"Que Joana não gostara do trabalho.","id":"q1-o1"},{"label":"Que Joana perdera o desenho.","id":"q1-o3"},{"label":"Que Joana queria jogar bola.","id":"q1-o2"}],"correctOptionId":"q1-o1","explanation":"Antes da conversa, Davi supõe que Joana não gostou do próprio trabalho."},{"id":"q2","prompt":"Que atitude permitiu a Davi conhecer a preferência de Joana?","options":[{"label":"Olhar o desenho sem conversar.","id":"q2-o2"},{"label":"Perguntar a ela.","id":"q2-o3"},{"label":"Escolher por ela.","id":"q2-o1"}],"correctOptionId":"q2-o3","explanation":"A pergunta permite que Davi substitua sua suposição pela resposta da própria Joana."},{"id":"q3","prompt":"Como Joana preferia começar a apresentação?","options":[{"label":"Apagando todo o desenho.","id":"q3-o3"},{"label":"Falando obrigatoriamente para a turma inteira.","id":"q3-o1"},{"label":"Mostrando o desenho para uma dupla.","id":"q3-o2"}],"correctOptionId":"q3-o2","explanation":"Joana explica que prefere começar mostrando o desenho para uma dupla."}]}','d35829ea10ab78eda550e5c989c38d0d433b99ad3c07f67f41d51423595a544a',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef2-quiz-04','v28:7e0f62550bfd91927141894bdf25a1e23c434f62a67cd3b3d0700849b2b8319a','Um livro, duas necessidades','quiz','2',ARRAY[]::text[],'7e0f62550bfd91927141894bdf25a1e23c434f62a67cd3b3d0700849b2b8319a','{"schemaVersion":1,"catalog":{"band":"EF2","area":"historia","batch":"livros-historia-v18","objective":"Identificar necessidades distintas e mediação em um conflito pelo uso do livro","readingRequired":true,"visualSupport":[]},"bookReference":{"year":2,"bookId":"historia-ef2","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Respeito, empatia e cooperação","topic":"Identificar necessidades distintas e mediação em um conflito pelo uso do livro","sourceUrl":"https://drive.google.com/file/d/1u8W8FmyMZykACrqwRUP5xxm7msOvsQ34/view","pages":[{"pdfPage":113,"printedPage":"112"}],"itemSources":[{"itemId":"q1","pdfPages":[113]},{"itemId":"q2","pdfPages":[113]},{"itemId":"q3","pdfPages":[113]}]},"id":"livros-ef2-quiz-04","title":"Um livro, duas necessidades","grade":"2º ano","subject":"História","collection":{"id":"historia-ef2","title":"História Indígena e Afro-Brasileira · 2º ano"},"description":"Com leitura mediada pelo professor, escolha uma resposta por pergunta. Consulte a página 112. Caso fictício apresentado pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Por que Raul quer usar o livro?","options":[{"label":"Para recortar uma página.","id":"q1-o2"},{"label":"Para terminar uma história.","id":"q1-o1"},{"label":"Para guardá-lo em casa.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"Raul explica que ainda deseja terminar a história que está lendo."},{"id":"q2","prompt":"Por que Mila precisa do livro?","options":[{"label":"Para escrever por cima do texto.","id":"q2-o1"},{"label":"Para impedir Raul de ler.","id":"q2-o2"},{"label":"Para observar uma imagem para a atividade.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"O relato informa que Mila precisa consultar uma imagem para realizar a atividade."},{"id":"q3","prompt":"Como os dois procuram ajuda?","options":[{"label":"Chamam a professora e explicam o que precisam.","id":"q3-o2"},{"label":"Decidem que só uma necessidade importa.","id":"q3-o1"},{"label":"Escondem o livro da professora.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"Os dois apresentam suas necessidades à professora, buscando ajuda para o desacordo."}]}','7e0f62550bfd91927141894bdf25a1e23c434f62a67cd3b3d0700849b2b8319a',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-02','v28:6919db9a887401a0af5fda8f38a42fa92aa8e19b9813c1ff1fd738f93e812043','Os cartões de Lia e Ravi','quiz','3',ARRAY[]::text[],'6919db9a887401a0af5fda8f38a42fa92aa8e19b9813c1ff1fd738f93e812043','{"schemaVersion":1,"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Ler pertencimentos e interesses sem reduzir uma pessoa a uma característica","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Identidade e diversidade","topic":"Ler pertencimentos e interesses sem reduzir uma pessoa a uma característica","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":11,"printedPage":"10"}],"itemSources":[{"itemId":"q1","pdfPages":[11]},{"itemId":"q2","pdfPages":[11]},{"itemId":"q3","pdfPages":[11]}]},"id":"livros-ef3-quiz-02","title":"Os cartões de Lia e Ravi","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Escolha uma resposta por pergunta. Consulte a página 10. Caso fictício apresentado pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual gosto aparece nos dois cartões fictícios?","options":[{"label":"Jogos de tabuleiro.","id":"q1-o3"},{"label":"Corridas de bicicleta.","id":"q1-o2"},{"label":"Histórias em quadrinhos.","id":"q1-o1"}],"correctOptionId":"q1-o1","explanation":"Os cartões de Lia e de Ravi trazem o mesmo gosto por histórias em quadrinhos."},{"id":"q2","prompt":"Qual participação Lia descreve na escola?","options":[{"label":"Ajudar a cuidar dos livros.","id":"q2-o3"},{"label":"Ensinar música para toda a turma.","id":"q2-o2"},{"label":"Cuidar da horta com Ravi.","id":"q2-o1"}],"correctOptionId":"q2-o3","explanation":"Lia conta em seu cartão que ajuda a cuidar dos livros na escola."},{"id":"q3","prompt":"Qual atividade Ravi conta realizar com a avó?","options":[{"label":"Construir um instrumento.","id":"q3-o3"},{"label":"Cultivar uma planta.","id":"q3-o2"},{"label":"Organizar uma biblioteca.","id":"q3-o1"}],"correctOptionId":"q3-o2","explanation":"Ravi descreve o cultivo de uma planta em casa com sua avó."}]}','6919db9a887401a0af5fda8f38a42fa92aa8e19b9813c1ff1fd738f93e812043',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-03','v28:5f6602534f939ecf8d6f7f167ab93fdfc4f8d102a1d8af2962e1c994bba77f7c','O encontro mudou de lugar','quiz','3',ARRAY[]::text[],'5f6602534f939ecf8d6f7f167ab93fdfc4f8d102a1d8af2962e1c994bba77f7c','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Consulte o convite, que registra o plano antes do encontro. Procure nele a informação pedida, sem trocar pelo relato feito depois."},{"itemId":"q2","text":"Agora consulte o relato de Joana. A pergunta pede o que aconteceu, que pode ser diferente do que estava planejado no convite."},{"itemId":"q3","text":"Compare os dois registros e procure o acontecimento mencionado antes da roda. Veja se ele explica por que o plano mudou."}]},"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Comparar planejamento e acontecimento usando convite e relato posterior","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Identidade e diversidade","topic":"Comparar planejamento e acontecimento usando convite e relato posterior","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":13,"printedPage":"12"}],"itemSources":[{"itemId":"q1","pdfPages":[13]},{"itemId":"q2","pdfPages":[13]},{"itemId":"q3","pdfPages":[13]}]},"id":"livros-ef3-quiz-03","title":"O encontro mudou de lugar","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Escolha uma resposta por pergunta. Consulte a página 12. Caso fictício apresentado pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que local o convite do Encontro de histórias anunciava?","options":[{"label":"O pátio.","id":"q1-o1"},{"label":"A biblioteca.","id":"q1-o2"},{"label":"A praça do bairro.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O convite anuncia o pátio; essa informação registra o plano inicial."},{"id":"q2","prompt":"Segundo o relato de Joana, onde a roda aconteceu?","options":[{"label":"No pátio.","id":"q2-o1"},{"label":"Na casa da tia.","id":"q2-o2"},{"label":"Na biblioteca.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"O relato posterior informa que as histórias foram ouvidas na biblioteca."},{"id":"q3","prompt":"Que informação explica a mudança de local?","options":[{"label":"O convite já anunciava dois locais.","id":"q3-o1"},{"label":"Começou a chover antes da roda.","id":"q3-o2"},{"label":"A escola cancelou todas as histórias.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"Joana relata que começou a chover antes da roda, explicando a mudança para a biblioteca."}]}','5f6602534f939ecf8d6f7f167ab93fdfc4f8d102a1d8af2962e1c994bba77f7c',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-04','v28:4dfc60df291acd72356b8f4a72660d5031ca7e3540027327b9550b884e5464d5','Leitura e ensaio no mesmo horário','quiz','3',ARRAY[]::text[],'4dfc60df291acd72356b8f4a72660d5031ca7e3540027327b9550b884e5464d5','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Separe o que cada pessoa conta de uma conclusão sobre intenção. Procure no relato se há informação sobre o que o grupo sabia, em vez de concluir apenas pelo incômodo causado."}]},"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Comparar perspectivas de um conflito sem atribuir intenção sem evidência","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Identidade e diversidade","topic":"Comparar perspectivas de um conflito sem atribuir intenção sem evidência","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":25,"printedPage":"24"}],"itemSources":[{"itemId":"q1","pdfPages":[25]},{"itemId":"q2","pdfPages":[25]},{"itemId":"q3","pdfPages":[25]}]},"id":"livros-ef3-quiz-04","title":"Leitura e ensaio no mesmo horário","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Escolha uma resposta por pergunta. Consulte a página 24. Registros de Nina e Davi usados no caso de convivência do livro; não pedir relatos pessoais.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que dificuldade Nina relatou durante a leitura?","options":[{"label":"Não sabia o horário do ensaio.","id":"q1-o3"},{"label":"Não conseguiu acompanhar a história por causa da música.","id":"q1-o1"},{"label":"Não encontrou nenhum livro na biblioteca.","id":"q1-o2"}],"correctOptionId":"q1-o1","explanation":"Nina conta que ouviu música do pátio e não conseguiu acompanhar a história."},{"id":"q2","prompt":"Que informação Davi oferece sobre o ensaio?","options":[{"label":"O grupo ensaiou no horário combinado.","id":"q2-o3"},{"label":"O ensaio aconteceu dentro da biblioteca.","id":"q2-o2"},{"label":"O grupo escolheu o horário para atrapalhar Nina.","id":"q2-o1"}],"correctOptionId":"q2-o3","explanation":"Davi afirma que o grupo seguiu o horário combinado para ensaiar."},{"id":"q3","prompt":"Os relatos provam que o grupo quis atrapalhar a leitura?","options":[{"label":"Sim. Qualquer som prova intenção de atrapalhar.","id":"q3-o3"},{"label":"Sim. Nina disse que Davi planejou atrapalhá-la.","id":"q3-o1"},{"label":"Não. Davi relata que o grupo desconhecia a leitura.","id":"q3-o2"}],"correctOptionId":"q3-o2","explanation":"Davi diz que o grupo não sabia da leitura; os registros não comprovam intenção de atrapalhar."}]}','4dfc60df291acd72356b8f4a72660d5031ca7e3540027327b9550b884e5464d5',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-association-01','v28:c1dae38c1855b35aaac9d1a03ee47e10cdbc8045f7e1f718a2f554f5245a2afe','Práticas e trajetórias com história','association','3',ARRAY[]::text[],'c1dae38c1855b35aaac9d1a03ee47e10cdbc8045f7e1f718a2f554f5245a2afe','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Consulte um registro por vez. Compare o nome da manifestação ou da autora com o trecho correspondente. Dossiê é um conjunto de informações e estudos sobre um tema; observe o tema citado, sem confundir prática cultural e documento."},"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer jongo, capoeira e produção de Carolina Maria de Jesus, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Cultura afro-brasileira","topic":"Jongo, capoeira e produção de Carolina Maria de Jesus","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":53,"printedPage":"52"},{"pdfPage":55,"printedPage":"54"},{"pdfPage":61,"printedPage":"60"}],"itemSources":[{"itemId":"p1","pdfPages":[53]},{"itemId":"p2","pdfPages":[55]},{"itemId":"p3","pdfPages":[61]}]},"id":"livros-ef3-association-01","title":"Práticas e trajetórias com história","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Releia as páginas 52, 54 e 60. Ligue cada nome à informação específica apresentada pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Jongo"},"right":{"label":"Expressão afro-brasileira da qual participa a comunidade do Tamandaré."}},{"id":"p2","left":{"label":"Capoeira"},"right":{"label":"Prática estudada no dossiê do IPHAN sobre rodas e mestres de capoeira."}},{"id":"p3","left":{"label":"Carolina Maria de Jesus"},"right":{"label":"Autora de diários, poemas, romances e canções."}}]}','c1dae38c1855b35aaac9d1a03ee47e10cdbc8045f7e1f718a2f554f5245a2afe',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-association-63','v28:dbde13a3b601d87d629d011f46842eb3297f765ebbbf88e9b89fafb44ebf206d','Mbanza Kongo: cidade e reino','association','3',ARRAY[]::text[],'dbde13a3b601d87d629d011f46842eb3297f765ebbbf88e9b89fafb44ebf206d','{"schemaVersion":1,"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Distinguir a função histórica de Mbanza Kongo e sua localização no território da atual Angola.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Cultura afro-brasileira","topic":"Distinguir a função histórica de Mbanza Kongo e sua localização no território da atual Angola.","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":46,"printedPage":"45"}],"itemSources":[{"itemId":"p1","pdfPages":[46]},{"itemId":"p2","pdfPages":[46]}]},"id":"livros-ef3-association-63","title":"Mbanza Kongo: cidade e reino","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Leia a página 45 e ligue cada aspecto de Mbanza Kongo à informação correspondente. Diferencie a cidade no antigo Reino do Kongo do país onde ela fica hoje.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Papel da cidade no Reino do Kongo"},"right":{"label":"Importante centro político e espiritual."}},{"id":"p2","left":{"label":"País atual onde a cidade fica"},"right":{"label":"Angola."}}]}','dbde13a3b601d87d629d011f46842eb3297f765ebbbf88e9b89fafb44ebf206d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-sequence-01','v28:0587f208b24af06a7b62a20cdf5699d4ae105db36bdf3dca328bb6b8890a6a09','Marcos da trajetória de Carolina','sequence','3',ARRAY[]::text[],'0587f208b24af06a7b62a20cdf5699d4ae105db36bdf3dca328bb6b8890a6a09','{"schemaVersion":1,"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer nascimento e publicação de duas obras de Carolina Maria de Jesus, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Cultura afro-brasileira","topic":"Nascimento e publicação de duas obras de Carolina Maria de Jesus","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":61,"printedPage":"60"}],"itemSources":[{"itemId":"s1","pdfPages":[61]},{"itemId":"s2","pdfPages":[61]},{"itemId":"s3","pdfPages":[61]}]},"id":"livros-ef3-sequence-01","title":"Marcos da trajetória de Carolina","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Leia a página 60 e ordene os três acontecimentos, do mais antigo ao mais recente. A atividade seleciona apenas três marcos, não toda a vida da escritora.","difficulty":"facil","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Carolina Maria de Jesus nasce em Minas Gerais.","id":"s1"},{"label":"Quarto de despejo é publicado em 1960.","id":"s2"},{"label":"Casa de alvenaria é publicado no ano seguinte.","id":"s3"}]}','0587f208b24af06a7b62a20cdf5699d4ae105db36bdf3dca328bb6b8890a6a09',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-association-64','v28:e56ac853a3036bb1819ff964a918ac9ba2657bdf071966be01604926518c01e1','Cultivo e trocas em Kalipety','association','3',ARRAY[]::text[],'e56ac853a3036bb1819ff964a918ac9ba2657bdf071966be01604926518c01e1','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Leia qual aspecto cada cartão pede: lugar, cultivo ou finalidade das trocas. Procure no texto a informação desse mesmo tipo e confira os nomes antes de ligar."},"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Localizar a tekoa Kalipety e relacionar o cultivo de batata-doce às trocas de variedades e conhecimentos entre aldeias.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas","topic":"Localizar a tekoa Kalipety e relacionar o cultivo de batata-doce às trocas de variedades e conhecimentos entre aldeias.","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":102,"printedPage":"101"},{"pdfPage":103,"printedPage":"102"}],"itemSources":[{"itemId":"p1","pdfPages":[102]},{"itemId":"p2","pdfPages":[102]},{"itemId":"p3","pdfPages":[102]}]},"id":"livros-ef3-association-64","title":"Cultivo e trocas em Kalipety","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Leia as páginas 101 e 102 e ligue cada aspecto da experiência Guarani de Kalipety à informação correspondente.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Localização da tekoa Kalipety"},"right":{"label":"Terra Indígena Tenondé Porã, em São Paulo."}},{"id":"p2","left":{"label":"Cultivo apresentado no texto"},"right":{"label":"Diferentes variedades de batata-doce."}},{"id":"p3","left":{"label":"Objetivo das trocas com outras aldeias"},"right":{"label":"Recuperar variedades e combinar conhecimentos no cuidado das roças."}}]}','e56ac853a3036bb1819ff964a918ac9ba2657bdf071966be01604926518c01e1',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-completion-01','v28:003809cb6dec9f4b66952fa80b100c3dec910c839209415ea6db4b02e2825d5d','Identificar a fonte da brincadeira','completion','3',ARRAY[]::text[],'003809cb6dec9f4b66952fa80b100c3dec910c839209415ea6db4b02e2825d5d','{"schemaVersion":1,"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer exemplo Wapixana da aldeia Canauanim em Roraima, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas","topic":"Exemplo Wapixana da aldeia Canauanim em Roraima","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":95,"printedPage":"94"}],"itemSources":[{"itemId":"b1","pdfPages":[95]},{"itemId":"b2","pdfPages":[95]},{"itemId":"b3","pdfPages":[95]}]},"id":"livros-ef3-completion-01","title":"Identificar a fonte da brincadeira","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Leia a seção “Leitura de fonte” da página 94. Complete as informações sobre o exemplo de figuras de fios, sem generalizá-lo para todos os povos indígenas.","difficulty":"facil","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"O relato de figuras de fios citado apresenta uma experiência entre os ","after":".","answers":["Wapixana"],"options":[{"label":"Kalapalo","id":"b1-o1"},{"label":"Wapixana","id":"b1-o2"},{"label":"Baniwa","id":"b1-o3"}]},{"id":"b2","before":"A aldeia citada nesse exemplo se chama ","after":".","answers":["Canauanim"],"options":[{"label":"Tuba Tuba","id":"b2-o1"},{"label":"Tamandaré","id":"b2-o2"},{"label":"Canauanim","id":"b2-o3"}]},{"id":"b3","before":"A aldeia Canauanim fica em ","after":".","answers":["Roraima"],"options":[{"label":"Roraima","id":"b3-o1"},{"label":"Paraná","id":"b3-o2"},{"label":"Minas Gerais","id":"b3-o3"}]}]}','003809cb6dec9f4b66952fa80b100c3dec910c839209415ea6db4b02e2825d5d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-01','v28:815d6640a6f8d96c37c9d107f67a6f2792a9451d2f3aa347b71311594dd4d6ce','Línguas indígenas têm valor','quiz','3',ARRAY[]::text[],'815d6640a6f8d96c37c9d107f67a6f2792a9451d2f3aa347b71311594dd4d6ce','{"schemaVersion":1,"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer diversidade linguística, FOIRN e educação no rio Negro, com apoio da fonte indicada.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas","topic":"Diversidade linguística, FOIRN e educação no rio Negro","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":85,"printedPage":"84"}],"itemSources":[{"itemId":"q1","pdfPages":[85]},{"itemId":"q2","pdfPages":[85]},{"itemId":"q3","pdfPages":[85]}]},"id":"livros-ef3-quiz-01","title":"Línguas indígenas têm valor","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Leia a página 84 e escolha a resposta apoiada no texto para cada pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"O que as línguas indígenas permitem fazer?","options":[{"label":"Apenas repetir palavras antigas.","id":"q1-o1"},{"label":"Conversar, narrar histórias e produzir conhecimentos.","id":"q1-o2"},{"label":"Somente dar nomes a plantas.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O texto apresenta essas funções e não trata as línguas indígenas como incompletas."},{"id":"q2","prompt":"O que a FOIRN defende na educação do rio Negro?","options":[{"label":"Escolas que considerem a diversidade cultural e linguística.","id":"q2-o1"},{"label":"Escolas que desconsiderem as comunidades.","id":"q2-o2"},{"label":"Uma única língua para todos os povos.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A FOIRN defende que a educação considere a diversidade dos povos da região."},{"id":"q3","prompt":"O que o uso de mais de uma língua significa no exemplo do livro?","options":[{"label":"Uma delas deve ser abandonada.","id":"q3-o1"},{"label":"As línguas indígenas são incompletas.","id":"q3-o2"},{"label":"Nenhuma delas tem menor valor por isso.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O uso de mais de uma língua não faz uma delas valer menos."}]}','815d6640a6f8d96c37c9d107f67a6f2792a9451d2f3aa347b71311594dd4d6ce',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-20','v28:e571a19107cb42d1d5103d31d80128ebf36ea06fcc5ae2fbc648f25cb36e825a','Ritxòkò: aprender com ceramistas','quiz','3',ARRAY[]::text[],'e571a19107cb42d1d5103d31d80128ebf36ea06fcc5ae2fbc648f25cb36e825a','{"schemaVersion":1,"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Investigar aprendizagem intergeracional e transformação do barro entre mulheres Iny","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas","topic":"Investigar aprendizagem intergeracional e transformação do barro entre mulheres Iny","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":93,"printedPage":"92"}],"itemSources":[{"itemId":"q1","pdfPages":[93]},{"itemId":"q2","pdfPages":[93]},{"itemId":"q3","pdfPages":[93]}]},"id":"livros-ef3-quiz-20","title":"Ritxòkò: aprender com ceramistas","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Consulte a página 92. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Como filhas e netas aprendem com ceramistas mais velhas?","options":[{"label":"Recebendo peças prontas sem acompanhar o trabalho.","id":"q1-o1"},{"label":"Observando, ajudando e desenvolvendo habilidades.","id":"q1-o2"},{"label":"Lendo somente etiquetas de museus.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O livro descreve aprendizagem no acompanhamento do trabalho, com observação e participação."},{"id":"q2","prompt":"Que etapas fazem parte da transformação do barro em figuras?","options":[{"label":"Modelagem, secagem e pintura.","id":"q2-o1"},{"label":"Impressão, encadernação e leitura.","id":"q2-o2"},{"label":"Tecelagem, corte e costura.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"As etapas citadas mostram habilidades de produção cerâmica, diferentes das usadas em livros ou tecidos."},{"id":"q3","prompt":"Em que região o texto situa o trabalho dessas ceramistas?","options":[{"label":"Vale do Ribeira.","id":"q3-o1"},{"label":"Golfo do Benim.","id":"q3-o2"},{"label":"Araguaia.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O recorte é o das mulheres Iny na região do Araguaia, não de qualquer produção cerâmica."}]}','e571a19107cb42d1d5103d31d80128ebf36ea06fcc5ae2fbc648f25cb36e825a',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-05','v28:fc6a99a50614cf03a91a2d7658846f1b2d37784fdcabc90fccc5b2c13df06c41','Histórias da população brasileira','quiz','3',ARRAY[]::text[],'fc6a99a50614cf03a91a2d7658846f1b2d37784fdcabc90fccc5b2c13df06c41','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Localize no texto as informações sobre o tempo anterior à colonização. Compare esse momento com os acontecimentos que vieram depois."},{"itemId":"q2","text":"Releia o trecho sobre a ocupação colonial. Procure as ações e suas consequências descritas na fonte, sem misturar com a situação atual."},{"itemId":"q3","text":"Agora procure o que o texto diz sobre o presente. Compare as informações encontradas com cada alternativa, sem acrescentar ideias que não estão na fonte."}]},"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Distinguir presença indígena anterior, violência colonial e participação de diferentes grupos no presente","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Formação do povo brasileiro","topic":"Distinguir presença indígena anterior, violência colonial e participação de diferentes grupos no presente","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":115,"printedPage":"114"}],"itemSources":[{"itemId":"q1","pdfPages":[115]},{"itemId":"q2","pdfPages":[115]},{"itemId":"q3","pdfPages":[115]}]},"id":"livros-ef3-quiz-05","title":"Histórias da população brasileira","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Escolha uma resposta por pergunta. Consulte a página 114. Síntese histórica do livro; migração escolhida e deslocamento forçado não são equivalentes.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual presença é anterior à colonização?","options":[{"label":"A dos colonizadores europeus.","id":"q1-o2"},{"label":"A dos grupos trazidos pelo tráfico escravista.","id":"q1-o3"},{"label":"A dos povos indígenas.","id":"q1-o1"}],"correctOptionId":"q1-o1","explanation":"O texto situa a presença dos povos indígenas antes da chegada dos colonizadores."},{"id":"q2","prompt":"O que o texto relaciona à chegada dos colonizadores europeus?","options":[{"label":"Somente viagens de visita.","id":"q2-o1"},{"label":"Ocupação, imposições e violência.","id":"q2-o3"},{"label":"A ausência de conflitos.","id":"q2-o2"}],"correctOptionId":"q2-o3","explanation":"O texto relaciona a colonização à ocupação, a imposições e à violência."},{"id":"q3","prompt":"Como o texto situa povos indígenas, populações negras e outros grupos hoje?","options":[{"label":"Participam da vida brasileira e transformam lugares.","id":"q3-o2"},{"label":"Permanecem em papéis que nunca mudam.","id":"q3-o1"},{"label":"Existem apenas nas lembranças do passado.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"O livro destaca que esses grupos continuam atuando e transformando seus lugares."}]}','fc6a99a50614cf03a91a2d7658846f1b2d37784fdcabc90fccc5b2c13df06c41',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-06','v28:8c8f42af1e9963cbe868d2e4d3b737cc96a48e13113e2d4af77827c6cc3a912f','Histórias na associação','quiz','3',ARRAY[]::text[],'8c8f42af1e9963cbe868d2e4d3b737cc96a48e13113e2d4af77827c6cc3a912f','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Compare o mesmo tipo de atividade no registro de 2005 e no de 2025. Procure o que continuou acontecendo, mesmo com outras mudanças."},{"itemId":"q2","text":"Compare somente as informações sobre o espaço nos dois anos. Veja o que o registro mais recente apresenta de diferente."}]},"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Identificar mudança, permanência e autorização em registros de 2005 e 2025","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Formação do povo brasileiro","topic":"Identificar mudança, permanência e autorização em registros de 2005 e 2025","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":125,"printedPage":"124"}],"itemSources":[{"itemId":"q1","pdfPages":[125]},{"itemId":"q2","pdfPages":[125]},{"itemId":"q3","pdfPages":[125]}]},"id":"livros-ef3-quiz-06","title":"Histórias na associação","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Escolha uma resposta por pergunta. Consulte a página 124. Caso fictício apresentado pelo livro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"O que permaneceu entre 2005 e 2025 na associação fictícia?","options":[{"label":"Os encontros para ouvir pessoas mais velhas.","id":"q1-o1"},{"label":"A ausência de qualquer gravação.","id":"q1-o3"},{"label":"O uso exclusivo da sala pequena.","id":"q1-o2"}],"correctOptionId":"q1-o1","explanation":"O relato de 2025 diz que os encontros para ouvir pessoas mais velhas continuam."},{"id":"q2","prompt":"Que mudança de espaço aparece em 2025?","options":[{"label":"A mudança para uma praça sem sala.","id":"q2-o2"},{"label":"O uso de uma sala maior.","id":"q2-o3"},{"label":"O fim dos encontros presenciais.","id":"q2-o1"}],"correctOptionId":"q2-o3","explanation":"O registro antigo cita uma sala pequena, enquanto o mais recente informa uma sala maior."},{"id":"q3","prompt":"Qual cuidado vem antes da gravação de histórias no relato?","options":[{"label":"Gravar escondido.","id":"q3-o3"},{"label":"Substituir obrigatoriamente todos os encontros.","id":"q3-o1"},{"label":"Obter autorização.","id":"q3-o2"}],"correctOptionId":"q3-o2","explanation":"O relato de 2025 explicita que algumas histórias são gravadas com autorização."}]}','8c8f42af1e9963cbe868d2e4d3b737cc96a48e13113e2d4af77827c6cc3a912f',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-07','v28:2e4f66e99c481e95479881f27af563f25c732934aebc862b6b74c0a578d5883e','Além da apresentação do boi','quiz','3',ARRAY[]::text[],'2e4f66e99c481e95479881f27af563f25c732934aebc862b6b74c0a578d5883e','{"schemaVersion":1,"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer lugar, preparação e limites do estudo escolar de uma celebração","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Formação do povo brasileiro","topic":"Reconhecer lugar, preparação e limites do estudo escolar de uma celebração","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":129,"printedPage":"128"}],"itemSources":[{"itemId":"q1","pdfPages":[129]},{"itemId":"q2","pdfPages":[129]},{"itemId":"q3","pdfPages":[129]}]},"id":"livros-ef3-quiz-07","title":"Além da apresentação do boi","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Escolha uma resposta por pergunta. Consulte a página 128. Exemplo cultural situado; não propõe realização de ritual.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Onde o livro situa o Complexo Cultural do Bumba meu boi estudado?","options":[{"label":"No rio Negro.","id":"q1-o2"},{"label":"No Maranhão.","id":"q1-o1"},{"label":"Em Tombuctu.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O texto identifica o Maranhão ao apresentar o complexo cultural estudado."},{"id":"q2","prompt":"Que trabalho também integra a celebração antes da apresentação pública?","options":[{"label":"Somente a chegada dos visitantes.","id":"q2-o1"},{"label":"Apenas a escolha do lugar pelo público.","id":"q2-o2"},{"label":"Os ensaios e a preparação.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"O livro inclui os ensaios no percurso da celebração, antes do encontro com o público."},{"id":"q3","prompt":"O que o estudo da celebração na escola exige, segundo o texto?","options":[{"label":"Conhecer sua história com respeito, sem exigir rituais.","id":"q3-o2"},{"label":"Transformar identidades em fantasias.","id":"q3-o1"},{"label":"Obrigar todas as crianças a realizar rituais.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"O livro distingue estudar a história da celebração de exigir a realização de seus rituais."}]}','2e4f66e99c481e95479881f27af563f25c732934aebc862b6b74c0a578d5883e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef3-quiz-21','v28:7d58d20a3186c8e3c5d74e1d58700e97ac0639724405deedc3fb9ed0c08e09ff','Uma biblioteca lembra Carolina','quiz','3',ARRAY[]::text[],'7d58d20a3186c8e3c5d74e1d58700e97ac0639724405deedc3fb9ed0c08e09ff','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Localize o registro que fala da escolha do nome. Confira de onde veio essa informação. A pergunta pede a fonte, não os assuntos dos livros da biblioteca."}]},"catalog":{"band":"EF3","area":"historia","batch":"livros-historia-v18","objective":"Relacionar homenagem pública, acervo e trajetória literária","readingRequired":true,"visualSupport":[]},"bookReference":{"year":3,"bookId":"historia-ef3","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Formação do povo brasileiro","topic":"Relacionar homenagem pública, acervo e trajetória literária","sourceUrl":"https://drive.google.com/file/d/1uFuNoTURIEt76hWlL1atfCAeUSNDvQrU/view","pages":[{"pdfPage":120,"printedPage":"119"},{"pdfPage":121,"printedPage":"120"}],"itemSources":[{"itemId":"q1","pdfPages":[120]},{"itemId":"q2","pdfPages":[120]},{"itemId":"q3","pdfPages":[121]}]},"id":"livros-ef3-quiz-21","title":"Uma biblioteca lembra Carolina","grade":"3º ano","subject":"História","collection":{"id":"historia-ef3","title":"História Indígena e Afro-Brasileira · 3º ano"},"description":"Consulte as páginas 119, 120. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"De que modo a biblioteca do Museu Afro Brasil homenageia Carolina?","options":[{"label":"Recebendo o nome da escritora.","id":"q1-o1"},{"label":"Atribuindo a ela a autoria de todos os livros do acervo.","id":"q1-o2"},{"label":"Apresentando-a como fundadora de todas as bibliotecas.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O nome dá visibilidade à trajetória da escritora, sem torná-la autora de todo o acervo."},{"id":"q2","prompt":"Que temas aparecem no acervo dessa biblioteca?","options":[{"label":"Somente receitas escritas por Carolina.","id":"q2-o1"},{"label":"Somente a história de uma cidade europeia.","id":"q2-o2"},{"label":"Culturas africanas, afro-brasileiras e história do Brasil.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"A diversidade dos temas mostra que a biblioteca reúne materiais para pesquisa, além da homenagem no nome."},{"id":"q3","prompt":"Qual fonte explica a escolha do nome da biblioteca?","options":[{"label":"Uma ficha de uma brincadeira Kalapalo.","id":"q3-o1"},{"label":"O site do Museu Afro Brasil.","id":"q3-o2"},{"label":"Um mapa do Araguaia.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"O registro A informa explicitamente que o nome foi escolhido em homenagem à escritora."}]}','7d58d20a3186c8e3c5d74e1d58700e97ac0639724405deedc3fb9ed0c08e09ff',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-sequence-01','v28:3197a7801369f1511666731e7a0d8f9a62c3737c08b71f543e1a607fcfdf446b','O caminho de um saber','sequence','4',ARRAY[]::text[],'3197a7801369f1511666731e7a0d8f9a62c3737c08b71f543e1a607fcfdf446b','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer aprendizagem, transmissão e transformação de um saber em uma narrativa fictícia.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Caminhos que transformam histórias","topic":"Diversidade cultural: Um saber em circulação","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":13,"printedPage":"12"}],"itemSources":[{"itemId":"s1","pdfPages":[13]},{"itemId":"s2","pdfPages":[13]},{"itemId":"s3","pdfPages":[13]}]},"id":"livros-ef4-sequence-01","title":"O caminho de um saber","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Leia a situação fictícia de Lia na página 12. Ordene as três etapas desse exemplo inventado de compartilhamento de um saber.","difficulty":"medio","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Lia aprende com a tia a trançar tiras de papel.","id":"s1"},{"label":"Ao mudar de cidade, Lia ensina os colegas.","id":"s2"},{"label":"O grupo cria novos objetos, registra quem ensinou e explica as mudanças.","id":"s3"}]}','3197a7801369f1511666731e7a0d8f9a62c3737c08b71f543e1a607fcfdf446b',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-association-01','v28:b2676d14316b024d4dbaeea1b9350a1971e46fcc9dad1b3a55837392623f5c64','Localizando Kilwa Kisiwani','association','4',ARRAY[]::text[],'b2676d14316b024d4dbaeea1b9350a1971e46fcc9dad1b3a55837392623f5c64','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Distinguir continente, país e oceano na localização de Kilwa Kisiwani.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · África e Brasil: história e cultura","topic":"O continente africano: chaves do localizador","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":45,"printedPage":"44"}],"itemSources":[{"itemId":"p1","pdfPages":[45]},{"itemId":"p2","pdfPages":[45]},{"itemId":"p3","pdfPages":[45]}]},"id":"livros-ef4-association-01","title":"Localizando Kilwa Kisiwani","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Leia as chaves do localizador na página 44. Ligue cada nome à informação correspondente.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"África"},"right":{"label":"Continente indicado no localizador."}},{"id":"p2","left":{"label":"Tanzânia"},"right":{"label":"País atual destacado no localizador."}},{"id":"p3","left":{"label":"Oceano Índico"},"right":{"label":"Oceano a leste da costa africana mostrada."}}]}','b2676d14316b024d4dbaeea1b9350a1971e46fcc9dad1b3a55837392623f5c64',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-quiz-01','v28:36021abf073ac56430869202dac47504c2967db78d4c3a33404de0597b70ccd6','Jongo: música, história e fontes','quiz','4',ARRAY[]::text[],'36021abf073ac56430869202dac47504c2967db78d4c3a33404de0597b70ccd6','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Relacionar o jongo à história das comunidades e reconhecer limites de imagens.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · África e Brasil: história e cultura","topic":"Música e dança afro-brasileira","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":56,"printedPage":"55"}],"itemSources":[{"itemId":"q1","pdfPages":[56]},{"itemId":"q2","pdfPages":[56]},{"itemId":"q3","pdfPages":[56]}]},"id":"livros-ef4-quiz-01","title":"Jongo: música, história e fontes","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Leia a página 55 e responda sobre o jongo e os limites de uma fotografia.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Além de reunir pessoas, a história do jongo está ligada a quê?","options":[{"label":"À comunicação e à resistência no contexto da escravidão.","id":"o1"},{"label":"Somente a apresentações de palco.","id":"o2"},{"label":"Somente à fabricação de instrumentos.","id":"o3"}],"correctOptionId":"o1","explanation":"O livro destaca, com base no IPHAN, comunicação e resistência na história do jongo."},{"id":"q2","prompt":"O que uma fotografia do jongo, sozinha, não permite?","options":[{"label":"Observar um instrumento visível.","id":"o1"},{"label":"Ver pessoas que aparecem na roda.","id":"o2"},{"label":"Ouvir o canto e compreender seu significado.","id":"o3"}],"correctOptionId":"o3","explanation":"Uma fotografia registra um instante; legendas e outras fontes ajudam a compreender a prática."},{"id":"q3","prompt":"Que atitude o texto recomenda ao estudar o jongo na escola?","options":[{"label":"Apresentar a dança apenas como enfeite.","id":"o1"},{"label":"Reconhecer o trabalho de mestres, mestras e participantes.","id":"o2"},{"label":"Imitar elementos desconhecidos sem procurar informações.","id":"o3"}],"correctOptionId":"o2","explanation":"O texto valoriza os participantes e seus conhecimentos."}]}','36021abf073ac56430869202dac47504c2967db78d4c3a33404de0597b70ccd6',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-quiz-40','v28:9b5be6c158780a98ebc56d8a190928c1cfc7a03cc2fcba9f35f20d3a06c7793d','Cidades suaílis e comércio','quiz','4',ARRAY[]::text[],'9b5be6c158780a98ebc56d8a190928c1cfc7a03cc2fcba9f35f20d3a06c7793d','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer as conexões comerciais entre regiões africanas e asiáticas e situar Kilwa Kisiwani e Songo Mnara como cidades suaílis","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · África e Brasil: história e cultura","topic":"Reconhecer as conexões comerciais entre regiões africanas e asiáticas e situar Kilwa Kisiwani e Songo Mnara como cidades suaílis","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":43,"printedPage":"42"},{"pdfPage":47,"printedPage":"46"}],"itemSources":[{"itemId":"q1","pdfPages":[43]},{"itemId":"q2","pdfPages":[47]}]},"id":"livros-ef4-quiz-40","title":"Cidades suaílis e comércio","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Consulte as páginas 42, 46. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que regiões as redes comerciais de Kilwa Kisiwani conectavam, segundo o texto?","options":[{"label":"Cidades brasileiras e lugares da América Central.","id":"q1-o1"},{"label":"Cidades americanas e portos europeus.","id":"q1-o2"},{"label":"Regiões africanas e lugares da Ásia.","id":"q1-o3"}],"correctOptionId":"q1-o3","explanation":"O texto apresenta Kilwa como participante de redes que ligavam regiões africanas à Ásia. Esse comércio mostra conexões de longa distância, além da localização da cidade no mapa."},{"id":"q2","prompt":"Segundo a informação da UNESCO citada no livro, o que eram Kilwa Kisiwani e Songo Mnara?","options":[{"label":"Cidades comerciais suaílis.","id":"q2-o1"},{"label":"Países africanos atuais.","id":"q2-o2"},{"label":"Bibliotecas de manuscritos.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A UNESCO as descreve como cidades comerciais suaílis relacionadas aos circuitos do Índico. São dois lugares históricos específicos, não países nem uma descrição de todo o continente."}]}','9b5be6c158780a98ebc56d8a190928c1cfc7a03cc2fcba9f35f20d3a06c7793d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-quiz-41','v28:51b8b1f054e7806b0295d7297690f5b487bfebd42e6ab73e1146dc7347e7ab78','Luiz Gama: escrita e imprensa','quiz','4',ARRAY[]::text[],'51b8b1f054e7806b0295d7297690f5b487bfebd42e6ab73e1146dc7347e7ab78','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Relacionar a atuação de Luiz Gama na imprensa ao uso da escrita nas lutas contra a escravidão","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · África e Brasil: história e cultura","topic":"Relacionar a atuação de Luiz Gama na imprensa ao uso da escrita nas lutas contra a escravidão","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":63,"printedPage":"62"}],"itemSources":[{"itemId":"q1","pdfPages":[63]},{"itemId":"q2","pdfPages":[63]}]},"id":"livros-ef4-quiz-41","title":"Luiz Gama: escrita e imprensa","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Consulte a página 62. Escolha uma resposta por pergunta.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual meio de comunicação a ficha relaciona à atuação de Luiz Gama?","options":[{"label":"Rádio.","id":"q1-o1"},{"label":"Imprensa.","id":"q1-o2"},{"label":"Cinema.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"A ficha cita a imprensa, e o texto apresenta Gama como jornalista. Esse recorte permite estudar sua participação na comunicação escrita de sua época."},{"id":"q2","prompt":"Que relação o livro estabelece entre a escrita de Luiz Gama e os conflitos de sua época?","options":[{"label":"A escrita servia apenas para registrar lembranças familiares.","id":"q2-o1"},{"label":"A escrita ficava separada de sua atuação abolicionista.","id":"q2-o2"},{"label":"A escrita também era um instrumento de luta pela liberdade.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"Ao apresentar Gama como escritor, jornalista e abolicionista, o texto relaciona sua escrita à luta pela liberdade. Escrever também era uma forma de participar dos conflitos de sua época."}]}','51b8b1f054e7806b0295d7297690f5b487bfebd42e6ab73e1146dc7347e7ab78',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-completion-01','v28:299a7b0aa7a8d431e55e7bf0d897491afcca5458a37649b529ee8681c137f07a','Identidade indígena no presente','completion','4',ARRAY[]::text[],'299a7b0aa7a8d431e55e7bf0d897491afcca5458a37649b529ee8681c137f07a','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer a presença indígena no presente e evitar julgamentos de identidade pela aparência.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas do Brasil","topic":"Quem são os povos indígenas","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":80,"printedPage":"79"}],"itemSources":[{"itemId":"b1","pdfPages":[80]},{"itemId":"b2","pdfPages":[80]},{"itemId":"b3","pdfPages":[80]}]},"id":"livros-ef4-completion-01","title":"Identidade indígena no presente","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Leia a página 79. Complete cada frase com a opção que respeita as informações do texto.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"Os povos indígenas são povos ","after":" com histórias e formas próprias de organização.","answers":["originários"],"options":[{"label":"originários","id":"o1"},{"label":"idênticos","id":"o2"},{"label":"desaparecidos","id":"o3"}]},{"id":"b2","before":"Uma pessoa indígena pode morar numa aldeia ou numa ","after":".","answers":["cidade"],"options":[{"label":"cidade","id":"o1"},{"label":"época","id":"o2"},{"label":"fotografia","id":"o3"}]},{"id":"b3","before":"Ao estudar um povo, devemos procurar como ele se apresenta e respeitar seu ","after":".","answers":["nome"],"options":[{"label":"nome","id":"o1"},{"label":"silenciamento","id":"o2"},{"label":"esquecimento","id":"o3"}]}]}','299a7b0aa7a8d431e55e7bf0d897491afcca5458a37649b529ee8681c137f07a',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-quiz-20','v28:3c83502d442e871e216c434a9823e543429d191954163f2f2cb2114ebaf6e19b','Wayana e Aparai: uma publicação','quiz','4',ARRAY[]::text[],'3c83502d442e871e216c434a9823e543429d191954163f2f2cb2114ebaf6e19b','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q2","text":"Releia o trecho sobre pessoas de diferentes gerações. Observe os verbos usados para explicar o que acontece com os sistemas gráficos ao longo do tempo."}]},"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Ler uma publicação situada sobre sistemas gráficos e sua transmissão","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas do Brasil","topic":"Ler uma publicação situada sobre sistemas gráficos e sua transmissão","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":96,"printedPage":"95"},{"pdfPage":97,"printedPage":"96"}],"itemSources":[{"itemId":"q1","pdfPages":[96]},{"itemId":"q2","pdfPages":[96]},{"itemId":"q3","pdfPages":[97]}]},"id":"livros-ef4-quiz-20","title":"Wayana e Aparai: uma publicação","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Consulte as páginas 95, 96. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quais comunidades são apresentadas nessa publicação?","options":[{"label":"Wayana e Aparai ao longo do rio Paru d’Este.","id":"q1-o1"},{"label":"Iny ao longo do Araguaia.","id":"q1-o2"},{"label":"Shona em Grande Zimbábue.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"A identificação do rio e dos povos delimita o recorte da obra, em vez de reunir artes de origens diferentes."},{"id":"q2","prompt":"Como o texto descreve a relação entre gerações e sistemas gráficos?","options":[{"label":"Os sistemas deixam de ser ensinados.","id":"q2-o1"},{"label":"Os sistemas são apenas importados de museus.","id":"q2-o2"},{"label":"Os sistemas são transmitidos e recriados.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"Transmitir e recriar indica aprendizagem e transformação entre gerações."},{"id":"q3","prompt":"Qual dado da ficha mostra quando a publicação foi lançada?","options":[{"label":"O ano de 1770.","id":"q3-o1"},{"label":"O ano de 2010.","id":"q3-o2"},{"label":"A data de 1945.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"2010 é o ano de publicação registrado na ficha, não uma data de origem de toda a arte desses povos."}]}','3c83502d442e871e216c434a9823e543429d191954163f2f2cb2114ebaf6e19b',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-association-02','v28:56a8db18b6e8bfb46a44e7a7236120a3911ef3ff728d78ce1655b08fc40f4cab','Ler o espaço da mostra','association','4',ARRAY[]::text[],'56a8db18b6e8bfb46a44e7a7236120a3911ef3ff728d78ce1655b08fc40f4cab','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer condições distintas no esquema fictício de circulação da mostra.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Respeito, cidadania e convivência","topic":"Reconhecer condições distintas no esquema fictício de circulação da mostra.","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":129,"printedPage":"128"}],"itemSources":[{"itemId":"p1","pdfPages":[129]},{"itemId":"p2","pdfPages":[129]},{"itemId":"p3","pdfPages":[129]}]},"id":"livros-ef4-association-02","title":"Ler o espaço da mostra","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Na página 128, leia a descrição do esquema fictício. Ele não está em escala. Ligue cada elemento à condição descrita. O esquema não é uma planta técnica nem uma proposta de obra.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Caixas no esquema"},"right":{"label":"Estreitam a passagem."}},{"id":"p2","left":{"label":"Painel no esquema"},"right":{"label":"Está muito alto."}},{"id":"p3","left":{"label":"Mesa de consulta no esquema"},"right":{"label":"Tem um caminho livre de acesso."}}]}','56a8db18b6e8bfb46a44e7a7236120a3911ef3ff728d78ce1655b08fc40f4cab',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-quiz-02','v28:7632e68d2182ddae636b348d3c7d76d24ca07e471a7d04ac91a939e945c996f5','Escutar antes de dividir tarefas','quiz','4',ARRAY[]::text[],'7632e68d2182ddae636b348d3c7d76d24ca07e471a7d04ac91a939e945c996f5','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Distinguir preferências expressas e sobrecarga nos casos fictícios de Lara, Caio e Joana.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Respeito, cidadania e convivência","topic":"Distinguir preferências expressas e sobrecarga nos casos fictícios de Lara, Caio e Joana.","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":122,"printedPage":"121"},{"pdfPage":135,"printedPage":"134"}],"itemSources":[{"itemId":"q1","pdfPages":[122]},{"itemId":"q2","pdfPages":[122]},{"itemId":"q3","pdfPages":[135]}]},"id":"livros-ef4-quiz-02","title":"Escutar antes de dividir tarefas","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"Analise os casos fictícios do livro nas páginas 121 e 134. Escolha combinações que respeitem as falas e repartam o trabalho.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Lara diz que quer participar sem falar ao microfone. Que combinação atende ao pedido?","options":[{"label":"Oferecer uma tarefa de participação sem fala ao microfone.","id":"q1-o1"},{"label":"Retirá-la de todas as tarefas.","id":"q1-o2"},{"label":"Inscrevê-la para falar ao microfone sem consultar.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"Lara quer participar e apenas recusa o microfone. Sua fala não justifica excluí-la das demais tarefas."},{"id":"q2","prompt":"Caio gosta de apresentar, mas faz qual pedido?","options":[{"label":"Não participar da mostra.","id":"q2-o1"},{"label":"Ler o texto antes da apresentação.","id":"q2-o2"},{"label":"Trocar todos os temas da exposição.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"Caio pede preparação antes de apresentar. Ele não recusa a apresentação."},{"id":"q3","prompt":"No caso fictício, Joana ficou com a escrita, a revisão e a montagem. O que precisa mudar?","options":[{"label":"Os colegas devem apenas assinar os painéis.","id":"q3-o1"},{"label":"Joana deve continuar fazendo tudo porque faz melhor.","id":"q3-o2"},{"label":"Os colegas devem combinar tarefas próprias e repartir o trabalho.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O elogio a Joana não divide o trabalho. O caso mostra que os demais não assumiram tarefas próprias."}]}','7632e68d2182ddae636b348d3c7d76d24ca07e471a7d04ac91a939e945c996f5',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef4-quiz-03','v28:9db1fe0275d38c46fc4e533b714b3c28943e5202c877f6b420f3bda25e261a22','Uma regra para revisar','quiz','4',ARRAY[]::text[],'9db1fe0275d38c46fc4e533b714b3c28943e5202c877f6b420f3bda25e261a22','{"schemaVersion":1,"catalog":{"band":"EF4","area":"historia","batch":"livros-historia-v18","objective":"Analisar a regra fictícia que exclui da mostra quem erra uma legenda.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":4,"bookId":"historia-ef4","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Respeito, cidadania e convivência","topic":"Analisar a regra fictícia que exclui da mostra quem erra uma legenda.","sourceUrl":"https://drive.google.com/file/d/1xMCt6ZUq0SwCTRcljz3edjSO-bXCpnBE/view","pages":[{"pdfPage":124,"printedPage":"123"}],"itemSources":[{"itemId":"q1","pdfPages":[124]},{"itemId":"q2","pdfPages":[124]},{"itemId":"q3","pdfPages":[124]}]},"id":"livros-ef4-quiz-03","title":"Uma regra para revisar","grade":"4º ano","subject":"História","collection":{"id":"historia-ef4","title":"História Indígena e Afro-Brasileira · 4º ano"},"description":"O livro apresenta uma regra fictícia: quem errar uma legenda fica excluído de todas as atividades. Use a página 123 para analisar e revisar essa regra.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Uma regra proíbe toda participação de quem erra a leitura. Por que ela é inadequada?","options":[{"label":"Transforma um erro de leitura em exclusão de um direito.","id":"q1-o1"},{"label":"Garante que todos aprendam com apoio.","id":"q1-o2"},{"label":"Distribui igualmente as tarefas.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O texto afirma que responsabilidades não autorizam retirar direitos essenciais como castigo."},{"id":"q2","prompt":"Qual revisão da regra ajuda a melhorar a leitura sem excluir?","options":[{"label":"Impedir o estudante de visitar a mostra.","id":"q2-o1"},{"label":"Expor o erro num cartaz com seu nome.","id":"q2-o3"},{"label":"Oferecer ensaio e apoio para revisar a leitura.","id":"q2-o2"}],"correctOptionId":"q2-o2","explanation":"Apoiar a aprendizagem responde à dificuldade de leitura; impedir toda participação não ajuda a aprender."},{"id":"q3","prompt":"Qual documento citado reconhece crianças e adolescentes como pessoas que têm direitos?","options":[{"label":"O cartaz com a regra fictícia de exclusão.","id":"q3-o1"},{"label":"O Estatuto da Criança e do Adolescente.","id":"q3-o3"},{"label":"A lista de tarefas da mostra.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"O livro cita o ECA como referência para reconhecer crianças e adolescentes como sujeitos de direitos."}]}','9db1fe0275d38c46fc4e533b714b3c28943e5202c877f6b420f3bda25e261a22',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-sequence-01','v28:7acb8a2abbbc5e0f552a7d5ae6e80f20bdd9251c03ec2dc76f954280494c1308','Participar e acompanhar mudanças','sequence','5',ARRAY[]::text[],'7acb8a2abbbc5e0f552a7d5ae6e80f20bdd9251c03ec2dc76f954280494c1308','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Compreender que a participação coletiva inclui conhecer necessidades, propor e acompanhar.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Identidade, cidadania e direitos","topic":"Cidadania: proposta para o recreio","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":21,"printedPage":"20"}],"itemSources":[{"itemId":"s1","pdfPages":[21]},{"itemId":"s2","pdfPages":[21]},{"itemId":"s3","pdfPages":[21]}]},"id":"livros-ef5-sequence-01","title":"Participar e acompanhar mudanças","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia o exemplo imaginado de melhoria do recreio na página 20. Organize as três etapas apresentadas pelo texto.","difficulty":"medio","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Antes de escolher a proposta, a turma observa o espaço, ouve colegas e registra problemas.","id":"s1"},{"label":"A turma apresenta suas ideias à escola.","id":"s2"},{"label":"Mais tarde, a turma verifica o que mudou e o que ainda precisa de atenção.","id":"s3"}]}','7acb8a2abbbc5e0f552a7d5ae6e80f20bdd9251c03ec2dc76f954280494c1308',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-association-01','v28:15e5728f3255380b97e9ea362d5e7af1e8e1fb8c6e700fdf24498b5ed3e0bb9e','Conhecendo os três Poderes','association','5',ARRAY[]::text[],'15e5728f3255380b97e9ea362d5e7af1e8e1fb8c6e700fdf24498b5ed3e0bb9e','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Leia uma função por vez e identifique sua ação principal. Volte às páginas indicadas para conferir a qual Poder o texto atribui essa função, sem se guiar apenas por palavras parecidas."},"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Distinguir funções dos três Poderes sem atribuir todas as decisões a um único cargo.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Organização do Estado brasileiro","topic":"Funções do Executivo, Legislativo e Judiciário","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":39,"printedPage":"38"},{"pdfPage":41,"printedPage":"40"},{"pdfPage":43,"printedPage":"42"}],"itemSources":[{"itemId":"p1","pdfPages":[39]},{"itemId":"p2","pdfPages":[41]},{"itemId":"p3","pdfPages":[43]}]},"id":"livros-ef5-association-01","title":"Conhecendo os três Poderes","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia as páginas 38, 40 e 42. Relacione cada Poder à função destacada no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Poder Executivo"},"right":{"label":"Administra ações e serviços públicos."}},{"id":"p2","left":{"label":"Poder Legislativo"},"right":{"label":"Discute e vota propostas de leis e fiscaliza ações do Executivo."}},{"id":"p3","left":{"label":"Poder Judiciário"},"right":{"label":"Examina questões apresentadas à Justiça e decide com base na Constituição e nas leis."}}]}','15e5728f3255380b97e9ea362d5e7af1e8e1fb8c6e700fdf24498b5ed3e0bb9e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-65','v28:db990e313e116db069dc813c2adcf4c073d20878e08d3a9ba1d0ba7b2c5e027a','Estado, governo e federação','quiz','5',ARRAY[]::text[],'db990e313e116db069dc813c2adcf4c073d20878e08d3a9ba1d0ba7b2c5e027a','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Compare o que cada termo inclui e como o texto trata as mudanças ao longo do tempo. Confira as duas partes de cada alternativa antes de escolher."},{"itemId":"q2","text":"Faça uma lista dos componentes citados no livro. Compare-a com cada alternativa, verificando todos os nomes."},{"itemId":"q3","text":"Localize no texto as responsabilidades e a relação entre as partes da federação. Confira se a alternativa respeita as duas informações."},{"itemId":"q4","text":"Leia a palavra junto da expressão em que aparece. Compare esse uso com o sentido de Estado brasileiro apresentado no texto."}]},"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Distinguir Estado e governo, reconhecer a composição federativa e compreender responsabilidades e sentidos da palavra estado.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Organização do Estado brasileiro","topic":"Distinguir Estado e governo, reconhecer a composição federativa e compreender responsabilidades e sentidos da palavra estado.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":37,"printedPage":"36"},{"pdfPage":38,"printedPage":"37"}],"itemSources":[{"itemId":"q1","pdfPages":[37]},{"itemId":"q2","pdfPages":[37]},{"itemId":"q3","pdfPages":[37]},{"itemId":"q4","pdfPages":[37]}]},"id":"livros-ef5-quiz-65","title":"Estado, governo e federação","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia as páginas 36 e 37 e escolha uma resposta por pergunta sobre a organização do Estado brasileiro.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"O que distingue o Estado do governo?","options":[{"label":"O Estado é a equipe que governa por um período; o governo reúne território e população.","id":"q1-o1"},{"label":"O Estado e o governo são dois nomes para a mesma equipe de governantes.","id":"q1-o2"},{"label":"O Estado envolve instituições, regras, população e território; o governo dirige ações por um período.","id":"q1-o3"}],"correctOptionId":"q1-o3","explanation":"Os governantes podem mudar sem que o Estado desapareça."},{"id":"q2","prompt":"Quais partes compõem a federação brasileira?","options":[{"label":"União, estados, Distrito Federal e municípios.","id":"q2-o1"},{"label":"União, estados, municípios e os três Poderes.","id":"q2-o2"},{"label":"União, estados, capitais e bairros.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A federação reúne os quatro componentes, incluindo o Distrito Federal."},{"id":"q3","prompt":"Como se relacionam as partes da federação?","options":[{"label":"A União define todas as responsabilidades e os municípios apenas recebem ordens.","id":"q3-o1"},{"label":"Cada parte tem responsabilidades próprias e também precisa cooperar com as outras.","id":"q3-o2"},{"label":"Cada parte cuida de suas responsabilidades sem precisar de ações conjuntas.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"Responsabilidades próprias e cooperação convivem na federação."},{"id":"q4","prompt":"Na expressão “estado da Bahia”, a palavra “estado” indica o quê?","options":[{"label":"A equipe que governa o país por um período.","id":"q4-o1"},{"label":"A organização política de todo o país.","id":"q4-o2"},{"label":"Uma das unidades que compõem a federação.","id":"q4-o3"}],"correctOptionId":"q4-o3","explanation":"Nesse contexto, Bahia é uma unidade da federação, não o Estado brasileiro inteiro."}]}','db990e313e116db069dc813c2adcf4c073d20878e08d3a9ba1d0ba7b2c5e027a',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-66','v28:dfa000935d3b30fca20aab8df3ef723ab2d9728c338fe907e920d341af92cdaf','Órgãos e esferas do Estado','quiz','5',ARRAY[]::text[],'dfa000935d3b30fca20aab8df3ef723ab2d9728c338fe907e920d341af92cdaf','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Confira uma esfera por vez nas páginas indicadas. Compare cada nome de cargo com a esfera correspondente e só depois avalie a alternativa inteira."},{"itemId":"q3","text":"Organize as esferas em linhas separadas e consulte o nome de cada órgão. Verifique todas as ligações, pois uma alternativa pode misturar informações certas e erradas."},{"itemId":"q4","text":"Separe duas perguntas: onde o fórum fica e a qual organização da Justiça ele pertence. Procure no texto o que pode ser concluído sobre cada uma."}]},"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer cargos e órgãos nas esferas da federação e compreender que os municípios não possuem Judiciário próprio.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Organização do Estado brasileiro","topic":"Reconhecer cargos e órgãos nas esferas da federação e compreender que os municípios não possuem Judiciário próprio.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":39,"printedPage":"38"},{"pdfPage":41,"printedPage":"40"},{"pdfPage":43,"printedPage":"42"},{"pdfPage":44,"printedPage":"43"}],"itemSources":[{"itemId":"q1","pdfPages":[39]},{"itemId":"q2","pdfPages":[41]},{"itemId":"q3","pdfPages":[41]},{"itemId":"q4","pdfPages":[43]}]},"id":"livros-ef5-quiz-66","title":"Órgãos e esferas do Estado","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia as páginas 38, 40, 42 e 43. Escolha uma resposta por pergunta sobre a organização dos órgãos e cargos nas diferentes esferas.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual alternativa liga corretamente cada esfera da federação a quem dirige seu Poder Executivo?","options":[{"label":"Municípios: governadores; estados e Distrito Federal: prefeitos; União: Presidência da República.","id":"q1-o1"},{"label":"Municípios: prefeitos; estados e Distrito Federal: governadores; União: Presidência da República.","id":"q1-o2"},{"label":"Municípios e Distrito Federal: prefeitos; estados: governadores; União: Presidência da República.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"Prefeitos dirigem o Executivo municipal; estados e Distrito Federal têm governadores."},{"id":"q2","prompt":"Quais órgãos formam o Congresso Nacional?","options":[{"label":"Assembleias legislativas e câmaras de vereadores.","id":"q2-o1"},{"label":"Senado Federal e Câmara Legislativa do Distrito Federal.","id":"q2-o2"},{"label":"Câmara dos Deputados e Senado Federal.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"O Congresso Nacional reúne essas duas casas do Legislativo da União."},{"id":"q3","prompt":"Qual alternativa liga corretamente cada esfera da federação ao seu órgão do Legislativo?","options":[{"label":"Estados: assembleias legislativas; municípios: câmaras de vereadores; Distrito Federal: Câmara Legislativa.","id":"q3-o1"},{"label":"Estados: câmaras de vereadores; municípios: assembleias legislativas; Distrito Federal: Câmara Legislativa.","id":"q3-o2"},{"label":"Estados: assembleias legislativas; municípios: Câmara Legislativa; Distrito Federal: câmara de vereadores.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"O texto distingue assembleias estaduais, câmaras municipais e a Câmara Legislativa do Distrito Federal."},{"id":"q4","prompt":"Existe um fórum em uma cidade. Isso permite afirmar que o município tem um Judiciário próprio?","options":[{"label":"Que a cidade possui um Judiciário municipal por sediar o fórum.","id":"q4-o1"},{"label":"Que o fórum pode estar na cidade, mas o município não possui Judiciário próprio.","id":"q4-o2"},{"label":"Que o prefeito passa a dirigir o Judiciário instalado no município.","id":"q4-o3"}],"correctOptionId":"q4-o2","explanation":"A localização do fórum não cria um Judiciário municipal."}]}','dfa000935d3b30fca20aab8df3ef723ab2d9728c338fe907e920d341af92cdaf',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-association-02','v28:afa21403de3343034b70f2e66891d828bf02179af8e81cf767b89cf2d90c8a44','Ler créditos de um calendário','association','5',ARRAY[]::text[],'afa21403de3343034b70f2e66891d828bf02179af8e81cf767b89cf2d90c8a44','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Relacionar finalidade e autoria no calendário ecológico do rio Tiquié.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas contemporâneos","topic":"Relacionar finalidade e autoria no calendário ecológico do rio Tiquié.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":77,"printedPage":"76"}],"itemSources":[{"itemId":"p1","pdfPages":[77]},{"itemId":"p2","pdfPages":[77]},{"itemId":"p3","pdfPages":[77]}]},"id":"livros-ef5-association-02","title":"Ler créditos de um calendário","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia a página 76 e associe cada referência à informação correspondente. A atividade analisa créditos e finalidades, sem reproduzir o calendário.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Calendário ecológico do rio Tiquié citado pela FOIRN"},"right":{"label":"Relaciona fenômenos ambientais e atividades."}},{"id":"p2","left":{"label":"Cesar Meira Barbosa (Tuyuka)"},"right":{"label":"Autor do desenho mencionado nos créditos."}},{"id":"p3","left":{"label":"Calendário escolar, usado na comparação"},"right":{"label":"Informa períodos de aulas."}}]}','afa21403de3343034b70f2e66891d828bf02179af8e81cf767b89cf2d90c8a44',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-02','v28:9896e85bd0bb8c6611a869559c8196dd8c4ff2e05b09d2daf36e37bd4f5f6a97','Takumã Kuikuro e escolhas de cinema','quiz','5',ARRAY[]::text[],'9896e85bd0bb8c6611a869559c8196dd8c4ff2e05b09d2daf36e37bd4f5f6a97','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Examinar autoria e recortes na produção audiovisual de Takumã Kuikuro.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas contemporâneos","topic":"Examinar autoria e recortes na produção audiovisual de Takumã Kuikuro.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":71,"printedPage":"70"}],"itemSources":[{"itemId":"q1","pdfPages":[71]},{"itemId":"q2","pdfPages":[71]},{"itemId":"q3","pdfPages":[71]}]},"id":"livros-ef5-quiz-02","title":"Takumã Kuikuro e escolhas de cinema","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia a página 70 e escolha uma resposta para cada questão.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual trabalho de Takumã Kuikuro é apresentado no livro?","options":[{"label":"Construção de estradas e pontes.","id":"q1-o2"},{"label":"Produção audiovisual e documentação cultural.","id":"q1-o1"},{"label":"Organização do Censo Demográfico.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O livro apresenta Takumã Kuikuro como cineasta, destacando sua atuação na produção e interpretação de imagens."},{"id":"q2","prompt":"Por que um filme não é uma visão completa e neutra do que acontece?","options":[{"label":"Há escolhas de tema, enquadramento e organização das cenas.","id":"q2-o2"},{"label":"A câmera registra todos os acontecimentos de todos os lugares.","id":"q2-o1"},{"label":"Nenhuma pessoa interfere nas cenas selecionadas.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"As decisões de quem produz o filme selecionam o que o público verá. Por isso, o registro tem recortes."},{"id":"q3","prompt":"O caso apresentado permite concluir que todos os cineastas indígenas trabalham do mesmo modo?","options":[{"label":"Sim; uma trajetória descreve qualquer cineasta.","id":"q3-o1"},{"label":"Sim; a ferramenta determina uma cultura única.","id":"q3-o2"},{"label":"Não; o caso não representa todos os cineastas ou povos.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O próprio texto limita o alcance desse exemplo: uma trajetória não descreve todos os cineastas nem todos os povos."}]}','9896e85bd0bb8c6611a869559c8196dd8c4ff2e05b09d2daf36e37bd4f5f6a97',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-03','v28:0fa5133cd4a5d159249b0f44f491f615a886b27fab19baf482ef014b69009cbd','Apiwtxa: ações planejadas','quiz','5',ARRAY[]::text[],'0fa5133cd4a5d159249b0f44f491f615a886b27fab19baf482ef014b69009cbd','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q2","text":"Localize o trecho que reúne as ações do projeto. Leia todos os elementos de cada conjunto e confira se o texto dá apoio a cada um deles."}]},"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer organização, ações e responsabilidades no projeto Alto Juruá.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas contemporâneos","topic":"Reconhecer organização, ações e responsabilidades no projeto Alto Juruá.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":73,"printedPage":"72"},{"pdfPage":79,"printedPage":"78"}],"itemSources":[{"itemId":"q1","pdfPages":[73]},{"itemId":"q2","pdfPages":[79]},{"itemId":"q3","pdfPages":[79]}]},"id":"livros-ef5-quiz-03","title":"Apiwtxa: ações planejadas","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia as páginas 72 e 78 e escolha uma resposta para cada questão.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quem coordenou o projeto Alto Juruá citado no livro?","options":[{"label":"A equipe do Censo Demográfico.","id":"q1-o2"},{"label":"A Associação Ashaninka do Rio Amônia, Apiwtxa.","id":"q1-o1"},{"label":"O cineasta Takumã Kuikuro.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O projeto é apresentado como ação coordenada por uma associação indígena identificada pelo nome Apiwtxa."},{"id":"q2","prompt":"Qual conjunto de iniciativas o livro apresenta como ações da Apiwtxa?","options":[{"label":"Somente divulgação de fotografias de paisagens.","id":"q2-o1"},{"label":"Apenas produção de filmes de ficção.","id":"q2-o3"},{"label":"Produção agroflorestal, formação e gestão territorial.","id":"q2-o2"}],"correctOptionId":"q2-o2","explanation":"O caso reúne diferentes iniciativas e evidencia planejamento e cooperação, não apenas uma intenção individual."},{"id":"q3","prompt":"Além das ações comunitárias, de que depende a proteção territorial, segundo o texto?","options":[{"label":"Do cumprimento de responsabilidades públicas.","id":"q3-o3"},{"label":"Apenas da boa vontade de uma criança.","id":"q3-o1"},{"label":"Da ausência de qualquer planejamento.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"O texto recusa atribuir somente aos povos indígenas a obrigação de proteger ambientes dos quais toda a sociedade depende."}]}','0fa5133cd4a5d159249b0f44f491f615a886b27fab19baf482ef014b69009cbd',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-association-68','v28:486584829672903c865afdbfff4aa57c32904cb569261fedfbc9f574198f903e','Aksum: conexões e mudança religiosa','association','5',ARRAY[]::text[],'486584829672903c865afdbfff4aa57c32904cb569261fedfbc9f574198f903e','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Relacionar o porto de Adulis às conexões de Aksum e Ezana à adoção do cristianismo no século IV.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · África: diversidade e história","topic":"Relacionar o porto de Adulis às conexões de Aksum e Ezana à adoção do cristianismo no século IV.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":97,"printedPage":"96"},{"pdfPage":103,"printedPage":"102"}],"itemSources":[{"itemId":"p1","pdfPages":[97]},{"itemId":"p2","pdfPages":[103]}]},"id":"livros-ef5-association-68","title":"Aksum: conexões e mudança religiosa","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia as páginas 96 e 102 e ligue cada nome à conexão histórica apresentada no texto.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Porto de Adulis"},"right":{"label":"Conexões de Aksum com o mar Vermelho e redes que ligavam regiões africanas a outros lugares."}},{"id":"p2","left":{"label":"Governante Ezana"},"right":{"label":"Adotou o cristianismo no século IV."}}]}','486584829672903c865afdbfff4aa57c32904cb569261fedfbc9f574198f903e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-01','v28:533a790c3b0c5ceba1fcd4add4b4f4b6af35356e681484e599ef2a680fa10b1d','Aksum: o que os vestígios contam','quiz','5',ARRAY[]::text[],'533a790c3b0c5ceba1fcd4add4b4f4b6af35356e681484e599ef2a680fa10b1d','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Localizar Aksum e reconhecer possibilidades e limites de seus vestígios.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · África: diversidade e história","topic":"Reinos e civilizações africanas: Aksum","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":95,"printedPage":"94"}],"itemSources":[{"itemId":"q1","pdfPages":[95]},{"itemId":"q2","pdfPages":[95]},{"itemId":"q3","pdfPages":[95]}]},"id":"livros-ef5-quiz-01","title":"Aksum: o que os vestígios contam","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia a página 94. Diferencie informações sobre Aksum de conclusões que as fontes não permitem.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Em que região africana o texto situa Aksum?","options":[{"label":"No sul africano.","id":"o1"},{"label":"No nordeste africano.","id":"o2"},{"label":"No oeste africano.","id":"o3"}],"correctOptionId":"o2","explanation":"Aksum é apresentado como um reino do nordeste africano."},{"id":"q2","prompt":"Quais vestígios são citados como fontes para investigar Aksum?","options":[{"label":"Fotografias de todos os habitantes.","id":"o1"},{"label":"Entrevistas atuais com os antigos reis.","id":"o2"},{"label":"Monumentos, inscrições e moedas.","id":"o3"}],"correctOptionId":"o3","explanation":"Esses vestígios ajudam a formular perguntas sobre a sociedade."},{"id":"q3","prompt":"O que podemos concluir a partir do estudo de Aksum?","options":[{"label":"É um caso que ajuda a conhecer a diversidade das histórias africanas.","id":"o1"},{"label":"Todos os reinos africanos tiveram a mesma história.","id":"o2"},{"label":"A vida de todos os habitantes era igual à do rei.","id":"o3"}],"correctOptionId":"o1","explanation":"O livro alerta que Aksum não representa todos os reinos africanos."}]}','533a790c3b0c5ceba1fcd4add4b4f4b6af35356e681484e599ef2a680fa10b1d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-20','v28:50db1811c31358fb4c4bbb502879990a761edb268ddd0f1f83fe4351362190ba','Kente: técnica e criação','quiz','5',ARRAY[]::text[],'50db1811c31358fb4c4bbb502879990a761edb268ddd0f1f83fe4351362190ba','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Interpretar técnica, transmissão e sentidos da tecelagem kente em Gana","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · África: diversidade e história","topic":"Interpretar técnica, transmissão e sentidos da tecelagem kente em Gana","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":99,"printedPage":"98"}],"itemSources":[{"itemId":"q1","pdfPages":[99]},{"itemId":"q2","pdfPages":[99]},{"itemId":"q3","pdfPages":[99]}]},"id":"livros-ef5-quiz-20","title":"Kente: técnica e criação","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Consulte a página 98. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Como o kente é produzido no exemplo de Gana?","options":[{"label":"Com figuras modeladas em barro.","id":"q1-o1"},{"label":"Com gravação em placas de bronze.","id":"q1-o2"},{"label":"Com faixas tecidas em teares.","id":"q1-o3"}],"correctOptionId":"q1-o3","explanation":"O procedimento indicado é tecelagem em faixas, uma técnica específica de produção do tecido."},{"id":"q2","prompt":"Que relação os tecidos podem ter com histórias e situações?","options":[{"label":"Apagam os nomes ligados a seus usos.","id":"q2-o1"},{"label":"Podem comunicar sentidos associados a elas.","id":"q2-o2"},{"label":"Servem somente para registrar números de páginas.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O texto relaciona tecidos a nomes, situações e histórias, portanto seus sentidos vão além da aparência."},{"id":"q3","prompt":"O que o registro da UNESCO destaca além da produção?","options":[{"label":"Transmissão e inovação.","id":"q3-o1"},{"label":"Abandono e esquecimento.","id":"q3-o2"},{"label":"Importação e tradução.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"A prática inclui ensinar conhecimentos e inovar; não é descrita como simples repetição de padrões."}]}','50db1811c31358fb4c4bbb502879990a761edb268ddd0f1f83fe4351362190ba',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-21','v28:1e8d2ee78fcd18441b693d27a13e48a02b6f8d445ab6e01309638f8d89c52861','Dakar: universidade e pesquisa','quiz','5',ARRAY[]::text[],'1e8d2ee78fcd18441b693d27a13e48a02b6f8d445ab6e01309638f8d89c52861','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Compare a ideia de cada alternativa com as atividades da universidade descritas no texto. Verifique qual ideia entra em conflito com o caso apresentado."}]},"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Investigar a produção contemporânea de conhecimento na Universidade Cheikh Anta Diop","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · África: diversidade e história","topic":"Investigar a produção contemporânea de conhecimento na Universidade Cheikh Anta Diop","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":107,"printedPage":"106"}],"itemSources":[{"itemId":"q1","pdfPages":[107]},{"itemId":"q2","pdfPages":[107]},{"itemId":"q3","pdfPages":[107]}]},"id":"livros-ef5-quiz-21","title":"Dakar: universidade e pesquisa","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Consulte a página 106. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que atividades caracterizam a Universidade Cheikh Anta Diop no texto?","options":[{"label":"Somente comércio de tecidos.","id":"q1-o1"},{"label":"Ensino e pesquisa em diferentes áreas.","id":"q1-o2"},{"label":"Somente conservação de ruínas antigas.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O exemplo é de uma instituição que forma pessoas e pesquisa no presente."},{"id":"q2","prompt":"Que conjunto de áreas aparece entre os cursos do portal?","options":[{"label":"Saúde, ciências e letras.","id":"q2-o1"},{"label":"Somente navegação e pesca.","id":"q2-o2"},{"label":"Somente construção de monumentos.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A variedade de cursos sustenta a afirmação de que a universidade trabalha em diferentes campos."},{"id":"q3","prompt":"Que ideia esse caso ajuda a questionar?","options":[{"label":"A de que instituições africanas realizam pesquisas.","id":"q3-o1"},{"label":"A de que o continente tem produções contemporâneas.","id":"q3-o2"},{"label":"A de que a África apenas recebe conhecimentos feitos em outros lugares.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O ensino e a pesquisa em Dakar evidenciam produção de conhecimento no próprio continente."}]}','1e8d2ee78fcd18441b693d27a13e48a02b6f8d445ab6e01309638f8d89c52861',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-67','v28:ac4f763f73e1377e17fe5aafb2bc8f65c64e904139d32dedb61423908422428b','Um festival de Ano Novo','quiz','5',ARRAY[]::text[],'ac4f763f73e1377e17fe5aafb2bc8f65c64e904139d32dedb61423908422428b','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Situar o Fichee-Chambalaalla entre os Sidama e reconhecer como sua data é determinada a cada ano.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · África: diversidade e história","topic":"Situar o Fichee-Chambalaalla entre os Sidama e reconhecer como sua data é determinada a cada ano.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":93,"printedPage":"92"}],"itemSources":[{"itemId":"q1","pdfPages":[93]},{"itemId":"q2","pdfPages":[93]}]},"id":"livros-ef5-quiz-67","title":"Um festival de Ano Novo","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia a página 92 e escolha uma resposta por pergunta sobre o Fichee-Chambalaalla. O livro apresenta uma celebração de um povo específico.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual povo celebra o Fichee-Chambalaalla como festival de Ano Novo na Etiópia?","options":[{"label":"Sidama.","id":"q1-o1"},{"label":"Shona.","id":"q1-o2"},{"label":"Punu.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"Fichee-Chambalaalla é o festival de Ano Novo Sidama apresentado no livro."},{"id":"q2","prompt":"Como é determinada a data dessa celebração?","options":[{"label":"Ela é definida pelo início das aulas no calendário escolar.","id":"q2-o1"},{"label":"Ela foi fixada uma vez e se repete sem nova definição anual.","id":"q2-o2"},{"label":"Conhecedores responsáveis pela tarefa a determinam a cada ano.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"A data é determinada anualmente por conhecedores, segundo o registro citado."}]}','ac4f763f73e1377e17fe5aafb2bc8f65c64e904139d32dedb61423908422428b',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-completion-01','v28:ccd93c8c100440d2de06cac9836d176a49796a41682d80a6221b1448789f5fac','Comunidades quilombolas hoje','completion','5',ARRAY[]::text[],'ccd93c8c100440d2de06cac9836d176a49796a41682d80a6221b1448789f5fac','{"schemaVersion":1,"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer comunidades quilombolas contemporâneas e seu protagonismo coletivo.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Escravidão, resistência e igualdade","topic":"Quilombos: história, comunidade e presente","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":125,"printedPage":"124"}],"itemSources":[{"itemId":"b1","pdfPages":[125]},{"itemId":"b2","pdfPages":[125]},{"itemId":"b3","pdfPages":[125]}]},"id":"livros-ef5-completion-01","title":"Comunidades quilombolas hoje","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia a página 124. Complete as frases sobre a presença e a organização quilombolas.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"As comunidades quilombolas existem no ","after":".","answers":["presente"],"options":[{"label":"presente","id":"o1"},{"label":"esquecimento","id":"o2"},{"label":"passado apenas","id":"o3"}]},{"id":"b2","before":"A organização nacional de articulação quilombola citada no texto é a ","after":".","answers":["CONAQ"],"options":[{"label":"CONAQ","id":"o1"},{"label":"Câmara dos Deputados","id":"o2"},{"label":"Presidência da República","id":"o3"}]},{"id":"b3","before":"Reconhecer direitos quilombolas exige ouvir as ","after":" e compreender suas histórias.","answers":["comunidades"],"options":[{"label":"comunidades","id":"o1"},{"label":"aparências","id":"o2"},{"label":"suposições","id":"o3"}]}]}','ccd93c8c100440d2de06cac9836d176a49796a41682d80a6221b1448789f5fac',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef5-quiz-69','v28:4db3924fde41b65b21ffa163d68108c6d65b058badfb9d32eb9a160465db95b1','Grupo Palmares e o 20 de novembro','quiz','5',ARRAY[]::text[],'4db3924fde41b65b21ffa163d68108c6d65b058badfb9d32eb9a160465db95b1','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Compare os modos de contar a história nas alternativas. Observe quem aparece como participante das ações e confira essa leitura com o texto da página 132."}]},"catalog":{"band":"EF5","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer a homenagem do Grupo Palmares em 1971, a participação de Oliveira Silveira e a valorização das lutas negras na construção da data.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":5,"bookId":"historia-ef5","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Escravidão, resistência e igualdade","topic":"Reconhecer a homenagem do Grupo Palmares em 1971, a participação de Oliveira Silveira e a valorização das lutas negras na construção da data.","sourceUrl":"https://drive.google.com/file/d/1HgbaJvBjXp7RAq7OYBnX6zZGH53Hdj6P/view","pages":[{"pdfPage":133,"printedPage":"132"}],"itemSources":[{"itemId":"q1","pdfPages":[133]},{"itemId":"q2","pdfPages":[133]},{"itemId":"q3","pdfPages":[133]}]},"id":"livros-ef5-quiz-69","title":"Grupo Palmares e o 20 de novembro","grade":"5º ano","subject":"História","collection":{"id":"historia-ef5","title":"História Indígena e Afro-Brasileira · 5º ano"},"description":"Leia a página 132 e escolha uma resposta por pergunta sobre a construção de uma data de memória.","difficulty":"facil","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que ação o Grupo Palmares realizou em Porto Alegre, em 1971?","options":[{"label":"Uma homenagem à assinatura da Lei Áurea.","id":"q1-o1"},{"label":"Uma homenagem a Zumbi.","id":"q1-o2"},{"label":"Uma homenagem a Luiz Gama.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O ato do Grupo Palmares homenageou Zumbi em 1971."},{"id":"q2","prompt":"Quem o livro cita como participante da construção dessa homenagem?","options":[{"label":"Abdias Nascimento.","id":"q2-o1"},{"label":"Lélia Gonzalez.","id":"q2-o2"},{"label":"Oliveira Silveira.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"O texto identifica Oliveira Silveira como participante dessa construção."},{"id":"q3","prompt":"Que mudança no modo de lembrar a história os movimentos ajudaram a fortalecer com o 20 de novembro?","options":[{"label":"Valorizar sujeitos e lutas negras, além de narrativas centradas na concessão da liberdade.","id":"q3-o1"},{"label":"Concentrar a memória na assinatura da lei, deixando as resistências em segundo plano.","id":"q3-o2"},{"label":"Tratar a história da liberdade como resultado apenas de decisões dos governantes.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"A mobilização ampliou a memória pública para destacar histórias e lutas negras."}]}','4db3924fde41b65b21ffa163d68108c6d65b058badfb9d32eb9a160465db95b1',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-association-02','v28:8dd16502c29fbe19aca00b8687f16564ed80d4a8a1130e18bf1851ad11ee9962','Ficha do Museu Magüta','association','6',ARRAY[]::text[],'8dd16502c29fbe19aca00b8687f16564ed80d4a8a1130e18bf1851ad11ee9962','{"schemaVersion":1,"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Identificar localização, povo e participação na apresentação do acervo do Museu Magüta.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Identidade, cultura e formação do povo brasileiro","topic":"Identificar localização, povo e participação na apresentação do acervo do Museu Magüta.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":14,"printedPage":"13"}],"itemSources":[{"itemId":"p1","pdfPages":[14]},{"itemId":"p2","pdfPages":[14]},{"itemId":"p3","pdfPages":[14]}]},"id":"livros-ef6-association-02","title":"Ficha do Museu Magüta","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia a página 13 e relacione os campos da ficha às informações do Museu Magüta. O exemplo não representa todos os museus ou povos indígenas.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Localização do Museu Magüta"},"right":{"label":"Benjamin Constant, Amazonas."}},{"id":"p2","left":{"label":"Povo relacionado aos objetos do acervo"},"right":{"label":"Tikuna."}},{"id":"p3","left":{"label":"Organização da apresentação dos objetos"},"right":{"label":"Organizada com participação dos próprios indígenas."}}]}','8dd16502c29fbe19aca00b8687f16564ed80d4a8a1130e18bf1851ad11ee9962',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-02','v28:3e0d92ffc1d9bd0c0645f122a8211721cf017bfa756212bdee7d8846dbc00068','Cais do Valongo e deslocamento forçado','quiz','6',ARRAY[]::text[],'3e0d92ffc1d9bd0c0645f122a8211721cf017bfa756212bdee7d8846dbc00068','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Separe o que pode ser observado no vestígio e o que seria preciso saber sobre cada pessoa. Confira se as informações disponíveis dão conta das duas coisas."}]},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Situar o Cais do Valongo, reconhecer mudanças na formação do Brasil e identificar limites de um vestígio arqueológico.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Identidade, cultura e formação do povo brasileiro","topic":"Situar o Cais do Valongo, reconhecer mudanças na formação do Brasil e identificar limites de um vestígio arqueológico.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":17,"printedPage":"16"},{"pdfPage":18,"printedPage":"17"}],"itemSources":[{"itemId":"q1","pdfPages":[18]},{"itemId":"q2","pdfPages":[17]},{"itemId":"q3","pdfPages":[17]}]},"id":"livros-ef6-quiz-02","title":"Cais do Valongo e deslocamento forçado","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia as páginas 16 e 17 e escolha uma resposta para cada questão.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual registro do livro situa a construção do Cais do Valongo?","options":[{"label":"Benjamin Constant, em 2018.","id":"q1-o2"},{"label":"Vale do Ribeira, em 1988.","id":"q1-o3"},{"label":"Rio de Janeiro, em 1811.","id":"q1-o1"}],"correctOptionId":"q1-o1","explanation":"O registro de apoio da página 17 informa local e ano da construção, situando historicamente o vestígio."},{"id":"q2","prompt":"O Brasil sempre teve as mesmas fronteiras, instituições e regras?","options":[{"label":"Não; essas configurações mudaram ao longo do tempo.","id":"q2-o2"},{"label":"Sim; o território e as instituições permaneceram iguais em todas as épocas.","id":"q2-o1"},{"label":"Sim; as regras atuais já valiam antes da colonização.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O texto alerta que o país atual não existiu com a mesma organização em todas as épocas. Projetar as condições de hoje sobre todo o passado seria incorreto."},{"id":"q3","prompt":"O cais, sozinho, informa a história de cada pessoa que desembarcou ali?","options":[{"label":"Sim; cada estrutura contém todas as biografias.","id":"q3-o1"},{"label":"Não; sua interpretação precisa de pesquisas e outros registros.","id":"q3-o3"},{"label":"Sim; basta conhecer a data da construção.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"Estruturas arqueológicas ajudam a investigar o desembarque, mas não registram sozinhas todas as trajetórias individuais."}]}','3e0d92ffc1d9bd0c0645f122a8211721cf017bfa756212bdee7d8846dbc00068',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-03','v28:aa9526fe86b60168c0f5005f78b630da7e5667ddc95620d15597e298112211dd','Patrimônio vivo no Vale do Ribeira','quiz','6',ARRAY[]::text[],'aa9526fe86b60168c0f5005f78b630da7e5667ddc95620d15597e298112211dd','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q2","text":"Organize no tempo o que o texto relata sobre os conhecimentos e sobre o registro. Compare a existência de uma prática com a data de seu reconhecimento."}]},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Distinguir existência, reconhecimento e transformação do sistema agrícola quilombola.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Identidade, cultura e formação do povo brasileiro","topic":"Distinguir existência, reconhecimento e transformação do sistema agrícola quilombola.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":23,"printedPage":"22"}],"itemSources":[{"itemId":"q1","pdfPages":[23]},{"itemId":"q2","pdfPages":[23]},{"itemId":"q3","pdfPages":[23]}]},"id":"livros-ef6-quiz-03","title":"Patrimônio vivo no Vale do Ribeira","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia a página 22 e escolha uma resposta para cada questão.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"O que o Iphan reconheceu em 2018 no caso do Vale do Ribeira?","options":[{"label":"A criação de todas as comunidades naquele ano.","id":"q1-o2"},{"label":"Somente um monumento sem relação com conhecimentos.","id":"q1-o3"},{"label":"Um sistema agrícola quilombola como Patrimônio Cultural do Brasil.","id":"q1-o1"}],"correctOptionId":"q1-o1","explanation":"O caso trata de saberes agrícolas e relações comunitárias reconhecidos pelo Iphan, e não apenas de um edifício."},{"id":"q2","prompt":"O reconhecimento de 2018 criou aqueles conhecimentos?","options":[{"label":"Sim; antes do registro não havia saberes.","id":"q2-o1"},{"label":"Não; eles já faziam parte das trajetórias das comunidades.","id":"q2-o2"},{"label":"Sim; o registro substituiu todas as experiências anteriores.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O registro reconheceu saberes já vividos e transmitidos. Reconhecer oficialmente não é criar a prática."},{"id":"q3","prompt":"Preservar esse patrimônio vivo exige proibir qualquer mudança?","options":[{"label":"Não; é preciso considerar os detentores e as condições de continuidade.","id":"q3-o3"},{"label":"Sim; toda técnica deve permanecer igual para sempre.","id":"q3-o1"},{"label":"Sim; comunidades deixam de poder tomar decisões.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"Patrimônio vivo depende de pessoas que produzem e transmitem conhecimentos; preservá-lo não exige congelar suas práticas."}]}','aa9526fe86b60168c0f5005f78b630da7e5667ddc95620d15597e298112211dd',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-completion-01','v28:cf3fb2ea031ee6d0012b2082526bf81f01dcf90e0a4b6f791e3d0ed26d95ba2d','Autoria indígena e conhecimento','completion','6',ARRAY[]::text[],'cf3fb2ea031ee6d0012b2082526bf81f01dcf90e0a4b6f791e3d0ed26d95ba2d','{"schemaVersion":1,"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer autoria Ticuna e distinguir consulta de autorização para reprodução.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos indígenas: história, cultura e direitos","topic":"Saberes tradicionais: O livro das árvores","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":52,"printedPage":"51"}],"itemSources":[{"itemId":"b1","pdfPages":[52]},{"itemId":"b2","pdfPages":[52]},{"itemId":"b3","pdfPages":[52]}]},"id":"livros-ef6-completion-01","title":"Autoria indígena e conhecimento","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia a página 51. Complete as frases sobre autoria, conhecimentos tradicionais e uso responsável de uma obra.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"O livro das árvores é uma obra da Organização Geral dos Professores ","after":" Bilíngues.","answers":["Ticuna"],"options":[{"label":"Ticuna","id":"o1"},{"label":"Kuikuro","id":"o2"},{"label":"Ikpeng","id":"o3"}]},{"id":"b2","before":"Ao falar de mudanças ao longo do tempo, dizemos que um conhecimento tradicional não precisa permanecer ","after":".","answers":["imóvel"],"options":[{"label":"imóvel","id":"o1"},{"label":"registrado","id":"o2"},{"label":"presente","id":"o3"}]},{"id":"b3","before":"Antes de reproduzir conteúdos de uma obra, devemos verificar ","after":" e respeitar as informações que não podem ser divulgadas livremente.","answers":["permissões"],"options":[{"label":"permissões","id":"o1"},{"label":"curtidas","id":"o2"},{"label":"popularidade","id":"o3"}]}]}','cf3fb2ea031ee6d0012b2082526bf81f01dcf90e0a4b6f791e3d0ed26d95ba2d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-association-01','v28:233dea5ac4ac38f9222377e8201f40567bc701b1bbf0ea66cb9971ae219c12f4','Fontes, lugares e mudanças','association','6',ARRAY[]::text[],'233dea5ac4ac38f9222377e8201f40567bc701b1bbf0ea66cb9971ae219c12f4','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Separe as informações por tipo: lugar, reino e registro com data. Para os registros, anote ano e nome em colunas diferentes e confira os dois juntos nas páginas indicadas."},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Contextualizar vestígios arqueológicos e distinguir denominações patrimoniais em diferentes datas.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · África e a formação da sociedade brasileira","topic":"Meroé e registros do samba de roda","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":68,"printedPage":"67"},{"pdfPage":77,"printedPage":"76"}],"itemSources":[{"itemId":"p1","pdfPages":[68]},{"itemId":"p2","pdfPages":[68]},{"itemId":"p3","pdfPages":[77]},{"itemId":"p4","pdfPages":[77]}]},"id":"livros-ef6-association-01","title":"Fontes, lugares e mudanças","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia as páginas 67 e 76. Relacione cada referência à informação específica que o livro apresenta.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Região de Meroé"},"right":{"label":"Localizada no atual Sudão."}},{"id":"p2","left":{"label":"Reino de Kush"},"right":{"label":"Reino ao qual se relacionam os vestígios arqueológicos de Meroé."}},{"id":"p3","left":{"label":"Registro do Iphan em 2004"},"right":{"label":"Samba de Roda do Recôncavo Baiano."}},{"id":"p4","left":{"label":"Revalidação do registro em 2024"},"right":{"label":"Samba de Roda do Estado da Bahia."}}]}','233dea5ac4ac38f9222377e8201f40567bc701b1bbf0ea66cb9971ae219c12f4',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-01','v28:2045da820ab243f3eaa12807d5eec3cf3af738dbb43d15d595751b7d07dadebb','Esperança Garcia: ação e evidência','quiz','6',ARRAY[]::text[],'2045da820ab243f3eaa12807d5eec3cf3af738dbb43d15d595751b7d07dadebb','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Distinga o que a carta registra sobre a ação da autora do que seria preciso saber sobre os acontecimentos posteriores. Procure no texto a evidência disponível para cada afirmação."}]},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Interpretar a carta de Esperança Garcia como ação histórica sem inventar seus resultados.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · África e a formação da sociedade brasileira","topic":"Resistência e luta pela liberdade: carta de 1770","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":75,"printedPage":"74"}],"itemSources":[{"itemId":"q1","pdfPages":[75]},{"itemId":"q2","pdfPages":[75]},{"itemId":"q3","pdfPages":[75]}]},"id":"livros-ef6-quiz-01","title":"Esperança Garcia: ação e evidência","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia a página 74 e analise a autoria, o destinatário e os limites da carta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"A quem Esperança Garcia dirigiu sua carta em 1770?","options":[{"label":"Ao governador da capitania do Piauí.","id":"o1"},{"label":"Ao diretor do Museu Magüta.","id":"o2"},{"label":"Aos responsáveis pelo registro do samba de roda.","id":"o3"}],"correctOptionId":"o1","explanation":"O destinatário era o governador da capitania do Piauí."},{"id":"q2","prompt":"Que ação a autora realizou por meio da carta?","options":[{"label":"Registrou um inventário de monumentos.","id":"o1"},{"label":"Denunciou violências e apresentou reivindicações.","id":"o2"},{"label":"Anunciou que todas as desigualdades haviam acabado.","id":"o3"}],"correctOptionId":"o2","explanation":"A carta evidencia uma ação concreta de uma mulher negra escravizada."},{"id":"q3","prompt":"A existência da carta comprova que todos os pedidos foram atendidos?","options":[{"label":"Sim, porque escrever a uma autoridade garante atendimento.","id":"o1"},{"label":"Sim, porque autora e destinatário tinham o mesmo poder.","id":"o2"},{"label":"Não; seriam necessários outros registros sobre o resultado.","id":"o3"}],"correctOptionId":"o3","explanation":"A fonte comprova a ação, mas não garante seu resultado."}]}','2045da820ab243f3eaa12807d5eec3cf3af738dbb43d15d595751b7d07dadebb',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-20','v28:c649724113ba48a3c0a84c18900eee8f3e0aa473284035a0f44744d021a616b6','Meroé: tecnologias e vida cotidiana','quiz','6',ARRAY[]::text[],'c649724113ba48a3c0a84c18900eee8f3e0aa473284035a0f44744d021a616b6','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q2","text":"Localize no trecho a estrutura mencionada e a função que lhe é atribuída. Relacione essa função a uma necessidade, sem concluir apenas pela palavra “armazenamento”."},{"itemId":"q3","text":"Observe quais pessoas aparecem nas fontes escolhidas e quais ficariam pouco representadas. Compare o alcance dessas fontes com o alcance da história que se pretende contar."}]},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Investigar tecnologias de Meroé e representação desigual dos grupos sociais nos vestígios","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · África e a formação da sociedade brasileira","topic":"Investigar tecnologias de Meroé e representação desigual dos grupos sociais nos vestígios","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":68,"printedPage":"67"},{"pdfPage":71,"printedPage":"70"}],"itemSources":[{"itemId":"q1","pdfPages":[71]},{"itemId":"q2","pdfPages":[71]},{"itemId":"q3","pdfPages":[68]}]},"id":"livros-ef6-quiz-20","title":"Meroé: tecnologias e vida cotidiana","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Consulte as páginas 67, 70. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual atividade produtiva é citada entre as evidências arqueológicas?","options":[{"label":"Trabalho com vidro.","id":"q1-o1"},{"label":"Trabalho com ferro.","id":"q1-o2"},{"label":"Trabalho com porcelana.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O ferro é o material mencionado no recorte sobre atividades produtivas antigas."},{"id":"q2","prompt":"Na página 70, a estrutura de armazenamento citada permite investigar qual necessidade?","options":[{"label":"Guardar e manejar água.","id":"q2-o1"},{"label":"Organizar espaços funerários.","id":"q2-o2"},{"label":"Abrigar atividades de culto.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A função de armazenamento orienta a investigação para o manejo da água, sua construção e manutenção."},{"id":"q3","prompt":"Que risco existe ao estudar Meroé apenas pelas construções ligadas aos governantes?","options":[{"label":"Confundir instalações de água com oficinas de ferro.","id":"q3-o1"},{"label":"Trocar a localização de Meroé pela de Kilwa Kisiwani.","id":"q3-o2"},{"label":"Contar uma história concentrada em quem detinha poder.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"Estruturas ligadas aos governantes podem ser mais visíveis que vestígios da vida cotidiana. Estudar apenas esses monumentos favorece a história de quem concentrava poder."}]}','c649724113ba48a3c0a84c18900eee8f3e0aa473284035a0f44744d021a616b6',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-04','v28:2d6f39e214b527afc8af11534a6faa00a450eaec241b4db9ea4e9c89c8bc41c2','Acesso à mostra sobre o Magüta','quiz','6',ARRAY[]::text[],'2d6f39e214b527afc8af11534a6faa00a450eaec241b4db9ea4e9c89c8bc41c2','{"schemaVersion":1,"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Analisar a barreira digital e a consulta ao público na mostra fictícia sobre o Magüta.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Diversidade, direitos humanos e inclusão","topic":"Analisar a barreira digital e a consulta ao público na mostra fictícia sobre o Magüta.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":93,"printedPage":"92"}],"itemSources":[{"itemId":"q1","pdfPages":[93]},{"itemId":"q2","pdfPages":[93]},{"itemId":"q3","pdfPages":[93]}]},"id":"livros-ef6-quiz-04","title":"Acesso à mostra sobre o Magüta","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Analise a mostra imaginada na página 92: textos pequenos e acesso apenas por código que exige telefone e internet. A situação é fictícia.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"No caso imaginado, por que um código como único acesso cria obstáculo?","options":[{"label":"Exige telefone e internet para acessar o conteúdo.","id":"q1-o1"},{"label":"Permite acesso impresso a qualquer visitante.","id":"q1-o2"},{"label":"Torna desnecessário qualquer equipamento.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"Um acesso exclusivamente digital pode impedir a participação de quem não dispõe do equipamento ou da conexão exigidos."},{"id":"q2","prompt":"Qual alternativa responde ao problema dos textos muito pequenos?","options":[{"label":"Diminuir ainda mais todas as letras.","id":"q2-o1"},{"label":"Oferecer uma versão impressa legível e leitura mediada.","id":"q2-o2"},{"label":"Exigir que cada visitante compre um telefone.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O recurso proposto enfrenta a dificuldade de leitura. Comprar um telefone não corrige, por si só, a legibilidade dos textos."},{"id":"q3","prompt":"Como a equipe pode conhecer necessidades sem exigir informações privadas?","options":[{"label":"Exigir que visitantes divulguem diagnósticos.","id":"q3-o1"},{"label":"Decidir que a dificuldade sempre é falta de interesse.","id":"q3-o2"},{"label":"Perguntar quais recursos facilitam a participação.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O texto orienta consultar sobre recursos de acesso, sem exigir exposição de diagnósticos ou informações privadas."}]}','2d6f39e214b527afc8af11534a6faa00a450eaec241b4db9ea4e9c89c8bc41c2',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-05','v28:55e867a45a0f48afe4d5c00e5fdd7877f9e2c413ac29fef5a1ec68f6e9b49402','Limites e respeito na pesquisa','quiz','6',ARRAY[]::text[],'55e867a45a0f48afe4d5c00e5fdd7877f9e2c413ac29fef5a1ec68f6e9b49402','{"schemaVersion":1,"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Distinguir limites de informação não pública, privacidade religiosa e debate respeitoso na pesquisa cultural.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Diversidade, direitos humanos e inclusão","topic":"Distinguir limites de informação não pública, privacidade religiosa e debate respeitoso na pesquisa cultural.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":97,"printedPage":"96"}],"itemSources":[{"itemId":"q1","pdfPages":[97]},{"itemId":"q2","pdfPages":[97]},{"itemId":"q3","pdfPages":[97]}]},"id":"livros-ef6-quiz-05","title":"Limites e respeito na pesquisa","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia a página 96. Analise os limites de acesso às informações, a privacidade das crenças e o respeito no debate. A primeira questão traz uma situação de pesquisa inventada, não um relato de uma comunidade real.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Uma comunidade informa que certo registro não é público. Como tratar esse limite na pesquisa sobre patrimônio?","options":[{"label":"Respeitá-lo, sem exigir divulgação nem inventar o conteúdo que não foi disponibilizado.","id":"q1-o1"},{"label":"Apresentar uma versão imaginada como se fosse o registro da comunidade.","id":"q1-o2"},{"label":"Exigir a divulgação, pois uma pesquisa escolar precisa ter acesso a tudo.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O livro explica que nem toda informação é pública e que as condições de uso integram o contexto do registro. Uma lacuna não autoriza exigir acesso ou inventar seu conteúdo."},{"id":"q2","prompt":"Para estudar a diversidade de crenças, os estudantes precisam revelar sua própria crença?","options":[{"label":"Sim; a crença deve constar num mural público.","id":"q2-o1"},{"label":"Sim; apenas quem declara uma crença pode pesquisar.","id":"q2-o3"},{"label":"Não; o estudo não exige revelar a crença pessoal.","id":"q2-o2"}],"correctOptionId":"q2-o2","explanation":"A aprendizagem pode usar fontes sobre histórias e manifestações culturais sem expor a religião dos estudantes."},{"id":"q3","prompt":"Qual atitude distingue debate histórico de humilhação?","options":[{"label":"Negar a participação de quem pensa diferente.","id":"q3-o1"},{"label":"Comparar informações e questionar interpretações sem atacar pessoas.","id":"q3-o3"},{"label":"Diminuir a dignidade de quem tem outra crença.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"O debate pode examinar argumentos e fontes; diferenças de crença não autorizam negar a dignidade ou a participação de alguém."}]}','55e867a45a0f48afe4d5c00e5fdd7877f9e2c413ac29fef5a1ec68f6e9b49402',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-06','v28:cad668311005f9f0ce93138077102ccda53e45236e748bedffbe02f0f312d92d','Critérios de uma assembleia','quiz','6',ARRAY[]::text[],'cad668311005f9f0ce93138077102ccda53e45236e748bedffbe02f0f312d92d','{"schemaVersion":1,"pedagogicalSupport":{"afterCompletion":"O problema é o critério discriminatório usado para excluir um tema, não a contagem dos votos. Contar votos não torna justo um critério que inferioriza um grupo."},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Avaliar legitimidade dos critérios de decisão na assembleia fictícia da mostra.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Diversidade, direitos humanos e inclusão","topic":"Avaliar legitimidade dos critérios de decisão na assembleia fictícia da mostra.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":101,"printedPage":"100"},{"pdfPage":102,"printedPage":"101"}],"itemSources":[{"itemId":"q1","pdfPages":[101,102]},{"itemId":"q2","pdfPages":[101]},{"itemId":"q3","pdfPages":[101]}]},"id":"livros-ef6-quiz-06","title":"Critérios de uma assembleia","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Analise a assembleia fictícia das páginas 100 e 101. Avalie o critério usado para escolher os temas da mostra.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Uma maioria quer excluir um tema afro-brasileiro por considerá-lo inferior. A votação torna a exclusão justa?","options":[{"label":"Sim; qualquer decisão da maioria é justa.","id":"q1-o2"},{"label":"Não; a maioria não pode autorizar inferiorização de um grupo.","id":"q1-o1"},{"label":"Sim; história e dignidade dependem da quantidade de votos.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"Contar votos não torna legítimo um critério discriminatório. A decisão coletiva continua limitada pelos direitos das pessoas."},{"id":"q2","prompt":"Antes de votar os temas, o que a turma precisa fazer?","options":[{"label":"Conhecer as opções e combinar critérios de escolha.","id":"q2-o2"},{"label":"Ocultar as propostas até o fim da votação.","id":"q2-o1"},{"label":"Permitir votar apenas em opções desconhecidas.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"Conhecer as opções e os critérios permite avaliar as propostas antes da escolha."},{"id":"q3","prompt":"Se uma proposta não foi aceita, qual retorno é necessário?","options":[{"label":"Não responder a quem apresentou a proposta.","id":"q3-o1"},{"label":"Apagar a sugestão sem registrar o motivo.","id":"q3-o2"},{"label":"Explicar a decisão e os critérios utilizados.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"Sem resposta e justificativa, a consulta pode virar um gesto vazio. O retorno permite compreender como a proposta foi considerada."}]}','cad668311005f9f0ce93138077102ccda53e45236e748bedffbe02f0f312d92d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-association-03','v28:51391899db9e8c695f850b3747e0bf4265e544e611d5ebc4557cea8acbabecbf','Responsabilidades numa mostra','association','6',ARRAY[]::text[],'51391899db9e8c695f850b3747e0bf4265e544e611d5ebc4557cea8acbabecbf','{"schemaVersion":1,"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Relacionar atribuições distintas na organização da mostra, sem transferir deveres institucionais aos alunos.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Cidadania e participação social","topic":"Relacionar atribuições distintas na organização da mostra, sem transferir deveres institucionais aos alunos.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":117,"printedPage":"116"}],"itemSources":[{"itemId":"p1","pdfPages":[117]},{"itemId":"p2","pdfPages":[117]},{"itemId":"p3","pdfPages":[117]}]},"id":"livros-ef6-association-03","title":"Responsabilidades numa mostra","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Na página 116, o livro apresenta responsabilidades de estudantes, docentes e instituição. Ligue cada participante à função destacada. Essas funções não formam uma lista completa de seus deveres.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Estudantes"},"right":{"label":"Pesquisar e revisar textos."}},{"id":"p2","left":{"label":"Docentes"},"right":{"label":"Mediar a aprendizagem."}},{"id":"p3","left":{"label":"Instituição"},"right":{"label":"Cuidar das condições de acesso e segurança."}}]}','51391899db9e8c695f850b3747e0bf4265e544e611d5ebc4557cea8acbabecbf',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-07','v28:5975eb9ab507bb66f4de7854e731e254a1720e195d4285b94a24f2f96eb538e8','Constituição, patrimônio e cidadania','quiz','6',ARRAY[]::text[],'5975eb9ab507bb66f4de7854e731e254a1720e195d4285b94a24f2f96eb538e8','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Ao consultar a Constituição como fonte, observe que tipo de texto está lendo. Compare o que ele estabelece com o que seria um registro de acontecimentos concretos."}]},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Identificar o alcance normativo da Constituição, direitos culturais e participação cidadã além do voto.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Cidadania e participação social","topic":"Identificar o alcance normativo da Constituição, direitos culturais e participação cidadã além do voto.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":111,"printedPage":"110"}],"itemSources":[{"itemId":"q1","pdfPages":[111]},{"itemId":"q2","pdfPages":[111]},{"itemId":"q3","pdfPages":[111]}]},"id":"livros-ef6-quiz-07","title":"Constituição, patrimônio e cidadania","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia a página 110 e escolha uma resposta para cada questão.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que tipo de informação a Constituição de 1988 oferece como fonte?","options":[{"label":"Uma fotografia de cada situação vivida no país.","id":"q1-o2"},{"label":"Princípios, direitos e responsabilidades estabelecidos no texto normativo.","id":"q1-o1"},{"label":"O resultado de todas as decisões escolares.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"Como fonte normativa, a Constituição registra o que está estabelecido em seu texto, não cada situação concreta do país."},{"id":"q2","prompt":"Que tipos de patrimônio cultural são reconhecidos no texto apresentado?","options":[{"label":"Somente edifícios e pedras.","id":"q2-o1"},{"label":"Apenas objetos que não são mais usados.","id":"q2-o3"},{"label":"Material e imaterial.","id":"q2-o2"}],"correctOptionId":"q2-o2","explanation":"O texto inclui conhecimentos e modos de fazer na discussão cultural, mostrando que patrimônio não se limita a edifícios."},{"id":"q3","prompt":"Uma pessoa que não ocupa cargo público e ainda não pode votar participa da cidadania?","options":[{"label":"Sim; pode conhecer direitos e participar da vida coletiva.","id":"q3-o3"},{"label":"Não; cidadania pertence somente a quem ocupa cargos públicos.","id":"q3-o1"},{"label":"Não; só é possível exercer cidadania depois de votar.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"O livro inclui apresentar propostas, ouvir argumentos e cobrar critérios claros na formação cidadã escolar. Essas ações não dependem de ocupar cargo ou votar."}]}','5975eb9ab507bb66f4de7854e731e254a1720e195d4285b94a24f2f96eb538e8',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-quiz-08','v28:61236d273491a41bfb5edf606148ee6e76003c24df5adee3327cf095aac53cbc','Representar exige prestar contas','quiz','6',ARRAY[]::text[],'61236d273491a41bfb5edf606148ee6e76003c24df5adee3327cf095aac53cbc','{"schemaVersion":1,"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Examinar consulta, prestação de contas e rodízio na representação estudantil.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Cidadania e participação social","topic":"Examinar consulta, prestação de contas e rodízio na representação estudantil.","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":121,"printedPage":"120"},{"pdfPage":122,"printedPage":"121"}],"itemSources":[{"itemId":"q1","pdfPages":[121,122]},{"itemId":"q2","pdfPages":[121]},{"itemId":"q3","pdfPages":[121]}]},"id":"livros-ef6-quiz-08","title":"Representar exige prestar contas","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia as páginas 120 e 121 e analise o caso fictício dos representantes que decidiram os temas sem consultar a turma.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Representantes eleitos escolhem todos os temas sem consultar a turma. Qual alternativa aponta o problema dessa decisão?","options":[{"label":"Ser eleito elimina qualquer responsabilidade perante o grupo.","id":"q1-o2"},{"label":"A eleição proíbe ouvir os demais estudantes.","id":"q1-o3"},{"label":"Ser eleito não autoriza decidir tudo sem consulta.","id":"q1-o1"}],"correctOptionId":"q1-o1","explanation":"A representação mantém responsabilidades perante os participantes; a escolha para a função não substitui a consulta ao grupo."},{"id":"q2","prompt":"Que critérios a comissão pode usar para organizar a ordem dos trabalhos?","options":[{"label":"O tempo disponível e os recursos.","id":"q2-o2"},{"label":"A suposta inferioridade de uma origem cultural.","id":"q2-o1"},{"label":"A popularidade pessoal de quem apresenta.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"Tempo e recursos permitem avaliar a viabilidade da programação. Inferiorizar uma origem cultural não é um critério legítimo."},{"id":"q3","prompt":"Que medida pode ampliar a experiência de participação nas funções da escola?","options":[{"label":"Manter todas as funções sempre com a mesma pessoa.","id":"q3-o1"},{"label":"Rodízio e clareza de tarefas.","id":"q3-o3"},{"label":"Deixar as tarefas sem definição.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"O rodízio permite que mais estudantes experimentem funções, e a clareza de tarefas ajuda a compreender suas responsabilidades."}]}','61236d273491a41bfb5edf606148ee6e76003c24df5adee3327cf095aac53cbc',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef6-sequence-01','v28:31c7096718a3d800222486875809bcfdc4f3dec40c57b919b1706ebfb4cff573','Uma mostra com autoria','sequence','6',ARRAY[]::text[],'31c7096718a3d800222486875809bcfdc4f3dec40c57b919b1706ebfb4cff573','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Encontre cada etapa no roteiro da página 148. Use a sequência apresentada ali para conferir sua organização, sem ordenar apenas pelo que você costuma fazer em outros trabalhos."},"catalog":{"band":"EF6","area":"historia","batch":"livros-historia-v18","objective":"Organizar o roteiro editorial de uma mostra escolar com revisão histórica, linguagem e acesso.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":6,"bookId":"historia-ef6","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 6 · Juventude, projeto de vida e transformação social","topic":"Projeto integrador: Histórias com autoria","sourceUrl":"https://drive.google.com/file/d/1OAVtQm5leb0SWK862xUmKimjw4Z261AZ/view","pages":[{"pdfPage":149,"printedPage":"148"}],"itemSources":[{"itemId":"s1","pdfPages":[149]},{"itemId":"s2","pdfPages":[149]},{"itemId":"s3","pdfPages":[149]},{"itemId":"s4","pdfPages":[149]},{"itemId":"s5","pdfPages":[149]}]},"id":"livros-ef6-sequence-01","title":"Uma mostra com autoria","grade":"6º ano","subject":"História","collection":{"id":"historia-ef6","title":"História Indígena e Afro-Brasileira · 6º ano"},"description":"Leia a página 148. As fontes já foram selecionadas. Ordene as cinco etapas seguintes conforme o roteiro do livro. Esse roteiro não é a única forma possível de fazer uma pesquisa.","difficulty":"medio","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Redação.","id":"s1"},{"label":"Revisão histórica.","id":"s2"},{"label":"Revisão de linguagem e acesso.","id":"s3"},{"label":"Apresentação interna.","id":"s4"},{"label":"Avaliação.","id":"s5"}]}','31c7096718a3d800222486875809bcfdc4f3dec40c57b919b1706ebfb4cff573',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-association-01','v28:a6988c41833aebe4bf2b29d163d7681051d3f8e14bc429508cb045359efbe7bb','Casos africanos e suas fontes','association','7',ARRAY[]::text[],'a6988c41833aebe4bf2b29d163d7681051d3f8e14bc429508cb045359efbe7bb','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Relacionar casos africanos a informações de lugar, tempo e tipo de evidência.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · África: civilizações e conhecimentos","topic":"África: geografia, evolução humana e vestígios históricos","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":15,"printedPage":"14"},{"pdfPage":19,"printedPage":"18"},{"pdfPage":21,"printedPage":"20"},{"pdfPage":23,"printedPage":"22"}],"itemSources":[{"itemId":"p1","pdfPages":[21]},{"itemId":"p2","pdfPages":[23]},{"itemId":"p3","pdfPages":[15]},{"itemId":"p4","pdfPages":[19]}]},"id":"livros-ef7-association-01","title":"Casos africanos e suas fontes","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Relacione cada caso ao que o livro informa. Consulte as páginas 14, 18, 20 e 22; um caso não representa toda a África.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Egito antigo"},"right":{"label":"Sociedade situada no nordeste africano, ligada ao vale do Nilo."}},{"id":"p2","left":{"label":"Cabeça de bronze de Augusto encontrada em Meroé"},"right":{"label":"Vestígio usado para investigar relações de poder entre Kush e Roma."}},{"id":"p3","left":{"label":"Sahel"},"right":{"label":"Faixa de transição ambiental ao sul do Saara."}},{"id":"p4","left":{"label":"Homo sapiens"},"right":{"label":"Espécie cuja evolução é situada na África há cerca de 300 mil anos."}}]}','a6988c41833aebe4bf2b29d163d7681051d3f8e14bc429508cb045359efbe7bb',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-association-60','v28:e0b686fb3aaf170633863f879e3c7f2015dc5dd589380ed2a30ad05a0e1b2a8c','Caminhos, poder e livros','association','7',ARRAY[]::text[],'e0b686fb3aaf170633863f879e3c7f2015dc5dd589380ed2a30ad05a0e1b2a8c','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Relacionar caminhos e circulação de conhecimentos às redes da África ocidental.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · África: civilizações e conhecimentos","topic":"Relacionar caminhos e circulação de conhecimentos às redes da África ocidental.","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":25,"printedPage":"24"},{"pdfPage":29,"printedPage":"28"},{"pdfPage":31,"printedPage":"30"}],"itemSources":[{"itemId":"p1","pdfPages":[25]},{"itemId":"p2","pdfPages":[29]},{"itemId":"p3","pdfPages":[31]},{"itemId":"p4","pdfPages":[31]}]},"id":"livros-ef7-association-60","title":"Caminhos, poder e livros","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Consulte as páginas 24, 28 e 30. Relacione cada tema à informação apresentada pelo livro. As conexões estudadas não representam uma única rota nem relações iguais para todas as pessoas.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Autoridades no antigo Gana"},"right":{"label":"Podiam se fortalecer pelo controle de caminhos e pelas relações com comerciantes."}},{"id":"p2","left":{"label":"Ampliação do poder de Songhai"},"right":{"label":"Relacionava-se a cidades e caminhos do rio Níger."}},{"id":"p3","left":{"label":"Localização de Timbuktu"},"right":{"label":"A proximidade do Níger e de caminhos do Saara favorecia contatos."}},{"id":"p4","left":{"label":"Trabalho e circulação de livros em Timbuktu"},"right":{"label":"Incluíam produzir, copiar, vender e guardar livros e buscar textos em outras regiões."}}]}','e0b686fb3aaf170633863f879e3c7f2015dc5dd589380ed2a30ad05a0e1b2a8c',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-01','v28:41cca7b19f247a7e4c4a012f5cb851d2eb354fbbc05164c02441cf52c024cde8','Histórias africanas: fontes e contextos','quiz','7',ARRAY[]::text[],'41cca7b19f247a7e4c4a012f5cb851d2eb354fbbc05164c02441cf52c024cde8','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer diferenças de tempo, lugar e tipo de fonte nas histórias de sociedades africanas.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · África: civilizações e conhecimentos","topic":"Gana, Mali e Timbuktu: leitura de fontes","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":25,"printedPage":"24"},{"pdfPage":27,"printedPage":"26"},{"pdfPage":31,"printedPage":"30"}],"itemSources":[{"itemId":"q1","pdfPages":[25]},{"itemId":"q2","pdfPages":[27]},{"itemId":"q3","pdfPages":[31]}]},"id":"livros-ef7-quiz-01","title":"Histórias africanas: fontes e contextos","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Consulte as páginas 24, 26 e 30. Diferencie o que as fontes sustentam de conclusões apressadas.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Ao estudar o antigo Reino de Gana, que cuidado o livro recomenda?","options":[{"label":"Considerar que o reino tinha os mesmos limites do país atual.","id":"o1"},{"label":"Distinguir o reino antigo do país contemporâneo de mesmo nome.","id":"o2"},{"label":"Usar apenas um mapa atual, sem verificar a época representada.","id":"o3"}],"correctOptionId":"o2","explanation":"Nomes semelhantes não garantem territórios idênticos. O texto distingue o antigo Gana do país atual."},{"id":"q2","prompt":"Como estudar as narrativas orais relacionadas a Sunjata e à formação do Mali?","options":[{"label":"Descartá-las porque não são textos escritos.","id":"o1"},{"label":"Tratá-las como fotografias imutáveis dos acontecimentos.","id":"o2"},{"label":"Investigar quem conta, em que contexto e comparar com outros registros.","id":"o3"}],"correctOptionId":"o3","explanation":"Tradições orais são fontes. É preciso analisar sua transmissão e seu contexto, sem supor que sejam registros imutáveis."},{"id":"q3","prompt":"A existência de bibliotecas em Timbuktu comprova que todos tinham as mesmas oportunidades de estudar?","options":[{"label":"Não. É preciso investigar quem tinha acesso aos textos.","id":"o1"},{"label":"Sim. A presença de livros comprova acesso igual.","id":"o2"},{"label":"Sim. Uma informação sobre a cidade vale para cada habitante.","id":"o3"}],"correctOptionId":"o1","explanation":"O livro distingue a existência de bibliotecas das condições de acesso de seus habitantes."}]}','41cca7b19f247a7e4c4a012f5cb851d2eb354fbbc05164c02441cf52c024cde8',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-20','v28:b3ee9b455ea6a7a548c80f3c36a9ee9e390ac3b386c66de80feed170625760f3','Njinga: governo e negociação','quiz','7',ARRAY[]::text[],'b3ee9b455ea6a7a548c80f3c36a9ee9e390ac3b386c66de80feed170625760f3','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Situar ações políticas de Njinga Mbandi no século XVII","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · África: civilizações e conhecimentos","topic":"Situar ações políticas de Njinga Mbandi no século XVII","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":41,"printedPage":"40"}],"itemSources":[{"itemId":"q1","pdfPages":[41]},{"itemId":"q2","pdfPages":[41]},{"itemId":"q3","pdfPages":[41]}]},"id":"livros-ef7-quiz-20","title":"Njinga: governo e negociação","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Consulte a página 40. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quais reinos foram governados por Njinga Mbandi?","options":[{"label":"Ndongo e Matamba.","id":"q1-o1"},{"label":"Gana e Songhai.","id":"q1-o2"},{"label":"Kush e Aksum.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O texto identifica dois reinos relacionados à sua atuação na região do atual território angolano."},{"id":"q2","prompt":"Que contexto marcou sua atuação no século XVII?","options":[{"label":"Industrialização de Dakar e criação da União Africana.","id":"q2-o1"},{"label":"Abolição de 1888 e fundação de universidades brasileiras.","id":"q2-o2"},{"label":"Expansão portuguesa e tráfico de pessoas escravizadas.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"As ações são situadas no avanço português e no tráfico, conflitos do período estudado."},{"id":"q3","prompt":"Que combinação de ações políticas o texto atribui à governante?","options":[{"label":"Catequese e administração missionária.","id":"q3-o1"},{"label":"Enfrentamentos e negociação.","id":"q3-o2"},{"label":"Produção de manuscritos e ensino religioso.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"A combinação indica que sua atuação envolveu conflitos e relações diplomáticas, não uma única forma de agir."}]}','b3ee9b455ea6a7a548c80f3c36a9ee9e390ac3b386c66de80feed170625760f3',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-22','v28:6874bd1d099d71b6a8b6c5a3f79895c7fa3d6ecc28cc3f16df86fbdbd01c377e','Uma ficha Punu no museu','quiz','7',ARRAY[]::text[],'6874bd1d099d71b6a8b6c5a3f79895c7fa3d6ecc28cc3f16df86fbdbd01c377e','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Interpretar material, época e vínculo social de uma máscara documentada","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · África: civilizações e conhecimentos","topic":"Interpretar material, época e vínculo social de uma máscara documentada","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":37,"printedPage":"36"}],"itemSources":[{"itemId":"q1","pdfPages":[37]},{"itemId":"q2","pdfPages":[37]},{"itemId":"q3","pdfPages":[37]}]},"id":"livros-ef7-quiz-22","title":"Uma ficha Punu no museu","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Consulte a página 36. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que materiais a ficha da máscara Mukudj registra?","options":[{"label":"Barro e tecido.","id":"q1-o1"},{"label":"Madeira e pigmento.","id":"q1-o2"},{"label":"Ferro e vidro.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"A ficha identifica madeira e pigmento como materiais da peça, sem exigir sua reprodução."},{"id":"q2","prompt":"Que vínculo social o título “Mask for the Okuyi Society” (“Máscara para a sociedade Okuyi”) identifica?","options":[{"label":"Uma relação com a sociedade Okuyi.","id":"q2-o1"},{"label":"Uma relação com a Universidade Cheikh Anta Diop.","id":"q2-o2"},{"label":"Uma relação com a Assembleia Constituinte.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"O título situa um vínculo social específico da máscara em vez de atribuir um significado universal às formas."},{"id":"q3","prompt":"Qual recorte de produção aparece na ficha?","options":[{"label":"Produção Shona, do início do século XII.","id":"q3-o1"},{"label":"Produção Wayana, publicada em 2010.","id":"q3-o2"},{"label":"Produção Punu, do final do século XIX.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"Povo e período constam juntos na ficha, permitindo situar a peça documentada."}]}','6874bd1d099d71b6a8b6c5a3f79895c7fa3d6ecc28cc3f16df86fbdbd01c377e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-sequence-01','v28:4ecf0f4834c71ef4c8d1dee0fbc28e31722aa1ee4b65fbdd8cd26a1d278c943a','Datas iniciais, histórias que se cruzam','sequence','7',ARRAY[]::text[],'4ecf0f4834c71ef4c8d1dee0fbc28e31722aa1ee4b65fbdd8cd26a1d278c943a','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Ordenar datas iniciais sem transformar uma cronologia em sequência de desaparecimento de povos.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · África: civilizações e conhecimentos","topic":"Recortes cronológicos aproximados de Gana, Mali e Songhai","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":29,"printedPage":"28"}],"itemSources":[{"itemId":"s1","pdfPages":[29]},{"itemId":"s2","pdfPages":[29]},{"itemId":"s3","pdfPages":[29]}]},"id":"livros-ef7-sequence-01","title":"Datas iniciais, histórias que se cruzam","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Ordene apenas as datas de início dos recortes aproximados da página 28, da mais antiga à mais recente. Os períodos se sobrepõem: a ordem não significa desaparecimento de povos nem substituição completa de um reino por outro.","difficulty":"medio","bncc":[],"status":"draft","template":"sequence","items":[{"label":"Gana: início do recorte por volta do ano 300.","id":"s1"},{"label":"Mali: início do recorte por volta de 1230.","id":"s2"},{"label":"Songhai: início do recorte por volta de 1464.","id":"s3"}]}','4ecf0f4834c71ef4c8d1dee0fbc28e31722aa1ee4b65fbdd8cd26a1d278c943a',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-completion-02','v28:283c509c680feb1faaecf42c935de223ca0939e011e76105d39e4f3ae5672d13','O percurso documentado do São José','completion','7',ARRAY[]::text[],'283c509c680feb1faaecf42c935de223ca0939e011e76105d39e4f3ae5672d13','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Localizar partida, destino planejado e naufrágio de uma viagem documentada sem confundir esses lugares.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos africanos e a formação do Brasil","topic":"O percurso documentado do São José","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":58,"printedPage":"57"}],"itemSources":[{"itemId":"b1","pdfPages":[58]},{"itemId":"b2","pdfPages":[58]},{"itemId":"b3","pdfPages":[58]}]},"id":"livros-ef7-completion-02","title":"O percurso documentado do São José","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"O São José partiu da ","after":".","answers":["Ilha de Moçambique"],"options":[{"label":"Ilha de Moçambique","id":"b1-o1"},{"label":"costa do Maranhão","id":"b1-o2"},{"label":"Cidade do Cabo","id":"b1-o3"}]},{"id":"b2","before":"O destino planejado da viagem era o ","after":".","answers":["Maranhão"],"options":[{"label":"Recife","id":"b2-o1"},{"label":"Rio de Janeiro","id":"b2-o2"},{"label":"Maranhão","id":"b2-o3"}]},{"id":"b3","before":"Em 27 de dezembro de 1794, o navio naufragou perto da ","after":".","answers":["Cidade do Cabo"],"options":[{"label":"Ilha de Moçambique","id":"b3-o1"},{"label":"Cidade do Cabo","id":"b3-o2"},{"label":"cidade de Salvador","id":"b3-o3"}]}]}','283c509c680feb1faaecf42c935de223ca0939e011e76105d39e4f3ae5672d13',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-02','v28:caa907d274966cea344400fad1a2756d05b1bdc452aea48eb9912779b5a8a4a6','Palmares: divergências em 1678','quiz','7',ARRAY[]::text[],'caa907d274966cea344400fad1a2756d05b1bdc452aea48eb9912779b5a8a4a6','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Interpretar a negociação de 1678 como evidência de posições políticas distintas em Palmares.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos africanos e a formação do Brasil","topic":"Palmares: divergências em 1678","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":66,"printedPage":"65"}],"itemSources":[{"itemId":"q1","pdfPages":[66]},{"itemId":"q2","pdfPages":[66]},{"itemId":"q3","pdfPages":[66]}]},"id":"livros-ef7-quiz-02","title":"Palmares: divergências em 1678","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quem negociou em 1678, segundo a síntese da pesquisa citada?","options":[{"label":"Gana Zumba e o governador de Pernambuco.","id":"q1-o2"},{"label":"Zumbi e o Tribunal de Justiça de São Paulo.","id":"q1-o1"},{"label":"Luiz Gama e o governador de Pernambuco.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"A síntese da pesquisa de Silvia Hunold Lara identifica esses dois participantes da negociação, em 1678."},{"id":"q2","prompt":"O que a pesquisa informa sobre os mocambos ligados a Zumbi?","options":[{"label":"Foram os únicos participantes da negociação.","id":"q2-o3"},{"label":"Todos aceitaram o acordo.","id":"q2-o2"},{"label":"Uma parte rejeitou o acordo.","id":"q2-o1"}],"correctOptionId":"q2-o1","explanation":"O texto registra a rejeição por parte dos mocambos ligados a Zumbi, mostrando que não houve uma posição única."},{"id":"q3","prompt":"Qual conclusão a informação sobre o acordo permite?","options":[{"label":"Conhecemos todos os sentimentos de cada liderança.","id":"q3-o1"},{"label":"Havia posições diferentes, mas não se podem inventar motivos individuais.","id":"q3-o3"},{"label":"Uma única decisão representava todos os mocambos.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"O registro sustenta a existência de divergências políticas, mas não informa os motivos pessoais de cada participante."}]}','caa907d274966cea344400fad1a2756d05b1bdc452aea48eb9912779b5a8a4a6',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-03','v28:443fea9caf76306b0e160de90e0ea1a7ec43f9607c3d55047b00ed3ebf88fee3','Luiz Gama e a luta na Justiça','quiz','7',ARRAY[]::text[],'443fea9caf76306b0e160de90e0ea1a7ec43f9607c3d55047b00ed3ebf88fee3','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Relacionar a atuação jurídica de Luiz Gama a conflitos coletivos e a documentos preservados.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos africanos e a formação do Brasil","topic":"Luiz Gama e a luta na Justiça","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":68,"printedPage":"67"}],"itemSources":[{"itemId":"q1","pdfPages":[68]},{"itemId":"q2","pdfPages":[68]},{"itemId":"q3","pdfPages":[68]}]},"id":"livros-ef7-quiz-03","title":"Luiz Gama e a luta na Justiça","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual frente de luta a trajetória de Luiz Gama permite investigar?","options":[{"label":"A direção das negociações de Palmares em 1678.","id":"q1-o3"},{"label":"A atuação na Justiça pela liberdade de pessoas escravizadas.","id":"q1-o2"},{"label":"A organização de viagens do tráfico atlântico.","id":"q1-o1"}],"correctOptionId":"q1-o2","explanation":"O livro apresenta Luiz Gama como abolicionista que atuou judicialmente pela liberdade, uma frente distinta de resistência."},{"id":"q2","prompt":"Qual instituição apresenta os documentos mencionados no texto?","options":[{"label":"Tribunal de Justiça de São Paulo.","id":"q2-o1"},{"label":"Fundação Cultural Palmares.","id":"q2-o2"},{"label":"Museu Paraense Emílio Goeldi.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"O texto cita documentos preservados e apresentados pelo tribunal paulista como fontes para investigar essa atuação."},{"id":"q3","prompt":"Que pergunta amplia a pesquisa para além de uma vitória judicial?","options":[{"label":"Como explicar a liberdade apenas pelo esforço de uma pessoa?","id":"q3-o2"},{"label":"Como provar que uma vitória tornou iguais todas as oportunidades?","id":"q3-o1"},{"label":"Quem conseguiu ou não recorrer à Justiça e quais barreiras enfrentou?","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"Uma vitória individual não demonstra acesso igual à Justiça; a pesquisa precisa incluir quem enfrentou obstáculos para recorrer."}]}','443fea9caf76306b0e160de90e0ea1a7ec43f9607c3d55047b00ed3ebf88fee3',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-21','v28:c428b82ca978e999a11b3ce1f3152af3293bd37203d31cad53b040f784c2c378','Úrsula: romance e crítica social','quiz','7',ARRAY[]::text[],'c428b82ca978e999a11b3ce1f3152af3293bd37203d31cad53b040f784c2c378','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Situar Úrsula na literatura de autoria negra e na crítica à escravidão","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Povos africanos e a formação do Brasil","topic":"Situar Úrsula na literatura de autoria negra e na crítica à escravidão","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":84,"printedPage":"83"}],"itemSources":[{"itemId":"q1","pdfPages":[84]},{"itemId":"q2","pdfPages":[84]},{"itemId":"q3","pdfPages":[84]}]},"id":"livros-ef7-quiz-21","title":"Úrsula: romance e crítica social","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Consulte a página 83. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"A qual forma literária pertence Úrsula?","options":[{"label":"Diário de viagens.","id":"q1-o1"},{"label":"Relato autobiográfico.","id":"q1-o2"},{"label":"Romance.","id":"q1-o3"}],"correctOptionId":"q1-o3","explanation":"O livro a apresenta como romance, uma criação literária com narradores e personagens."},{"id":"q2","prompt":"Que relação histórica o livro atribui à obra de Maria Firmina dos Reis?","options":[{"label":"Integra a literatura de autoria negra e a defesa da escravidão.","id":"q2-o1"},{"label":"Integra a literatura de autoria negra e a crítica à escravidão.","id":"q2-o2"},{"label":"Integra o registro de leis abolicionistas e de decisões judiciais.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"A importância destacada combina autoria negra e intervenção crítica nas relações escravistas."},{"id":"q3","prompt":"Qual investigação sobre a circulação de Úrsula é proposta pelo texto?","options":[{"label":"Quem teve espaço para publicar e como a obra foi lida.","id":"q3-o1"},{"label":"Qual personagem comprova toda a biografia da autora.","id":"q3-o2"},{"label":"Qual cena serve como transcrição de uma audiência judicial.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"Investigar publicação e recepção permite compreender o lugar ocupado pela obra na vida literária."}]}','c428b82ca978e999a11b3ce1f3152af3293bd37203d31cad53b040f784c2c378',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-association-02','v28:8f2eadf10fd48671853dcb8b2b16b9bbd715d42a69c922ccb04d6fe349f43d10','Uma reunião: três dimensões do acesso','association','7',ARRAY[]::text[],'8f2eadf10fd48671853dcb8b2b16b9bbd715d42a69c922ccb04d6fe349f43d10','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Releia o caso da reunião na página indicada. Para cada dimensão, procure o que já está disponível e o que ainda dificulta a participação. Use somente situações descritas no caso, sem acrescentar obstáculos."},"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Diagnosticar as barreiras efetivamente descritas na reunião fictícia, sem inventar obstáculos.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Racismo, direitos humanos e cidadania","topic":"Uma reunião: três dimensões do acesso","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":117,"printedPage":"116"}],"itemSources":[{"itemId":"p1","pdfPages":[117]},{"itemId":"p2","pdfPages":[117]},{"itemId":"p3","pdfPages":[117]}]},"id":"livros-ef7-association-02","title":"Uma reunião: três dimensões do acesso","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro. Caso fictício do livro. Relacione cada dimensão ao diagnóstico correspondente.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Chegar ao local"},"right":{"label":"O acesso físico já está oferecido; não inventar uma barreira ausente."}},{"id":"p2","left":{"label":"Entender os avisos"},"right":{"label":"Rever a comunicação pouco clara."}},{"id":"p3","left":{"label":"Acompanhar o que foi decidido"},"right":{"label":"Registrar os encaminhamentos da reunião."}}]}','8f2eadf10fd48671853dcb8b2b16b9bbd715d42a69c922ccb04d6fe349f43d10',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-04','v28:a69a09b49275ab226606addb37b280b87c69557a4cf60be6d8ec3a85c490a318','Liberdade religiosa e estudo escolar','quiz','7',ARRAY[]::text[],'a69a09b49275ab226606addb37b280b87c69557a4cf60be6d8ec3a85c490a318','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Relacionar a liberdade de pensamento, consciência e religião ao respeito a diferentes escolhas e à análise histórica da intolerância.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Racismo, direitos humanos e cidadania","topic":"Liberdade religiosa e estudo escolar","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":107,"printedPage":"106"}],"itemSources":[{"itemId":"q1","pdfPages":[107]},{"itemId":"q2","pdfPages":[107]},{"itemId":"q3","pdfPages":[107]}]},"id":"livros-ef7-quiz-04","title":"Liberdade religiosa e estudo escolar","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia a página 106 e relacione o artigo 18 da Declaração Universal dos Direitos Humanos (DUDH) à liberdade de crença e à análise da intolerância religiosa.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Quais liberdades são destacadas no artigo 18 apresentado pelo livro?","options":[{"label":"Somente a religião escolhida pela maioria.","id":"q1-o1"},{"label":"Somente participação em cerimônias públicas.","id":"q1-o3"},{"label":"Pensamento, consciência e religião.","id":"q1-o2"}],"correctOptionId":"q1-o2","explanation":"O marco apresentado resume o artigo 18, que protege essas liberdades sem restringi-las à crença da maioria."},{"id":"q2","prompt":"Quem também está protegido pela liberdade religiosa descrita?","options":[{"label":"Quem muda de crença ou não tem religião.","id":"q2-o1"},{"label":"Apenas quem participa de uma religião majoritária.","id":"q2-o3"},{"label":"Apenas quem conserva a mesma religião toda a vida.","id":"q2-o2"}],"correctOptionId":"q2-o1","explanation":"A proteção inclui professar uma religião, mudar de crença ou não seguir religião; não depende da concordância alheia."},{"id":"q3","prompt":"Quando atinge tradições afro-brasileiras, a intolerância religiosa pode se relacionar a quê?","options":[{"label":"Somente a divergências recentes, sem relações com a história.","id":"q3-o2"},{"label":"Ao racismo e a uma história de desvalorização.","id":"q3-o1"},{"label":"À ausência de história própria dessas tradições.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"O livro situa ataques a tradições afro-brasileiras em relações históricas de desvalorização, sem reduzir a análise a diferenças de opinião religiosa."}]}','a69a09b49275ab226606addb37b280b87c69557a4cf60be6d8ec3a85c490a318',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-05','v28:8431f31b4ea94827a056ef8b47d4cb1d537a7297c76f6b4015c0e3009105e907','Um arquivo igual, acessos diferentes','quiz','7',ARRAY[]::text[],'8431f31b4ea94827a056ef8b47d4cb1d537a7297c76f6b4015c0e3009105e907','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Analisar a equidade no caso fictício do arquivo escolar inacessível.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Racismo, direitos humanos e cidadania","topic":"Um arquivo igual, acessos diferentes","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":113,"printedPage":"112"}],"itemSources":[{"itemId":"q1","pdfPages":[113]},{"itemId":"q2","pdfPages":[113]},{"itemId":"q3","pdfPages":[113]}]},"id":"livros-ef7-quiz-05","title":"Um arquivo igual, acessos diferentes","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro. Caso fictício apresentado no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"No caso fictício, por que enviar o mesmo arquivo a toda a turma não garante que todos consigam lê-lo?","options":[{"label":"Parte da turma precisa de formato acessível para lê-lo.","id":"q1-o2"},{"label":"Todos os estudantes precisam de conteúdos diferentes.","id":"q1-o3"},{"label":"O objetivo comum deve ser abandonado.","id":"q1-o1"}],"correctOptionId":"q1-o2","explanation":"O caso mostra uma barreira de formato: receber o arquivo não significa conseguir lê-lo."},{"id":"q2","prompt":"Antes de escolher a adaptação, qual medida corresponde ao livro?","options":[{"label":"Escolher sem consultar a pessoa para decidir por ela.","id":"q2-o2"},{"label":"Identificar a barreira e ouvir quem será afetado.","id":"q2-o1"},{"label":"Presumir incapacidade a partir da necessidade de formato.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A medida precisa responder à barreira e favorecer autonomia; decidir sem ouvir pode impor um apoio inadequado."},{"id":"q3","prompt":"Qual efeito a adaptação deve evitar?","options":[{"label":"Favorecer sua autonomia de leitura.","id":"q3-o2"},{"label":"Ampliar suas possibilidades de participação.","id":"q3-o1"},{"label":"Separar a pessoa em uma atividade de menor expectativa.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O apoio deve ampliar possibilidades na atividade comum, e não afastar a pessoa para uma proposta de menor expectativa."}]}','8431f31b4ea94827a056ef8b47d4cb1d537a7297c76f6b4015c0e3009105e907',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-completion-01','v28:5ce8add31c91203c96628db9a3a69bd68253ba1c8fc0349b2eb0a08eed9a6910','Vozes, mapas e direitos indígenas','completion','7',ARRAY[]::text[],'5ce8add31c91203c96628db9a3a69bd68253ba1c8fc0349b2eb0a08eed9a6910','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Distinguir comunicação de autoria indígena, limites cartográficos e direitos reconhecidos.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Povos indígenas: história, cultura e resistência","topic":"Comunicação indígena, mapas coloniais e direitos","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":144,"printedPage":"143"},{"pdfPage":146,"printedPage":"145"},{"pdfPage":148,"printedPage":"147"}],"itemSources":[{"itemId":"b1","pdfPages":[144]},{"itemId":"b2","pdfPages":[146]},{"itemId":"b3","pdfPages":[148]}]},"id":"livros-ef7-completion-01","title":"Vozes, mapas e direitos indígenas","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Complete com base nas páginas 143, 145 e 147. Considere autoria, limites das fontes e reconhecimento de direitos.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"No exemplo do rio Negro, a Rede ","after":" produz e faz circular conteúdos em diferentes formatos.","answers":["Wayuri"],"options":[{"label":"Wayuri","id":"o1"},{"label":"Sankoré","id":"o2"},{"label":"Palmares","id":"o3"}]},{"id":"b2","before":"Se uma comunidade não aparece em um mapa colonial, essa ausência ","after":" que ela não existia.","answers":["não prova"],"options":[{"label":"comprova","id":"o1"},{"label":"garante","id":"o2"},{"label":"não prova","id":"o3"}]},{"id":"b3","before":"A Constituição de 1988 ","after":" direitos originários sobre terras tradicionalmente ocupadas.","answers":["reconhece"],"options":[{"label":"substitui por favores","id":"o1"},{"label":"reconhece","id":"o2"},{"label":"condiciona à perda da identidade","id":"o3"}]}]}','5ce8add31c91203c96628db9a3a69bd68253ba1c8fc0349b2eb0a08eed9a6910',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-61','v28:5e906407b00754ba9d3e9cd03d2151510f2001be5aa67655804cf46ea35e4084','O retorno do manto Tupinambá','quiz','7',ARRAY[]::text[],'5e906407b00754ba9d3e9cd03d2151510f2001be5aa67655804cf46ea35e4084','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q3","text":"Faça uma coluna para cada ficha. Anote quem publicou, a data e o acontecimento descrito. Compare essas anotações com cada alternativa, verificando separadamente a primeira e a segunda parte."}]},"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer o retorno documentado do manto Tupinambá e a articulação entre iniciativa indígena e instituições.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Povos indígenas: história, cultura e resistência","topic":"Reconhecer o retorno documentado do manto Tupinambá e a articulação entre iniciativa indígena e instituições.","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":154,"printedPage":"153"},{"pdfPage":155,"printedPage":"154"},{"pdfPage":160,"printedPage":"159"}],"itemSources":[{"itemId":"q1","pdfPages":[154]},{"itemId":"q2","pdfPages":[160]},{"itemId":"q3","pdfPages":[155]}]},"id":"livros-ef7-quiz-61","title":"O retorno do manto Tupinambá","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Consulte as páginas 153, 154 e 159. Escolha uma resposta por pergunta sobre o processo de retorno documentado em 2024.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que deslocamento do manto Tupinambá o livro registra em 2024?","options":[{"label":"Do Brasil para a Dinamarca.","id":"q1-o1"},{"label":"Da Dinamarca para o Brasil.","id":"q1-o2"},{"label":"Entre instituições situadas no Brasil.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O texto registra um retorno da Dinamarca ao Brasil em 2024. A informação não estabelece quando ou como o manto havia saído do Brasil."},{"id":"q2","prompt":"Que participação das lideranças indígenas o livro identifica nesse processo?","options":[{"label":"Reivindicações e articulações com instituições.","id":"q2-o1"},{"label":"Apenas o recebimento de uma decisão já tomada.","id":"q2-o2"},{"label":"Somente cuidados técnicos com o material do manto.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A página 159 destaca reivindicações e articulações. Assim, o processo inclui ação coletiva indígena, e não apenas uma decisão de museu ou governo."},{"id":"q3","prompt":"Como a página 154 distingue os eventos registrados pelas duas fichas?","options":[{"label":"A nota MRE/MPI registra a cerimônia com lideranças; a notícia UFRJ registra o retorno e a iniciativa Tupinambá.","id":"q3-o1"},{"label":"A nota MRE/MPI registra o retorno e a iniciativa Tupinambá; a notícia UFRJ documenta as técnicas de conservação.","id":"q3-o2"},{"label":"A nota MRE/MPI registra o retorno e a iniciativa Tupinambá; a notícia UFRJ relata a cerimônia.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"A ficha A é a nota MRE/MPI de julho de 2024 sobre retorno e iniciativa Tupinambá. A ficha B é a notícia UFRJ de setembro sobre a cerimônia com lideranças e instituições."}]}','5e906407b00754ba9d3e9cd03d2151510f2001be5aa67655804cf46ea35e4084',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-association-03','v28:d11243f682073f9c2f92d6ce1a96bca7d81a1e3f4d2dfb54a166785b2c25e958','Biblioteca: promessa, ação e conclusão','association','7',ARRAY[]::text[],'d11243f682073f9c2f92d6ce1a96bca7d81a1e3f4d2dfb54a166785b2c25e958','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Distinguir o alcance dos três registros fictícios sobre uma biblioteca.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Juventudes, tecnologia e transformação social","topic":"Biblioteca: promessa, ação e conclusão","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":179,"printedPage":"178"}],"itemSources":[{"itemId":"p1","pdfPages":[179]},{"itemId":"p2","pdfPages":[179]},{"itemId":"p3","pdfPages":[179]}]},"id":"livros-ef7-association-03","title":"Biblioteca: promessa, ação e conclusão","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro. Os três registros são fictícios, conforme o livro.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Registro A: anúncio de novos livros"},"right":{"label":"Informa uma promessa."}},{"id":"p2","left":{"label":"Registro B: relatório datado de vinte exemplares entregues"},"right":{"label":"Registra uma ação delimitada."}},{"id":"p3","left":{"label":"Registro C: todos os problemas da biblioteca terminaram"},"right":{"label":"Conclui mais do que as evidências demonstram."}}]}','d11243f682073f9c2f92d6ce1a96bca7d81a1e3f4d2dfb54a166785b2c25e958',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-06','v28:2158655dd4d711cc95daf7fc125073917ec448ecbe9b40586b7a05262af9f788','IA não é testemunha do passado','quiz','7',ARRAY[]::text[],'2158655dd4d711cc95daf7fc125073917ec448ecbe9b40586b7a05262af9f788','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Avaliar o valor documental e as responsabilidades no uso escolar de inteligência artificial.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Juventudes, tecnologia e transformação social","topic":"IA não é testemunha do passado","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":181,"printedPage":"180"}],"itemSources":[{"itemId":"q1","pdfPages":[181]},{"itemId":"q2","pdfPages":[181]},{"itemId":"q3","pdfPages":[181]}]},"id":"livros-ef7-quiz-06","title":"IA não é testemunha do passado","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Uma resposta de IA cita um livro de modo convincente. O que fazer?","options":[{"label":"Usar a referência como prova sem consultar outra fonte.","id":"q1-o1"},{"label":"Conferir a existência da referência e suas afirmações em fontes adequadas.","id":"q1-o2"},{"label":"Aceitar a referência porque a frase é fluente.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"A fluência não garante exatidão: sistemas generativos podem produzir referências inexistentes."},{"id":"q2","prompt":"Uma imagem de um acontecimento histórico foi gerada por IA. Como identificá-la?","options":[{"label":"Como prova de todos os detalhes representados.","id":"q2-o3"},{"label":"Como fotografia original da época.","id":"q2-o2"},{"label":"Como criação gerada, não como fotografia documental.","id":"q2-o1"}],"correctOptionId":"q2-o1","explanation":"A imagem resulta de geração de conteúdo e não de registro do acontecimento; por isso não prova os detalhes da cena."},{"id":"q3","prompt":"Qual apresentação do trabalho preserva a informação sobre autoria?","options":[{"label":"Informar a assistência recebida conforme as regras da escola.","id":"q3-o3"},{"label":"Ocultar toda ajuda e declarar produção sem assistência.","id":"q3-o1"},{"label":"Substituir a conferência das fontes pelo nome da ferramenta.","id":"q3-o2"}],"correctOptionId":"q3-o3","explanation":"O texto exige preservar autoria e não apresentar uma produção assistida como se tivesse sido feita integralmente sem ajuda."}]}','2158655dd4d711cc95daf7fc125073917ec448ecbe9b40586b7a05262af9f788',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef7-quiz-07','v28:39f6ece9f7d9969212272955ba708bffa860f4cab0c0f448ab7220110840676e','Privacidade em um projeto escolar','quiz','7',ARRAY[]::text[],'39f6ece9f7d9969212272955ba708bffa860f4cab0c0f448ab7220110840676e','{"schemaVersion":1,"catalog":{"band":"EF7","area":"historia","batch":"livros-historia-v18","objective":"Distinguir finalidade, autorização e responsabilidade na proteção de dados escolares.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":7,"bookId":"historia-ef7","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Juventudes, tecnologia e transformação social","topic":"Privacidade em um projeto escolar","sourceUrl":"https://drive.google.com/file/d/1GTtdABSSoBbGE86SkSk--8_kFx7mILfN/view","pages":[{"pdfPage":175,"printedPage":"174"}],"itemSources":[{"itemId":"q1","pdfPages":[175]},{"itemId":"q2","pdfPages":[175]},{"itemId":"q3","pdfPages":[175]}]},"id":"livros-ef7-quiz-07","title":"Privacidade em um projeto escolar","grade":"7º ano","subject":"História","collection":{"id":"historia-ef7","title":"História Indígena e Afro-Brasileira · 7º ano"},"description":"Leia as páginas indicadas e responda com base no livro. A situação do primeiro item é fictícia.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Situação fictícia: um projeto pede endereço e rotina sem precisar deles para aprender. Qual revisão é adequada?","options":[{"label":"Coletar todos os dados disponíveis para decidir depois.","id":"q1-o3"},{"label":"Exigir publicação da rotina para comprovar participação.","id":"q1-o1"},{"label":"Retirar dados desnecessários ao objetivo de aprendizagem.","id":"q1-o2"}],"correctOptionId":"q1-o2","explanation":"A finalidade pedagógica delimita os dados necessários; endereço e rotina não devem ser coletados sem necessidade para a atividade."},{"id":"q2","prompt":"Uma imagem foi autorizada para uma finalidade. Isso permite qualquer uso posterior?","options":[{"label":"Sim; uma autorização vale para toda divulgação futura.","id":"q2-o2"},{"label":"Não; a autorização não é ilimitada.","id":"q2-o1"},{"label":"Sim; desde que o novo uso tenha muitos espectadores.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"Permissão para uma finalidade não é autorização irrestrita para usos posteriores."},{"id":"q3","prompt":"De quem é a responsabilidade de proteger dados, segundo o texto?","options":[{"label":"Também das escolas, responsáveis e serviços digitais.","id":"q3-o3"},{"label":"Somente de quem possui mais seguidores.","id":"q3-o2"},{"label":"Somente do estudante que aparece na imagem.","id":"q3-o1"}],"correctOptionId":"q3-o3","explanation":"A proteção não depende só de uma escolha individual: instituições e responsáveis também têm deveres."}]}','39f6ece9f7d9969212272955ba708bffa860f4cab0c0f448ab7220110840676e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-completion-01','v28:3345eb715efa4dda2abb00fe8b20e18ec5e056be648687e40766f16d5af459b2','Nomear a coerção com cuidado','completion','8',ARRAY[]::text[],'3345eb715efa4dda2abb00fe8b20e18ec5e056be648687e40766f16d5af459b2','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer o deslocamento forçado e os limites de representações cartográficas do tráfico.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Africanos no Brasil: escravização e resistência","topic":"Tráfico transatlântico: coerção, linguagem e mapas","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":19,"printedPage":"18"}],"itemSources":[{"itemId":"b1","pdfPages":[19]},{"itemId":"b2","pdfPages":[19]},{"itemId":"b3","pdfPages":[19]}]},"id":"livros-ef8-completion-01","title":"Nomear a coerção com cuidado","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Complete a síntese da página 18. O foco é compreender o caráter imposto da escravização e os limites de um mapa, sem simular experiências de violência.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"No contexto estudado, o tráfico transatlântico foi um deslocamento ","after":" de pessoas africanas.","answers":["forçado"],"options":[{"label":"voluntário","id":"o1"},{"label":"forçado","id":"o2"},{"label":"turístico","id":"o3"}]},{"id":"b2","before":"A expressão “pessoas escravizadas” destaca que a condição de cativeiro foi ","after":".","answers":["imposta"],"options":[{"label":"escolhida livremente","id":"o1"},{"label":"uma característica natural","id":"o2"},{"label":"imposta","id":"o3"}]},{"id":"b3","before":"As setas de um mapa de rotas ","after":" as experiências individuais e a perda de liberdade.","answers":["não mostram sozinhas"],"options":[{"label":"não mostram sozinhas","id":"o1"},{"label":"explicam por completo","id":"o2"},{"label":"substituem todas","id":"o3"}]}]}','3345eb715efa4dda2abb00fe8b20e18ec5e056be648687e40766f16d5af459b2',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-21','v28:e7a5d1d312365217900e14aa08bb7b28a1e9e64eb4c2a079d6ff3fa0d9face5f','Capoeira: roda e ofício','quiz','8',ARRAY[]::text[],'e7a5d1d312365217900e14aa08bb7b28a1e9e64eb4c2a079d6ff3fa0d9face5f','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Distinguir bens culturais relacionados e documentos sobre a história da capoeira","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Africanos no Brasil: escravização e resistência","topic":"Distinguir bens culturais relacionados e documentos sobre a história da capoeira","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":33,"printedPage":"32"}],"itemSources":[{"itemId":"q1","pdfPages":[33]},{"itemId":"q2","pdfPages":[33]},{"itemId":"q3","pdfPages":[33]}]},"id":"livros-ef8-quiz-21","title":"Capoeira: roda e ofício","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Consulte a página 32. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"O que o reconhecimento da Roda de Capoeira destaca?","options":[{"label":"A construção de um único edifício.","id":"q1-o1"},{"label":"A realização coletiva da prática.","id":"q1-o2"},{"label":"A autoria de um romance individual.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"A roda diz respeito ao encontro coletivo, dimensão diferente do ofício de transmitir saberes."},{"id":"q2","prompt":"O que o Ofício dos Mestres e Mestras valoriza?","options":[{"label":"Os saberes e sua transmissão.","id":"q2-o1"},{"label":"Somente o tamanho do espaço de apresentação.","id":"q2-o2"},{"label":"Somente a venda de ingressos.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"O reconhecimento do ofício dirige atenção ao conhecimento e ao ensino, não apenas ao espetáculo."},{"id":"q3","prompt":"Para investigar como autoridades reprimiam a capoeira, qual fonte o texto sugere?","options":[{"label":"Uma lista de ingredientes de acarajé.","id":"q3-o1"},{"label":"Uma ficha de cursos universitários.","id":"q3-o2"},{"label":"Um documento policial.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"O registro policial permite estudar classificações e ações de repressão das autoridades em seu contexto."}]}','e7a5d1d312365217900e14aa08bb7b28a1e9e64eb4c2a079d6ff3fa0d9face5f',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-40','v28:a7d2fd7f13a32df2c66e66c598c53e2c16048416464e8ffc4880ac7a3b2feb3e','Irmandades negras e auxílio','quiz','8',ARRAY[]::text[],'a7d2fd7f13a32df2c66e66c598c53e2c16048416464e8ffc4880ac7a3b2feb3e','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Relacionar devoção, auxílio e recursos coletivos às iniciativas de irmandades religiosas negras em condições de escravidão","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Africanos no Brasil: escravização e resistência","topic":"Relacionar devoção, auxílio e recursos coletivos às iniciativas de irmandades religiosas negras em condições de escravidão","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":29,"printedPage":"28"}],"itemSources":[{"itemId":"q1","pdfPages":[29]},{"itemId":"q2","pdfPages":[29]}]},"id":"livros-ef8-quiz-40","title":"Irmandades negras e auxílio","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Consulte a página 28. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Segundo o texto, o que reunia as pessoas nas irmandades religiosas negras?","options":[{"label":"Devoções religiosas e formas de auxílio.","id":"q1-o1"},{"label":"Administração das leis aprovadas pelo governo.","id":"q1-o2"},{"label":"Organização de repartições dos antigos senhores.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"As irmandades são apresentadas como espaços de devoção e auxílio. Assim, a prática religiosa também podia reunir relações de solidariedade entre participantes."},{"id":"q2","prompt":"Que contribuição dos recursos coletivos é mencionada no texto?","options":[{"label":"Garantiam a alforria imediata de toda pessoa que ingressasse em uma irmandade.","id":"q2-o1"},{"label":"Em certas situações, ajudavam na obtenção de alforrias.","id":"q2-o2"},{"label":"Dispensavam qualquer iniciativa dos participantes para obter a liberdade.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O texto afirma que recursos coletivos ajudaram na obtenção de alforrias em certas situações. Não afirma que todas as irmandades garantiam a liberdade automática de seus integrantes."}]}','a7d2fd7f13a32df2c66e66c598c53e2c16048416464e8ffc4880ac7a3b2feb3e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-completion-62','v28:4651f6b174c8afb52945dd7bba86c5ed41ab19daa60b6559e9efd53f3a814f00','Ventre Livre: alcance e restrições','completion','8',ARRAY[]::text[],'4651f6b174c8afb52945dd7bba86c5ed41ab19daa60b6559e9efd53f3a814f00','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"b1","text":"Vigência é o período em que uma lei está em vigor. No trecho do livro, identifique a partir de quando a regra passou a valer e compare esse limite com as opções."},{"itemId":"b3","text":"Organize o trecho da lei em três perguntas: quem escolhia, quais eram as opções e até quando cada obrigação valia? Compare uma informação de cada vez nas alternativas."}]},"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Distinguir a declaração de condição livre das restrições e escolhas previstas na Lei do Ventre Livre.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Quilombos, rebeliões e processos de libertação","topic":"Distinguir a declaração de condição livre das restrições e escolhas previstas na Lei do Ventre Livre.","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":57,"printedPage":"56"},{"pdfPage":58,"printedPage":"57"}],"itemSources":[{"itemId":"b1","pdfPages":[57]},{"itemId":"b2","pdfPages":[57]},{"itemId":"b3","pdfPages":[57]},{"itemId":"b4","pdfPages":[57]}]},"id":"livros-ef8-completion-62","title":"Ventre Livre: alcance e restrições","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas 56 e 57. Complete as frases sobre a lei histórica apresentada no livro. A condição declarada livre não significava autonomia plena e imediata.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"A declaração de condição livre abrangia filhos de mulheres escravizadas nascidos ","after":".","answers":["a partir da vigência da lei"],"options":[{"label":"antes da vigência da lei","id":"b1-o1"},{"label":"a partir da vigência da lei","id":"b1-o2"},{"label":"em qualquer período, antes ou depois da lei","id":"b1-o3"}]},{"id":"b2","before":"As crianças permaneciam sob a autoridade dos senhores de suas mães até os ","after":".","answers":["oito anos"],"options":[{"label":"oito anos","id":"b2-o1"},{"label":"vinte e um anos","id":"b2-o2"},{"label":"três anos","id":"b2-o3"}]},{"id":"b3","before":"Aos oito anos da criança, cabia ao senhor escolher entre ","after":".","answers":["receber indenização estatal ou utilizar os serviços dela até os 21 anos"],"options":[{"label":"pagar indenização à criança ou utilizar os serviços dela até os 21 anos","id":"b3-o1"},{"label":"receber indenização estatal ou utilizar os serviços dela por mais três anos","id":"b3-o2"},{"label":"receber indenização estatal ou utilizar os serviços dela até os 21 anos","id":"b3-o3"}]},{"id":"b4","before":"Os recursos reunidos para buscar alforria eram chamados de ","after":".","answers":["pecúlio"],"options":[{"label":"indenização estatal","id":"b4-o1"},{"label":"pecúlio","id":"b4-o2"},{"label":"serviço compulsório","id":"b4-o3"}]}]}','4651f6b174c8afb52945dd7bba86c5ed41ab19daa60b6559e9efd53f3a814f00',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-01','v28:48ec6d586542f28790ae4d4697f8176f819401d8c695f79425e8ec08eb24146f','Resistência negra: evidências e limites','quiz','8',ARRAY[]::text[],'48ec6d586542f28790ae4d4697f8176f819401d8c695f79425e8ec08eb24146f','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Interpretar fontes sobre resistência negra, reconhecendo ação coletiva e limites documentais.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Quilombos, rebeliões e processos de libertação","topic":"Palmares, Dandara e Malês: história e memória","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":43,"printedPage":"42"},{"pdfPage":47,"printedPage":"46"},{"pdfPage":51,"printedPage":"50"}],"itemSources":[{"itemId":"q1","pdfPages":[43]},{"itemId":"q2","pdfPages":[47]},{"itemId":"q3","pdfPages":[51]}]},"id":"livros-ef8-quiz-01","title":"Resistência negra: evidências e limites","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas 42, 46 e 50. Analise Palmares, a memória de Dandara e a Revolta dos Malês sem generalizar.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Por que muitos relatos sobre Palmares precisam ser lidos criticamente?","options":[{"label":"Porque documentos escritos nunca podem ser fontes.","id":"o1"},{"label":"Porque uma rede de mocambos não pode deixar registros.","id":"o2"},{"label":"Porque muitos foram produzidos por adversários de Palmares.","id":"o3"}],"correctOptionId":"o3","explanation":"O livro informa que muitos registros vieram de adversários. Sua autoria e seus interesses precisam ser examinados."},{"id":"q2","prompt":"Qual afirmação sobre Dandara é sustentada pelo livro?","options":[{"label":"Todos os detalhes de sua biografia estão comprovados.","id":"o1"},{"label":"Sua importância na memória da resistência não dispensa cuidado com detalhes sem comprovação.","id":"o2"},{"label":"A falta de registros permite inventar episódios para completar a biografia.","id":"o3"}],"correctOptionId":"o2","explanation":"O texto reconhece Dandara como referência importante e distingue essa memória de detalhes biográficos sem comprovação segura."},{"id":"q3","prompt":"Qual cuidado evita uma generalização ao estudar a Revolta dos Malês?","options":[{"label":"Reconhecer o papel de africanos muçulmanos sem afirmar que todos os africanos eram muçulmanos.","id":"o1"},{"label":"Tratar toda a população africana como participante da revolta.","id":"o2"},{"label":"Concluir que religião e violência são a mesma coisa.","id":"o3"}],"correctOptionId":"o1","explanation":"O texto apresenta uma rebelião específica, em Salvador, em 1835, e rejeita generalizações sobre africanos e muçulmanos."}]}','48ec6d586542f28790ae4d4697f8176f819401d8c695f79425e8ec08eb24146f',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-41','v28:26f2114ca7832b4d99c155aeb50bc3e6d8848bcc5de7e141f976b4d7983d5f87','Sexagenários: condições da lei','quiz','8',ARRAY[]::text[],'26f2114ca7832b4d99c155aeb50bc3e6d8848bcc5de7e141f976b4d7983d5f87','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q2","text":"Na página indicada, localize a regra sobre a duração do serviço e a regra ligada à idade. Faça uma linha do tempo do caso e verifique como as duas condições se aplicam juntas."}]},"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Interpretar a obrigação de serviços da Lei dos Sexagenários e sua cessação aos 65 anos sem confundi-la com liberdade sem restrições","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Quilombos, rebeliões e processos de libertação","topic":"Interpretar a obrigação de serviços da Lei dos Sexagenários e sua cessação aos 65 anos sem confundi-la com liberdade sem restrições","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":59,"printedPage":"58"},{"pdfPage":60,"printedPage":"59"}],"itemSources":[{"itemId":"q1","pdfPages":[59]},{"itemId":"q2","pdfPages":[59,60]}]},"id":"livros-ef8-quiz-41","title":"Sexagenários: condições da lei","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Consulte as páginas 58, 59. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que obrigação a Lei dos Sexagenários impunha como compensação pela alforria?","options":[{"label":"Serviços aos antigos senhores por até três anos.","id":"q1-o1"},{"label":"Pagamento dos antigos senhores às pessoas libertas.","id":"q1-o2"},{"label":"Dispensa imediata de qualquer obrigação de serviços.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"A lei previa três anos de serviços aos antigos senhores. A obrigação podia terminar antes desse prazo ao completar 65 anos, por isso a síntese usa “até três anos”."},{"id":"q2","prompt":"Situação hipotética: uma pessoa iniciou essa prestação de serviços aos 64 anos. Ao completar 65, havia cumprido apenas um ano. Que regra se aplicava?","options":[{"label":"Deveria cumprir mais dois anos para completar os três.","id":"q2-o1"},{"label":"Deveria recomeçar a contagem do prazo de três anos.","id":"q2-o2"},{"label":"A obrigação de serviços cessava ao completar 65 anos.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"A regra de cessação aos 65 anos valia mesmo sem completar os três anos. O exemplo aplica essa condição; ele não afirma que todas as outras restrições de vida e subsistência também desapareciam."}]}','26f2114ca7832b4d99c155aeb50bc3e6d8848bcc5de7e141f976b4d7983d5f87',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-sequence-01','v28:21f565741333709a336be622f49e159394cc9825d3e2ee28917be2e9ca1228a7','Leis abolicionistas em ordem','sequence','8',ARRAY[]::text[],'21f565741333709a336be622f49e159394cc9825d3e2ee28917be2e9ca1228a7','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Situar três leis abolicionistas no tempo sem confundir suas diferentes consequências.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · Quilombos, rebeliões e processos de libertação","topic":"Leis de 1871, 1885 e 1888: cronologia e limites","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":57,"printedPage":"56"},{"pdfPage":59,"printedPage":"58"},{"pdfPage":61,"printedPage":"60"}],"itemSources":[{"itemId":"s1","pdfPages":[57]},{"itemId":"s2","pdfPages":[59]},{"itemId":"s3","pdfPages":[61]}]},"id":"livros-ef8-sequence-01","title":"Leis abolicionistas em ordem","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Ordene as leis pela data, da mais antiga à mais recente. Consulte as páginas 56, 58 e 60. A cronologia não apaga suas restrições nem as lutas coletivas que pressionaram pela abolição.","difficulty":"medio","bncc":[],"status":"draft","template":"sequence","items":[{"label":"1871: Lei do Ventre Livre, com declaração de liberdade e restrições.","id":"s1"},{"label":"1885: Lei dos Sexagenários, com obrigações de serviço.","id":"s2"},{"label":"1888: Lei Áurea e extinção jurídica da escravidão no Brasil.","id":"s3"}]}','21f565741333709a336be622f49e159394cc9825d3e2ee28917be2e9ca1228a7',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-02','v28:3bb523c48cc8986b88bb17225d2ff395d6281d7dc69b9d26d373f97e997ee884','Alimentação no Rio Negro: alcance do exemplo','quiz','8',ARRAY[]::text[],'3bb523c48cc8986b88bb17225d2ff395d6281d7dc69b9d26d373f97e997ee884','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Delimitar o que o caso do Rio Negro permite afirmar sobre alimentação e mudança histórica.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas: história e contribuições","topic":"Alimentação no Rio Negro: alcance do exemplo","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":83,"printedPage":"82"}],"itemSources":[{"itemId":"q1","pdfPages":[83]},{"itemId":"q2","pdfPages":[83]},{"itemId":"q3","pdfPages":[83]}]},"id":"livros-ef8-quiz-02","title":"Alimentação no Rio Negro: alcance do exemplo","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual planta o texto destaca no Sistema Agrícola Tradicional do Rio Negro?","options":[{"label":"Trigo.","id":"q1-o2"},{"label":"Mandioca.","id":"q1-o1"},{"label":"Oliveira.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O exemplo identifica a mandioca como importante em um sistema que também reúne técnicas, utensílios e redes de troca."},{"id":"q2","prompt":"O caso do Rio Negro permite definir a alimentação de todos os povos indígenas?","options":[{"label":"Sim; um caso local substitui outras pesquisas.","id":"q2-o2"},{"label":"Sim; todo povo tem exatamente o mesmo sistema agrícola.","id":"q2-o1"},{"label":"Não; é um exemplo específico e os conhecimentos variam.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"O livro delimita o exemplo ao Rio Negro e explica que conhecimentos alimentares variam entre povos e ambientes."},{"id":"q3","prompt":"Que fatores o texto relaciona a mudanças na disponibilidade de alimentos?","options":[{"label":"Uma regra que impede qualquer mudança nas práticas.","id":"q3-o1"},{"label":"Novas condições territoriais e contatos.","id":"q3-o2"},{"label":"A ausência completa de relações com o ambiente.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"Mudanças nas condições territoriais e nos contatos podem alterar a disponibilidade e os modos de obter alimentos."}]}','3bb523c48cc8986b88bb17225d2ff395d6281d7dc69b9d26d373f97e997ee884',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-03','v28:63c76dc420a632f18963446e28785a230199bb9fc51c4d23e3e64c051709d323','Ritxòkò: autoria e sentidos','quiz','8',ARRAY[]::text[],'63c76dc420a632f18963446e28785a230199bb9fc51c4d23e3e64c051709d323','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Contextualizar as figuras cerâmicas ritxòkò sem reduzi-las a padrões decorativos disponíveis para cópia.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas: história e contribuições","topic":"Ritxòkò: autoria e sentidos","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":95,"printedPage":"94"}],"itemSources":[{"itemId":"q1","pdfPages":[95]},{"itemId":"q2","pdfPages":[95]},{"itemId":"q3","pdfPages":[95]}]},"id":"livros-ef8-quiz-03","title":"Ritxòkò: autoria e sentidos","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"A quem o livro associa a produção de ritxòkò?","options":[{"label":"A todas as comunidades indígenas indistintamente.","id":"q1-o3"},{"label":"A um grupo sem identificação no texto.","id":"q1-o2"},{"label":"Às mulheres Iny, também conhecidas como Karajá.","id":"q1-o1"}],"correctOptionId":"q1-o1","explanation":"O caso nomeia as mulheres Iny/Karajá, permitindo reconhecer autoria em vez de atribuir a produção a um grupo genérico."},{"id":"q2","prompt":"Que produção recebe o nome ritxòkò no exemplo?","options":[{"label":"Figuras cerâmicas.","id":"q2-o3"},{"label":"Dicionários de palavras.","id":"q2-o1"},{"label":"Registros sonoros.","id":"q2-o2"}],"correctOptionId":"q2-o3","explanation":"O texto chama ritxòkò às figuras cerâmicas cuja produção envolve saberes e formas de expressão."},{"id":"q3","prompt":"Qual leitura é sustentada pelo caso?","options":[{"label":"As peças se relacionam à vida social e às referências culturais de seu povo.","id":"q3-o2"},{"label":"São desenhos sem relação com conhecimentos ou vida social.","id":"q3-o3"},{"label":"São um código universal que traduz qualquer grafismo indígena.","id":"q3-o1"}],"correctOptionId":"q3-o2","explanation":"As peças são contextualizadas na vida social Iny/Karajá, e não apresentadas como um código aplicável a todos os povos."}]}','63c76dc420a632f18963446e28785a230199bb9fc51c4d23e3e64c051709d323',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-04','v28:aff908db6b4ff7a937a9c8ecd65f9e09abb8564a4512831c3a8b00eced2353a6','Pesquisar a história de um nome','quiz','8',ARRAY[]::text[],'aff908db6b4ff7a937a9c8ecd65f9e09abb8564a4512831c3a8b00eced2353a6','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Distinguir investigação etimológica, mudança de sentido e presença indígena contemporânea.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Povos indígenas: história e contribuições","topic":"Pesquisar a história de um nome","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":91,"printedPage":"90"}],"itemSources":[{"itemId":"q1","pdfPages":[91]},{"itemId":"q2","pdfPages":[91]},{"itemId":"q3","pdfPages":[91]}]},"id":"livros-ef8-quiz-04","title":"Pesquisar a história de um nome","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas indicadas e responda com base no livro. O projeto de pesquisa do primeiro item é uma situação fictícia.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Situação fictícia: a turma quer pesquisar a origem de um nome de lugar. Por onde começar?","options":[{"label":"Por dicionários especializados e pesquisas linguísticas.","id":"q1-o1"},{"label":"Por adivinhações baseadas na sonoridade.","id":"q1-o2"},{"label":"Por uma explicação sem fonte repetida muitas vezes.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"A origem de palavras exige pesquisa: semelhança sonora e repetição de explicações não substituem fontes linguísticas."},{"id":"q2","prompt":"Por que registros de uma palavra podem apresentar diferenças?","options":[{"label":"As palavras nunca se transformam após entrar em outra língua.","id":"q2-o2"},{"label":"Ela pode mudar de forma e sentido ao circular.","id":"q2-o3"},{"label":"Toda diferença comprova que uma fonte foi falsificada.","id":"q2-o1"}],"correctOptionId":"q2-o3","explanation":"A circulação pode alterar formas e sentidos; registros feitos por falantes de outra língua também podem conter adaptações."},{"id":"q3","prompt":"O nome de origem indígena prova sozinho quais povos vivem hoje no lugar?","options":[{"label":"Sim; uma palavra substitui pesquisa sobre comunidades atuais.","id":"q3-o1"},{"label":"Não; a presença contemporânea exige outra investigação.","id":"q3-o2"},{"label":"Sim; nomes antigos sempre identificam os habitantes atuais.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"Origem linguística e presença contemporânea são perguntas diferentes; um topônimo não identifica sozinho os habitantes atuais."}]}','aff908db6b4ff7a937a9c8ecd65f9e09abb8564a4512831c3a8b00eced2353a6',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-association-01','v28:0b0321e2107bc92b1f17013a664f4e06a17b0db869291957458f94647ce92385','Educação indígena: conceitos e experiência','association','8',ARRAY[]::text[],'0b0321e2107bc92b1f17013a664f4e06a17b0db869291957458f94647ce92385','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Diferenciar processos educativos e reconhecer participação comunitária e transformação dos conhecimentos.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Direitos, educação e espiritualidade indígena","topic":"Educação indígena, educação escolar e Escola Pamáali","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":109,"printedPage":"108"},{"pdfPage":111,"printedPage":"110"},{"pdfPage":113,"printedPage":"112"}],"itemSources":[{"itemId":"p1","pdfPages":[109]},{"itemId":"p2","pdfPages":[109]},{"itemId":"p3","pdfPages":[111]},{"itemId":"p4","pdfPages":[113]}]},"id":"livros-ef8-association-01","title":"Educação indígena: conceitos e experiência","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Relacione os conceitos e o caso estudado às descrições das páginas 108, 110 e 112. Pamáali é uma experiência específica, não um modelo único para todos os povos.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Educação indígena"},"right":{"label":"Aprendizagens nas relações familiares, comunitárias e em diferentes atividades da vida."}},{"id":"p2","left":{"label":"Educação escolar indígena"},"right":{"label":"Ensino específico, diferenciado e intercultural, atento às línguas e à participação das comunidades."}},{"id":"p3","left":{"label":"Escola Pamáali"},"right":{"label":"Experiência educacional Baniwa e Koripako do Alto Rio Negro."}},{"id":"p4","left":{"label":"Conhecimentos tradicionais"},"right":{"label":"Saberes produzidos e transmitidos em trajetórias coletivas, que podem mudar."}}]}','0b0321e2107bc92b1f17013a664f4e06a17b0db869291957458f94647ce92385',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-association-63','v28:d991075015a610366c421d75bb97a6f6dfbdcb2c36ef338df39d115f53334e1b','Direção imperial e ação em juízo','association','8',ARRAY[]::text[],'d991075015a610366c421d75bb97a6f6dfbdcb2c36ef338df39d115f53334e1b','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Distinguir mecanismos do Regulamento das Missões e o reconhecimento da atuação indígena em juízo.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Direitos, educação e espiritualidade indígena","topic":"Distinguir mecanismos do Regulamento das Missões e o reconhecimento da atuação indígena em juízo.","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":103,"printedPage":"102"},{"pdfPage":104,"printedPage":"103"},{"pdfPage":105,"printedPage":"104"}],"itemSources":[{"itemId":"p1","pdfPages":[103]},{"itemId":"p2","pdfPages":[103]},{"itemId":"p3","pdfPages":[103]},{"itemId":"p4","pdfPages":[105]}]},"id":"livros-ef8-association-63","title":"Direção imperial e ação em juízo","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Consulte as páginas 102 a 104. Relacione cada aspecto ao que o livro informa sobre os textos de 1845 e 1988. A síntese de uma norma não descreve automaticamente a realidade de todas as comunidades.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Nomeação dos diretores prevista no Regulamento das Missões de 1845"},"right":{"label":"Cabia ao poder imperial."}},{"id":"p2","left":{"label":"Temas das medidas previstas no Regulamento das Missões"},"right":{"label":"Aldeamentos, trabalho e catequese."}},{"id":"p3","left":{"label":"Ideia imperial de “civilização” examinada no livro"},"right":{"label":"Pretensão de modificar modos de viver segundo um modelo valorizado pelas autoridades."}},{"id":"p4","left":{"label":"Defesa de direitos na Justiça admitida pela Constituição de 1988"},"right":{"label":"Indígenas, comunidades e organizações podem agir para defender seus direitos."}}]}','d991075015a610366c421d75bb97a6f6dfbdcb2c36ef338df39d115f53334e1b',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-20','v28:7e6bb3312605d96efa4e00d9a9fa8912440e320e647542a403dcf32073763051','Krenak na Constituinte','quiz','8',ARRAY[]::text[],'7e6bb3312605d96efa4e00d9a9fa8912440e320e647542a403dcf32073763051','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Relacionar um discurso indígena ao processo constituinte de 1987","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Direitos, educação e espiritualidade indígena","topic":"Relacionar um discurso indígena ao processo constituinte de 1987","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":123,"printedPage":"122"},{"pdfPage":124,"printedPage":"123"}],"itemSources":[{"itemId":"q1","pdfPages":[123]},{"itemId":"q2","pdfPages":[123]},{"itemId":"q3","pdfPages":[124]}]},"id":"livros-ef8-quiz-20","title":"Krenak na Constituinte","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Consulte as páginas 122, 123. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Em qual contexto Ailton Krenak realizou o discurso de 4 de setembro de 1987?","options":[{"label":"Durante a proclamação da DUDH em 1948.","id":"q1-o1"},{"label":"Durante a assinatura da Lei Áurea em 1888.","id":"q1-o2"},{"label":"Durante a Assembleia Constituinte.","id":"q1-o3"}],"correctOptionId":"q1-o3","explanation":"A intervenção ocorreu no debate constituinte, antes da Constituição de 1988."},{"id":"q2","prompt":"Que tema orientou a intervenção de Krenak?","options":[{"label":"A produção de kente em Gana.","id":"q2-o1"},{"label":"A defesa dos povos indígenas.","id":"q2-o2"},{"label":"A organização do comércio de Kilwa.","id":"q2-o3"}],"correctOptionId":"q2-o2","explanation":"O tema relaciona a fala à disputa pública pelos direitos dos povos indígenas."},{"id":"q3","prompt":"Onde foi publicado o registro do discurso indicado no livro?","options":[{"label":"Na revista GIS, da Universidade de São Paulo.","id":"q3-o1"},{"label":"No catálogo de uma máscara do Brooklyn Museum.","id":"q3-o2"},{"label":"Na ficha de patrimônio da UNESCO sobre kente.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"A identificação da revista oferece um caminho documental específico para estudar a intervenção."}]}','7e6bb3312605d96efa4e00d9a9fa8912440e320e647542a403dcf32073763051',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-05','v28:b433d360e3032ce7ba547c640f7de7ec213bcb9f596dcf707833b4b2f3c4776c','DUDH: contexto e alcance histórico','quiz','8',ARRAY[]::text[],'b433d360e3032ce7ba547c640f7de7ec213bcb9f596dcf707833b4b2f3c4776c','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Situar a Declaração de 1948 em seu contexto histórico e reconhecer relações entre educação e participação.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Identidade, diversidade e cidadania","topic":"DUDH: contexto e alcance histórico","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":133,"printedPage":"132"}],"itemSources":[{"itemId":"q1","pdfPages":[133]},{"itemId":"q2","pdfPages":[133]},{"itemId":"q3","pdfPages":[133]}]},"id":"livros-ef8-quiz-05","title":"DUDH: contexto e alcance histórico","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Em que contexto o livro situa a proclamação da Declaração Universal dos Direitos Humanos (DUDH)?","options":[{"label":"Antes da colonização europeia das Américas.","id":"q1-o3"},{"label":"Durante as negociações de Palmares, em 1678.","id":"q1-o2"},{"label":"Após as violências da Segunda Guerra Mundial, em 1948.","id":"q1-o1"}],"correctOptionId":"q1-o1","explanation":"O livro situa a proclamação pela ONU em 1948 após as violências da Segunda Guerra, contextualizando o marco internacional."},{"id":"q2","prompt":"Que cuidado evita tratar 1948 como origem de toda luta por direitos?","options":[{"label":"Afirmar que ninguém reivindicou direitos antes da ONU.","id":"q2-o1"},{"label":"Reconhecer que já havia lutas por direitos antes desse marco.","id":"q2-o3"},{"label":"Excluir do estudo movimentos anteriores à Declaração.","id":"q2-o2"}],"correctOptionId":"q2-o3","explanation":"A Declaração é um marco histórico, mas o texto alerta que ela não iniciou todas as reivindicações por direitos."},{"id":"q3","prompt":"Que exemplo do texto mostra que os direitos se relacionam?","options":[{"label":"A participação pode ser avaliada sem considerar condições educacionais.","id":"q3-o3"},{"label":"O acesso à educação depende apenas da vontade individual.","id":"q3-o2"},{"label":"Dificuldades de acesso à educação podem limitar a participação.","id":"q3-o1"}],"correctOptionId":"q3-o1","explanation":"O exemplo mostra que uma barreira educacional pode afetar outro campo de direitos, a participação, evidenciando sua interdependência."}]}','b433d360e3032ce7ba547c640f7de7ec213bcb9f596dcf707833b4b2f3c4776c',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-06','v28:6a3ef82c2577e44545608f6eb7a57b51cb1d739702c63732f44dac5ae5f76fe1','Teorias raciais e autoridade científica','quiz','8',ARRAY[]::text[],'6a3ef82c2577e44545608f6eb7a57b51cb1d739702c63732f44dac5ae5f76fe1','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Analisar historicamente o uso de teorias raciais do século XIX para justificar dominação.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Identidade, diversidade e cidadania","topic":"Teorias raciais e autoridade científica","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":137,"printedPage":"136"}],"itemSources":[{"itemId":"q1","pdfPages":[137]},{"itemId":"q2","pdfPages":[137]},{"itemId":"q3","pdfPages":[137]}]},"id":"livros-ef8-quiz-06","title":"Teorias raciais e autoridade científica","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Como as teorias raciais do século XIX tentavam justificar uma suposta superioridade de alguns grupos humanos sobre outros?","options":[{"label":"Reconhecendo-as apenas como gostos pessoais sem efeito social.","id":"q1-o2"},{"label":"Apresentando-as como verdades científicas.","id":"q1-o1"},{"label":"Defendendo que todas as relações de dominação tinham terminado.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"As teorias tentaram dar aparência de verdade científica a hierarquias humanas, mobilizando argumentos de autoridade."},{"id":"q2","prompt":"Que uso político dessas ideias o texto destaca?","options":[{"label":"Justificar dominação e exclusão, inclusive no imperialismo.","id":"q2-o3"},{"label":"Garantir iguais oportunidades em todas as colônias.","id":"q2-o2"},{"label":"Impedir toda expansão imperialista.","id":"q2-o1"}],"correctOptionId":"q2-o3","explanation":"O texto relaciona essas ideias à legitimação de dominação e exclusão, inclusive em contextos imperialistas."},{"id":"q3","prompt":"Por que estudar essas teorias não significa aceitá-las?","options":[{"label":"O estudo investiga como argumentos de autoridade sustentaram relações de poder.","id":"q3-o2"},{"label":"Toda teoria antiga passa a ser válida quando entra no livro.","id":"q3-o1"},{"label":"O estudo exige repetir suas hierarquias como verdade.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"Investigar como uma teoria foi usada para sustentar poder permite criticá-la; não exige aceitar suas hierarquias."}]}','6a3ef82c2577e44545608f6eb7a57b51cb1d739702c63732f44dac5ae5f76fe1',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef8-quiz-07','v28:54c9ac91c96c2e643d0c498e41ce8923de1eace2b4b906b3aba75225af65e204','Analisar ações afirmativas','quiz','8',ARRAY[]::text[],'54c9ac91c96c2e643d0c498e41ce8923de1eace2b4b906b3aba75225af65e204','{"schemaVersion":1,"catalog":{"band":"EF8","area":"historia","batch":"livros-historia-v18","objective":"Identificar problema, critérios e avaliação em políticas de ação afirmativa sem estigmatizar beneficiários.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":8,"bookId":"historia-ef8","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 5 · Identidade, diversidade e cidadania","topic":"Analisar ações afirmativas","sourceUrl":"https://drive.google.com/file/d/1b6CqgGFxwktinicoqeIv6td4e_HXgW43/view","pages":[{"pdfPage":141,"printedPage":"140"}],"itemSources":[{"itemId":"q1","pdfPages":[141]},{"itemId":"q2","pdfPages":[141]},{"itemId":"q3","pdfPages":[141]}]},"id":"livros-ef8-quiz-07","title":"Analisar ações afirmativas","grade":"8º ano","subject":"História","collection":{"id":"historia-ef8","title":"História Indígena e Afro-Brasileira · 8º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual finalidade caracteriza as ações afirmativas no texto?","options":[{"label":"Enfrentar desvantagens históricas e ampliar participação.","id":"q1-o1"},{"label":"Premiar uma suposta superioridade biológica.","id":"q1-o3"},{"label":"Substituir uma hierarquia racial por outra.","id":"q1-o2"}],"correctOptionId":"q1-o1","explanation":"O texto define essas medidas em relação a desvantagens produzidas historicamente, não a diferenças de capacidade biológica."},{"id":"q2","prompt":"Qual conjunto permite começar a analisar uma política de ação afirmativa?","options":[{"label":"Apenas uma frase isolada favorável ou contrária.","id":"q2-o1"},{"label":"Somente impressões sobre a aparência de beneficiários.","id":"q2-o2"},{"label":"Problema, critérios e resultados pretendidos.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"Esses campos permitem entender o desenho e a finalidade da medida antes de julgá-la por uma frase isolada."},{"id":"q3","prompt":"Qual pergunta ajuda a avaliar resultados?","options":[{"label":"Como presumir que todos os beneficiários têm a mesma trajetória?","id":"q3-o3"},{"label":"Como dispensar evidências após a divulgação da política?","id":"q3-o1"},{"label":"Que barreiras diminuíram e que dificuldades persistiram para o público alcançado?","id":"q3-o2"}],"correctOptionId":"q3-o2","explanation":"A avaliação precisa observar alcance e mudanças nas barreiras, incluindo dificuldades que a política ainda não resolveu."}]}','54c9ac91c96c2e643d0c498e41ce8923de1eace2b4b906b3aba75225af65e204',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-quiz-66','v28:24166b5d90b73bdc78971006ab0d0df1e6316702e53c4538b2e0cada0d5ba1cd','Trabalho contemporâneo: ler os conceitos','quiz','9',ARRAY[]::text[],'24166b5d90b73bdc78971006ab0d0df1e6316702e53c4538b2e0cada0d5ba1cd','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Compare cada alternativa com a síntese do artigo no livro, um termo de cada vez. Palavras parecidas podem descrever situações diferentes; não decida apenas pelo tamanho da lista."},{"itemId":"q2","text":"Separe a leitura em dois pontos: o papel das correntes e a necessidade de as situações ocorrerem juntas. Confira as duas afirmações de cada alternativa no texto antes de escolher."}]},"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Reconhecer hipóteses citadas do art. 149 e limites de sua interpretação em uma leitura escolar.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Encerramento","topic":"Reconhecer hipóteses citadas do art. 149 e limites de sua interpretação em uma leitura escolar.","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":151,"printedPage":"150"},{"pdfPage":152,"printedPage":"151"}],"itemSources":[{"itemId":"q1","pdfPages":[151]},{"itemId":"q2","pdfPages":[151]},{"itemId":"q3","pdfPages":[152]}]},"id":"livros-ef9-quiz-66","title":"Trabalho contemporâneo: ler os conceitos","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Consulte as páginas 150 e 151. Escolha uma resposta por pergunta sobre a síntese do livro. A atividade não pede classificação de casos reais nem investigação de locais ou trabalhadores.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Qual alternativa reúne as situações citadas pelo livro na síntese do artigo 149?","options":[{"label":"Trabalho temporário, jornada exaustiva, condições degradantes e restrição de locomoção por dívida.","id":"q1-o1"},{"label":"Trabalho forçado, jornada exaustiva, condições degradantes e restrição de locomoção por dívida.","id":"q1-o2"},{"label":"Trabalho forçado, jornada em tempo parcial, condições degradantes e restrição de locomoção por dívida.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O livro cita trabalho forçado, jornada exaustiva, condições degradantes e restrição de locomoção por dívida, conforme os elementos legais. “Temporário” e “em tempo parcial” não substituem os termos dessa síntese."},{"id":"q2","prompt":"Segundo o livro, correntes são obrigatórias para caracterizar o crime? Todas as situações citadas precisam ocorrer juntas? Escolha a alternativa que responde corretamente às duas perguntas.","options":[{"label":"As hipóteses só caracterizam o crime quando acompanhadas por correntes ou confinamento físico.","id":"q2-o1"},{"label":"Na ausência de correntes, todas as hipóteses precisam necessariamente ocorrer juntas.","id":"q2-o2"},{"label":"A caracterização não depende exclusivamente de correntes, e as formas não precisam aparecer todas juntas.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"A página 150 afasta duas exigências indevidas: presença obrigatória de correntes e reunião obrigatória de todas as formas descritas. Isso não dispensa a análise dos elementos legais."},{"id":"q3","prompt":"Por que uma irregularidade trabalhista não é automaticamente classificada como o crime descrito no artigo 149?","options":[{"label":"Porque a análise de casos concretos exige apuração competente.","id":"q3-o1"},{"label":"Porque uma classificação criminal depende apenas do nome usado em uma notícia.","id":"q3-o2"},{"label":"Porque a identificação de qualquer descumprimento já substitui a apuração.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"O livro diferencia irregularidade e classificação automática como crime. A página 151 exige apuração competente para analisar casos concretos, tarefa que não cabe à atividade escolar."}]}','24166b5d90b73bdc78971006ab0d0df1e6316702e53c4538b2e0cada0d5ba1cd',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-quiz-67','v28:492bfdd8c60c7f9ae8c62a5dc8e452c7fcd68b59a4d0d424bed01fa200d7ee05','Custos ambientais e justiça social','quiz','9',ARRAY[]::text[],'492bfdd8c60c7f9ae8c62a5dc8e452c7fcd68b59a4d0d424bed01fa200d7ee05','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q1","text":"Organize o relatório em um quadro: grupo mencionado, benefícios, custos ou riscos e dados que sustentam cada informação. Veja quais campos ficaram sem informação e compare-os com as alternativas."}]},"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Analisar a distribuição de riscos e benefícios e a dimensão de infraestrutura nos problemas de saneamento.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Encerramento","topic":"Analisar a distribuição de riscos e benefícios e a dimensão de infraestrutura nos problemas de saneamento.","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":153,"printedPage":"152"},{"pdfPage":154,"printedPage":"153"}],"itemSources":[{"itemId":"q1","pdfPages":[153]},{"itemId":"q2","pdfPages":[153]},{"itemId":"q3","pdfPages":[153]}]},"id":"livros-ef9-quiz-67","title":"Custos ambientais e justiça social","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Leia as páginas 152 e 153. Escolha uma resposta por pergunta sobre a distribuição de benefícios e custos ambientais. O exemplo da primeira questão é hipotético.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Um relatório hipotético apresenta apenas os benefícios de uma obra. Que informações faltam para analisar quem recebe os benefícios e quem enfrenta os custos ambientais?","options":[{"label":"Considerar os benefícios gerais como prova de que todos enfrentam os mesmos riscos.","id":"q1-o1"},{"label":"Identificar a população afetada, os riscos, as alternativas e os dados, pois custos e benefícios podem alcançar grupos diferentes.","id":"q1-o2"},{"label":"Usar o benefício de um grupo para compensar no relatório qualquer custo enfrentado por outro, sem investigar os efeitos.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O texto afirma que uma obra pode beneficiar alguns e impor custos ambientais a outros. Por isso, a análise precisa identificar os afetados, os dados e as alternativas, e não apenas somar benefícios."},{"id":"q2","prompt":"Por que a falta de saneamento em um território sem serviço adequado não deve ser tratada como escolha pessoal dos moradores?","options":[{"label":"Porque a ausência de serviço resulta apenas da preferência de cada família.","id":"q2-o1"},{"label":"Porque atitudes de consumo bastam para oferecer toda a infraestrutura que falta.","id":"q2-o2"},{"label":"Porque o problema envolve condições de infraestrutura que não se reduzem às escolhas individuais.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"A leitura liga o problema à falta de serviço e à infraestrutura. Atribuí-lo apenas a decisões individuais apagaria condições que os moradores não resolvem somente por suas escolhas de consumo."},{"id":"q3","prompt":"Que critério aproxima cuidado ambiental e justiça social segundo a leitura?","options":[{"label":"Buscar proteção sem transferir todo o custo a grupos com menos poder.","id":"q3-o1"},{"label":"Concentrar o custo nos grupos com menos poder para preservar os benefícios dos demais.","id":"q3-o2"},{"label":"Avaliar apenas o benefício total, sem distinguir quais grupos suportam os custos.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"A página 152 relaciona justiça social e cuidado ambiental à busca de proteção sem impor todo o custo aos grupos com menos poder. A distribuição importa, além da existência de algum benefício."}]}','492bfdd8c60c7f9ae8c62a5dc8e452c7fcd68b59a4d0d424bed01fa200d7ee05',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-association-64','v28:c5768a6cdadd7b65a3a16711aa39c2ce24a118067e76b9d15b76a512f18d745d','Frente Negra e Teatro Experimental','association','9',ARRAY[]::text[],'c5768a6cdadd7b65a3a16711aa39c2ce24a118067e76b9d15b76a512f18d745d','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Distinguir a Frente Negra Brasileira e o Teatro Experimental do Negro por sua criação e atuação.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Abolição, liberdade e desigualdades raciais","topic":"Distinguir a Frente Negra Brasileira e o Teatro Experimental do Negro por sua criação e atuação.","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":27,"printedPage":"26"},{"pdfPage":28,"printedPage":"27"}],"itemSources":[{"itemId":"p1","pdfPages":[27]},{"itemId":"p2","pdfPages":[27]}]},"id":"livros-ef9-association-64","title":"Frente Negra e Teatro Experimental","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Consulte as páginas 26 e 27. Relacione cada organização ao conjunto de informações apresentado no livro. Esses exemplos não resumem todas as organizações do movimento negro.","difficulty":"facil","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Frente Negra Brasileira"},"right":{"label":"Criada em 1931; articulou atividades sociais, educacionais e políticas."}},{"id":"p2","left":{"label":"Teatro Experimental do Negro"},"right":{"label":"Fundado em 1944 por Abdias Nascimento; enfrentou a exclusão de pessoas negras dos palcos e relacionou arte e cidadania."}}]}','c5768a6cdadd7b65a3a16711aa39c2ce24a118067e76b9d15b76a512f18d745d',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-association-65','v28:6330ce7455467b9590dfd41aaac5e37ae6aeea736e9b60d81ae6be2b5d3673d3','Cotas: níveis e inclusão','association','9',ARRAY[]::text[],'6330ce7455467b9590dfd41aaac5e37ae6aeea736e9b60d81ae6be2b5d3673d3','{"schemaVersion":1,"pedagogicalSupport":{"overview":"Monte duas colunas: nível de ensino ao qual a pessoa quer ingressar e escolarização anterior exigida na síntese. Compare os artigos separadamente. Depois identifique quais descrições tratam de apoio à participação e à continuidade dos estudos."},"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Distinguir níveis de ensino e escolarização prévia nas sínteses da Lei de Cotas e identificar outras medidas de inclusão.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Abolição, liberdade e desigualdades raciais","topic":"Distinguir níveis de ensino e escolarização prévia nas sínteses da Lei de Cotas e identificar outras medidas de inclusão.","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":35,"printedPage":"34"},{"pdfPage":36,"printedPage":"35"}],"itemSources":[{"itemId":"p1","pdfPages":[36]},{"itemId":"p2","pdfPages":[36]},{"itemId":"p3","pdfPages":[35]}]},"id":"livros-ef9-association-65","title":"Cotas: níveis e inclusão","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Leia as páginas 34 e 35. Relacione cada recorte à síntese correspondente. A atividade se limita ao texto do livro e não apresenta todas as regras de inscrição.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Graduação federal vinculada ao MEC: síntese do art. 1º"},"right":{"label":"Todo o ensino médio em escolas públicas ou em determinadas escolas comunitárias do campo conveniadas."}},{"id":"p2","left":{"label":"Ensino técnico federal de nível médio: síntese do art. 4º"},"right":{"label":"Todo o ensino fundamental em escolas públicas."}},{"id":"p3","left":{"label":"Medidas de inclusão além da reserva de vagas"},"right":{"label":"Apoio à permanência, acessibilidade e iniciativas de formação."}}]}','6330ce7455467b9590dfd41aaac5e37ae6aeea736e9b60d81ae6be2b5d3673d3',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-quiz-01','v28:ef2130fd5e0b824c82f998d5b1ca4596849779edfe603b464b1403209138b109','Desigualdades: ler dados e leis','quiz','9',ARRAY[]::text[],'ef2130fd5e0b824c82f998d5b1ca4596849779edfe603b464b1403209138b109','{"schemaVersion":1,"pedagogicalSupport":{"items":[{"itemId":"q2","text":"Leia a definição da taxa na fonte e escreva-a como uma fração. Identifique quem é contado no numerador e qual conjunto aparece no denominador. Confira se a alternativa mantém o mesmo grupo de referência."}]},"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Interpretar indicadores históricos e distinguir existência de normas de sua implementação.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Abolição, liberdade e desigualdades raciais","topic":"Desigualdades raciais: indicadores e implementação de direitos","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":23,"printedPage":"22"},{"pdfPage":25,"printedPage":"24"},{"pdfPage":33,"printedPage":"32"}],"itemSources":[{"itemId":"q1","pdfPages":[23]},{"itemId":"q2","pdfPages":[25]},{"itemId":"q3","pdfPages":[33]}]},"id":"livros-ef9-quiz-01","title":"Desigualdades: ler dados e leis","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Consulte as páginas 22, 24 e 32. Preserve o ano, a população de referência e os limites de cada informação.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"No Censo 2022 citado no livro, os percentuais de ensino superior completo se referem a qual população?","options":[{"label":"A todos os estudantes matriculados em universidades.","id":"o1"},{"label":"Às pessoas de 25 anos ou mais, em cada grupo informado.","id":"o2"},{"label":"A todas as crianças e adolescentes de cada grupo.","id":"o3"}],"correctOptionId":"o2","explanation":"Os resultados citados têm ano, população e indicador específicos: Censo 2022, pessoas de 25 anos ou mais e nível superior completo."},{"id":"q2","prompt":"O que a taxa de desocupação de um grupo relaciona?","options":[{"label":"O grupo a todas as pessoas desempregadas do país.","id":"o1"},{"label":"Todas as pessoas do grupo à população brasileira inteira.","id":"o2"},{"label":"As pessoas desocupadas à força de trabalho do próprio grupo.","id":"o3"}],"correctOptionId":"o3","explanation":"O denominador é a força de trabalho do próprio grupo. Não se trata de sua participação no total de desempregados."},{"id":"q3","prompt":"A existência do Estatuto da Igualdade Racial permite concluir que todas as desigualdades terminaram?","options":[{"label":"Não. É preciso investigar implementação, instituições e experiências das pessoas.","id":"o1"},{"label":"Sim. Uma norma comprova que seus objetivos foram plenamente alcançados.","id":"o2"},{"label":"Sim. Depois da lei, dados e experiências deixam de ser necessários.","id":"o3"}],"correctOptionId":"o1","explanation":"Uma lei orienta direitos e responsabilidades. Seus efeitos precisam ser investigados."}]}','ef2130fd5e0b824c82f998d5b1ca4596849779edfe603b464b1403209138b109',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-quiz-20','v28:ad75435c5b3d6723c904b88eef112b09353eff457aa30a252bd00fa9fe84fb20','Abdias e Lélia: campos de atuação','quiz','9',ARRAY[]::text[],'ad75435c5b3d6723c904b88eef112b09353eff457aa30a252bd00fa9fe84fb20','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Comparar formas de produção intelectual e intervenção pública de duas trajetórias negras","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Abolição, liberdade e desigualdades raciais","topic":"Comparar formas de produção intelectual e intervenção pública de duas trajetórias negras","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":37,"printedPage":"36"}],"itemSources":[{"itemId":"q1","pdfPages":[37]},{"itemId":"q2","pdfPages":[37]},{"itemId":"q3","pdfPages":[37]}]},"id":"livros-ef9-quiz-20","title":"Abdias e Lélia: campos de atuação","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Consulte a página 36. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Que campos Abdias Nascimento articulou?","options":[{"label":"Engenharia, arquitetura e urbanismo.","id":"q1-o1"},{"label":"Teatro, pensamento e atuação política.","id":"q1-o2"},{"label":"Medicina, saúde pública e enfermagem.","id":"q1-o3"}],"correctOptionId":"q1-o2","explanation":"O texto reúne criação teatral, reflexão e participação política na mesma trajetória."},{"id":"q2","prompt":"Sobre quais questões Lélia Gonzalez produziu reflexões?","options":[{"label":"Racismo, sexismo e cultura.","id":"q2-o1"},{"label":"Arquitetura, navegação e comércio.","id":"q2-o2"},{"label":"Agricultura, metalurgia e mineração.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"As reflexões citadas articulam desigualdades e cultura, e não um tema técnico isolado."},{"id":"q3","prompt":"Que atuação de Lélia é mencionada além da reflexão intelectual?","options":[{"label":"Administração de um reino africano.","id":"q3-o1"},{"label":"Direção de pesquisas arqueológicas sobre Meroé.","id":"q3-o2"},{"label":"Participação em movimentos sociais.","id":"q3-o3"}],"correctOptionId":"q3-o3","explanation":"A participação em movimentos aproxima produção de conhecimento e ação pública no exemplo apresentado."}]}','ad75435c5b3d6723c904b88eef112b09353eff457aa30a252bd00fa9fe84fb20',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-sequence-01','v28:c87fac692b4f4b0fbfd48a93bef5fd2a204ebe8b99fb9103889af3f811a6d521','Marcos de lutas e direitos','sequence','9',ARRAY[]::text[],'c87fac692b4f4b0fbfd48a93bef5fd2a204ebe8b99fb9103889af3f811a6d521','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Situar marcos jurídicos e de mobilização social em uma cronologia sem reduzir a história a leis.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 1 · Abolição, liberdade e desigualdades raciais","topic":"Abolição, MNU, Estatuto da Igualdade Racial e Lei de Cotas","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":13,"printedPage":"12"},{"pdfPage":29,"printedPage":"28"},{"pdfPage":33,"printedPage":"32"},{"pdfPage":35,"printedPage":"34"}],"itemSources":[{"itemId":"s1","pdfPages":[13]},{"itemId":"s2","pdfPages":[29]},{"itemId":"s3","pdfPages":[33]},{"itemId":"s4","pdfPages":[35]}]},"id":"livros-ef9-sequence-01","title":"Marcos de lutas e direitos","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Ordene os quatro marcos do mais antigo ao mais recente. Consulte as páginas 12, 28, 32 e 34. Nenhum deles significa que a luta negra começou naquela data ou que todas as desigualdades acabaram.","difficulty":"medio","bncc":[],"status":"draft","template":"sequence","items":[{"label":"1888: Lei Áurea e extinção jurídica da escravidão.","id":"s1"},{"label":"1978: ato público em São Paulo do movimento que se consolidaria como MNU.","id":"s2"},{"label":"2010: instituição do Estatuto da Igualdade Racial.","id":"s3"},{"label":"2012: Lei nº 12.711 sobre reserva de vagas em instituições federais de ensino.","id":"s4"}]}','c87fac692b4f4b0fbfd48a93bef5fd2a204ebe8b99fb9103889af3f811a6d521',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-association-02','v28:d60aa676bacf78ad0ee3d7cbd7a1b3ea9816cee239a1668185f5e25f07230ce3','Autora, narradora e circulação','association','9',ARRAY[]::text[],'d60aa676bacf78ad0ee3d7cbd7a1b3ea9816cee239a1668185f5e25f07230ce3','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Distinguir dimensões da leitura literária no estudo de Carolina Maria de Jesus e Conceição Evaristo.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · África, diáspora e formação cultural brasileira","topic":"Autora, narradora e circulação","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":69,"printedPage":"68"}],"itemSources":[{"itemId":"p1","pdfPages":[69]},{"itemId":"p2","pdfPages":[69]},{"itemId":"p3","pdfPages":[69]}]},"id":"livros-ef9-association-02","title":"Autora, narradora e circulação","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Leia as páginas indicadas e responda com base no livro. Considere a leitura que apresenta Carolina Maria de Jesus e Conceição Evaristo; não confunda biografia com análise literária.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Autora"},"right":{"label":"Pessoa com trajetória histórica."}},{"id":"p2","left":{"label":"Narradora"},"right":{"label":"Voz construída no texto."}},{"id":"p3","left":{"label":"Circulação"},"right":{"label":"Edição, leitores e biblioteca."}}]}','d60aa676bacf78ad0ee3d7cbd7a1b3ea9816cee239a1668185f5e25f07230ce3',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-quiz-02','v28:77b7307c35779f11f84c1e587e8e2c2c486ba58014c6e1e493752fb1c66eabd7','Museu Afro Brasil: escolhas e legendas','quiz','9',ARRAY[]::text[],'77b7307c35779f11f84c1e587e8e2c2c486ba58014c6e1e493752fb1c66eabd7','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Examinar a mediação museológica e o tratamento de lacunas nas legendas do acervo.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · África, diáspora e formação cultural brasileira","topic":"Museu Afro Brasil: escolhas e legendas","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":71,"printedPage":"70"}],"itemSources":[{"itemId":"q1","pdfPages":[71]},{"itemId":"q2","pdfPages":[71]},{"itemId":"q3","pdfPages":[71]}]},"id":"livros-ef9-quiz-02","title":"Museu Afro Brasil: escolhas e legendas","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"Ao estudar o Museu Afro Brasil Emanoel Araujo, quais escolhas merecem análise?","options":[{"label":"Apenas o tamanho físico do edifício.","id":"q1-o1"},{"label":"Somente a quantidade de visitantes, sem observar o acervo.","id":"q1-o2"},{"label":"Seleção de objetos, organização dos percursos e legendas.","id":"q1-o3"}],"correctOptionId":"q1-o3","explanation":"Selecionar, organizar e legendar são decisões que influenciam o que o público percebe e pergunta sobre o acervo."},{"id":"q2","prompt":"Qual conjunto torna uma legenda mais informativa?","options":[{"label":"Somente a palavra “antigo”.","id":"q2-o3"},{"label":"Um nome de autor inventado para evitar lacunas.","id":"q2-o1"},{"label":"Autoria conhecida, título, data ou período, material e contexto.","id":"q2-o2"}],"correctOptionId":"q2-o2","explanation":"Essas informações identificam e contextualizam a obra; uma classificação genérica como “antigo” deixa lacunas importantes."},{"id":"q3","prompt":"Como registrar a autoria quando ela é desconhecida?","options":[{"label":"Atribuir a obra ao artista mais conhecido do período.","id":"q3-o2"},{"label":"Informar a lacuna, sem inventar um nome.","id":"q3-o1"},{"label":"Omitir o objeto porque não pode ser estudado.","id":"q3-o3"}],"correctOptionId":"q3-o1","explanation":"O livro orienta declarar o desconhecimento: inventar autoria transformaria uma lacuna documental em informação falsa."}]}','77b7307c35779f11f84c1e587e8e2c2c486ba58014c6e1e493752fb1c66eabd7',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-quiz-03','v28:482ac75f92e0baeb99df00dddb9dee07e0cddbe9f3560e93665d56ec64af819e','Cais do Valongo: memória e interpretação','quiz','9',ARRAY[]::text[],'482ac75f92e0baeb99df00dddb9dee07e0cddbe9f3560e93665d56ec64af819e','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Relacionar o lugar de memória do Cais do Valongo à pesquisa e à participação na construção de narrativas.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 2 · África, diáspora e formação cultural brasileira","topic":"Cais do Valongo: memória e interpretação","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":75,"printedPage":"74"}],"itemSources":[{"itemId":"q1","pdfPages":[75]},{"itemId":"q2","pdfPages":[75]},{"itemId":"q3","pdfPages":[75]}]},"id":"livros-ef9-quiz-03","title":"Cais do Valongo: memória e interpretação","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Leia as páginas indicadas e responda com base no livro.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"A que história o livro relaciona o Cais do Valongo, no Rio de Janeiro?","options":[{"label":"À capital do Reino do Kongo.","id":"q1-o2"},{"label":"Ao desembarque de africanos escravizados.","id":"q1-o3"},{"label":"À publicação de Quarto de despejo.","id":"q1-o1"}],"correctOptionId":"q1-o3","explanation":"O livro situa o cais no Rio de Janeiro e o relaciona ao desembarque de africanos escravizados, fundamento de sua importância como memória."},{"id":"q2","prompt":"Por que preservar a memória do Cais do Valongo não significa celebrar a violência?","options":[{"label":"Porque transforma o desembarque em lembrança de uma viagem voluntária.","id":"q2-o2"},{"label":"Porque torna visíveis histórias e sujeitos que foram apagados.","id":"q2-o1"},{"label":"Porque substitui a história das pessoas por uma celebração da arquitetura.","id":"q2-o3"}],"correctOptionId":"q2-o1","explanation":"A preservação pode enfrentar apagamentos históricos e reconhecer sujeitos; lembrar criticamente a violência não é exaltá-la."},{"id":"q3","prompt":"Além de conservar o cais, que pergunta ajuda a analisar como sua história é contada?","options":[{"label":"Quem participa da construção da narrativa sobre o lugar?","id":"q3-o1"},{"label":"Como dispensar a pesquisa depois da instalação de uma placa?","id":"q3-o3"},{"label":"Como eliminar todas as vozes diferentes da narrativa?","id":"q3-o2"}],"correctOptionId":"q3-o1","explanation":"A narrativa patrimonial envolve escolhas; perguntar pela participação ajuda a perceber quais vozes são ouvidas ou silenciadas."}]}','482ac75f92e0baeb99df00dddb9dee07e0cddbe9f3560e93665d56ec64af819e',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-completion-01','v28:979ed8957378bfea02b43b7c53477b88940f4675bce066c93c194ccc9fbc4b12','Conceitos para uma participação responsável','completion','9',ARRAY[]::text[],'979ed8957378bfea02b43b7c53477b88940f4675bce066c93c194ccc9fbc4b12','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Distinguir julgamentos e práticas discriminatórias e identificar cuidados na circulação de informação.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 3 · Direitos humanos, cidadania e justiça social","topic":"Preconceito, discriminação e verificação de informação","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":97,"printedPage":"96"},{"pdfPage":105,"printedPage":"104"}],"itemSources":[{"itemId":"b1","pdfPages":[97]},{"itemId":"b2","pdfPages":[97]},{"itemId":"b3","pdfPages":[105]}]},"id":"livros-ef9-completion-01","title":"Conceitos para uma participação responsável","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Complete com apoio nas páginas 96 e 104. Diferencie conceitos e reconheça a necessidade de verificar informações antes de divulgá-las.","difficulty":"medio","bncc":[],"status":"draft","template":"completion","blanks":[{"id":"b1","before":"O julgamento prévio e generalizante sobre pessoas ou grupos é chamado de ","after":".","answers":["preconceito"],"options":[{"label":"preconceito","id":"o1"},{"label":"indicador","id":"o2"},{"label":"patrimônio","id":"o3"}]},{"id":"b2","before":"O tratamento desigual que produz exclusão ou desvantagem caracteriza ","after":".","answers":["discriminação"],"options":[{"label":"convivência","id":"o1"},{"label":"discriminação","id":"o2"},{"label":"preservação","id":"o3"}]},{"id":"b3","before":"Antes de divulgar uma informação, procure a ","after":" e compare com registros confiáveis.","answers":["fonte original"],"options":[{"label":"maior contagem de curtidas","id":"o1"},{"label":"versão mais repetida","id":"o2"},{"label":"fonte original","id":"o3"}]}]}','979ed8957378bfea02b43b7c53477b88940f4675bce066c93c194ccc9fbc4b12',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-association-01','v28:b0923a7dee2fdfae8df639e73cbfdc78c79a588b34704e3e88bb1b28505ec60f','Povos indígenas: sujeitos e conhecimentos','association','9',ARRAY[]::text[],'b0923a7dee2fdfae8df639e73cbfdc78c79a588b34704e3e88bb1b28505ec60f','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Relacionar sujeitos e conhecimentos indígenas a seus contextos sem apagar autoria ou direitos.","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Povos indígenas: história, território e resistência","topic":"Território, FOIRN, sistema agrícola e arte kusiwa","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":123,"printedPage":"122"},{"pdfPage":129,"printedPage":"128"},{"pdfPage":131,"printedPage":"130"},{"pdfPage":133,"printedPage":"132"}],"itemSources":[{"itemId":"p1","pdfPages":[123]},{"itemId":"p2","pdfPages":[129]},{"itemId":"p3","pdfPages":[131]},{"itemId":"p4","pdfPages":[133]}]},"id":"livros-ef9-association-01","title":"Povos indígenas: sujeitos e conhecimentos","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Relacione cada conceito ou exemplo à descrição apoiada nas páginas 122, 128, 130 e 132. Reconhecer um conhecimento não autoriza qualquer reprodução.","difficulty":"medio","bncc":[],"status":"draft","template":"association","pairs":[{"id":"p1","left":{"label":"Território indígena"},"right":{"label":"Espaços vividos de moradia, circulação, produção e memória."}},{"id":"p2","left":{"label":"FOIRN"},"right":{"label":"Federação que articula organizações indígenas do Rio Negro."}},{"id":"p3","left":{"label":"Sistema Agrícola Tradicional do Rio Negro"},"right":{"label":"Práticas de cultivo, diversidade de plantas, saberes e relações comunitárias."}},{"id":"p4","left":{"label":"Arte kusiwa dos Wajãpi"},"right":{"label":"Expressões gráficas e conhecimentos próprios, com limites de circulação e cópia."}}]}','b0923a7dee2fdfae8df639e73cbfdc78c79a588b34704e3e88bb1b28505ec60f',true);
insert into mission_private.revisions(activity_key,revision,title,engine,grade,age_ranges,content_hash,source_json,source_sha256,published) values('livros-ef9-quiz-21','v28:ad94cce603cb774fac62fb6d9aadda4b89f2fd34cdb21076d6b5856358485fb8','Kopenawa e organização Yanomami','quiz','9',ARRAY[]::text[],'ad94cce603cb774fac62fb6d9aadda4b89f2fd34cdb21076d6b5856358485fb8','{"schemaVersion":1,"catalog":{"band":"EF9","area":"historia","batch":"livros-historia-v18","objective":"Relacionar atuação intelectual e territorial à organização coletiva Yanomami","readingRequired":true,"visualSupport":[]},"bookReference":{"year":9,"bookId":"historia-ef9","bookTitle":"Raízes e Saberes • História e Cultura Afro-Brasileira e Indígena","unit":"Unidade 4 · Povos indígenas: história, território e resistência","topic":"Relacionar atuação intelectual e territorial à organização coletiva Yanomami","sourceUrl":"https://drive.google.com/file/d/1OXwOTFgdemTkg6_hN6mX55S_HZfve62C/view","pages":[{"pdfPage":137,"printedPage":"136"}],"itemSources":[{"itemId":"q1","pdfPages":[137]},{"itemId":"q2","pdfPages":[137]},{"itemId":"q3","pdfPages":[137]}]},"id":"livros-ef9-quiz-21","title":"Kopenawa e organização Yanomami","grade":"9º ano","subject":"História","collection":{"id":"historia-ef9","title":"História Indígena e Afro-Brasileira · 9º ano"},"description":"Consulte a página 136. Escolha uma resposta por pergunta.","difficulty":"medio","bncc":[],"status":"draft","template":"quiz","questions":[{"id":"q1","prompt":"A que defesa se relaciona a atuação de Davi Kopenawa no texto?","options":[{"label":"Dos povos e da floresta.","id":"q1-o1"},{"label":"Dos acervos de literatura do século XIX.","id":"q1-o2"},{"label":"Dos circuitos comerciais da costa suaíli.","id":"q1-o3"}],"correctOptionId":"q1-o1","explanation":"O texto situa a atuação dessa liderança e intelectual Yanomami na defesa dos povos e da floresta."},{"id":"q2","prompt":"Que papel é atribuído à Hutukara Associação Yanomami?","options":[{"label":"Uma instituição estatal de representação exclusiva.","id":"q2-o1"},{"label":"Um acervo pessoal de obras literárias.","id":"q2-o2"},{"label":"Espaço coletivo de organização.","id":"q2-o3"}],"correctOptionId":"q2-o3","explanation":"A associação é apresentada como organização coletiva, não como extensão de uma trajetória individual."},{"id":"q3","prompt":"Segundo o caso estudado, o que sustenta a atuação de Davi Kopenawa como uma voz pública?","options":[{"label":"Ela substitui todas as organizações indígenas.","id":"q3-o1"},{"label":"Ela se apoia em experiências, responsabilidades e redes.","id":"q3-o2"},{"label":"Ela dispensa relações com comunidades.","id":"q3-o3"}],"correctOptionId":"q3-o2","explanation":"Ligar Kopenawa à organização coletiva ajuda a compreender as redes que sustentam sua atuação."}]}','ad94cce603cb774fac62fb6d9aadda4b89f2fd34cdb21076d6b5856358485fb8',true);
